def _candidate_source_bound_router_refusal_signed_self_lock_can_rederive(
    candidate: "AllocatorCandidate",
    reason: str,
) -> bool:
    """Resolve a stale outer self-lock only from a valid signed-true triplet."""

    reason = _text(reason)
    if reason != "source_bound_router_refusal_requires_signed_new_entry_authority":
        return False
    metadata = _mapping(candidate.metadata)
    if not _candidate_package_source_bound_executable_present(candidate):
        return False
    for surface in _package_authority_validation_surfaces(metadata):
        if not _compact_signed_new_entry_authority_claim_valid(metadata, surface):
            continue
        payload = _mapping(surface.get("package_new_entry_authority_payload"))
        if _text(payload.get("authority_family")) != "router_refusal_softening":
            continue
        signed_allowed, _, _ = _signed_order_executable_triplet(payload)
        if signed_allowed is not True:
            continue
        if _text(payload.get("selector_reason")) != (
            "source_bound_router_refusal_open_reduced_materialized_for_replay"
        ):
            continue
        if not _predecision_no_outcome_boundary(payload.get("source_boundary")):
            continue
        if not _truthy(payload.get("source_bound_package_candidate_use_allowed")):
            continue
        return True
    return False


def _signed_package_new_entry_authority_scalar_valid(row: Mapping[str, Any]) -> bool:
    payload = _mapping(row.get("package_new_entry_authority_payload"))
    payload_action = _normalize_action_intent(payload.get("target_action_intent"))
    return bool(
        _truthy(row.get("package_new_entry_authority_valid"))
        and payload_action in REDUCED_RISK_SIGNED_NEW_ENTRY_ACTIONS
        and _truthy(payload.get("authority_allowed"))
        and _immutable_package_new_entry_authority_payload_valid(row, row)
    )


def _candidate_decision_instance_key(row: Mapping[str, Any]) -> str:
    candidate_id = _text(
        row.get("candidate_id")
        or row.get("package_new_entry_authority_candidate_id")
        or row.get("candidate_row_key")
    )
    decision_time = _text(
        row.get("decision_time_utc")
        or row.get("window_time_utc")
        or row.get("candle_close_utc")
        or row.get("source_candle_time_utc")
        or row.get("package_new_entry_authority_decision_time_utc")
    )
    if not candidate_id or not decision_time:
        return ""
    return f"{candidate_id}@@{decision_time}"


def _candidate_package_executable_authority(
    candidate: "AllocatorCandidate",
    broker_cost_rank: Mapping[str, Any],
    *,
    source_bound_executable_present: bool | None = None,
    source_completeness_floor: float = 0.95,
    expected_net_r: float | None = None,
    probability: float | None = None,
    fill_probability: float | None = None,
    source_completeness: float | None = None,
    source_completeness_status: str | None = None,
) -> tuple[bool, str, str]:
    explicit_executable = _explicit_package_executable_value(candidate.metadata)
    if explicit_executable is not None:
        allowed = _truthy(explicit_executable)
        reason = _text(
            candidate.metadata.get("package_replay_executable_candidate_use_allowed_reason")
            or candidate.metadata.get("replay_candidate_use_allowed_now_reason")
        )
        source_bound_self_lock = (
            reason
            in {
                "ultimate_package_effective_source_bound_not_allowed",
                "source_bound_package_replay_not_allowed",
                "package_source_bound_not_allowed",
                "source_bound_package_candidate_use_not_allowed",
            }
            and _candidate_package_source_bound_executable_present(candidate)
        )
        owner_approved_family_root_self_lock = (
            reason in _OWNER_APPROVED_FAMILY_ROOT_STALE_FALSE_REASONS
            and _owner_approved_family_root_admission_valid(candidate.metadata)
        )
        router_refusal_signed_self_lock = (
            _candidate_source_bound_router_refusal_signed_self_lock_can_rederive(
                candidate,
                reason,
            )
        )
        cost_block_reason = (
            _candidate_broker_cost_non_executable_reason(broker_cost_rank)
            if not allowed
            else None
        )
        if cost_block_reason:
            return False, cost_block_reason, "broker_cost_authority_blocked"
        if (
            not allowed
            and (
                _explicit_package_false_reason_can_be_rederived(reason)
                or source_bound_self_lock
                or owner_approved_family_root_self_lock
                or router_refusal_signed_self_lock
            )
        ):
            derived_allowed, derived_reason = _candidate_derived_package_executable_authority(
                candidate,
                broker_cost_rank,
                source_bound_executable_present=(
                    source_bound_executable_present
                    if source_bound_executable_present is not None
                    else True
                    if (
                        router_refusal_signed_self_lock
                        or owner_approved_family_root_self_lock
                    )
                    else None
                ),
                source_completeness_floor=source_completeness_floor,
                expected_net_r=expected_net_r,
                probability=probability,
                fill_probability=fill_probability,
                source_completeness=source_completeness,
                source_completeness_status=source_completeness_status,
            )
            return (
                derived_allowed,
                derived_reason
                if derived_allowed
                else (
                    "explicit_package_replay_executable_self_lock_"
                    f"revalidated_failed:{derived_reason}"
                ),
                (
                    "derived_after_source_bound_router_refusal_signed_authority_self_lock"
                    if router_refusal_signed_self_lock
                    else "derived_after_owner_approved_family_root_self_lock"
                    if owner_approved_family_root_self_lock
                    else "derived_after_selector_reduce_risk_materialization_self_lock"
                ),
        )
        if allowed:
            provenance_failures = _candidate_quality_hard_execution_failures(candidate)
            if provenance_failures:
                return (
                    False,
                    "explicit_package_replay_executable_rejected:"
                    "candidate_decision_quality_provenance_missing:"
                    + ",".join(provenance_failures),
                    "explicit_package_replay_executable_revalidated_failed",
                )
            derived_allowed, derived_reason = _candidate_derived_package_executable_authority(
                candidate,
                broker_cost_rank,
                source_bound_executable_present=source_bound_executable_present,
                source_completeness_floor=source_completeness_floor,
                expected_net_r=expected_net_r,
                probability=probability,
                fill_probability=fill_probability,
                source_completeness=source_completeness,
                source_completeness_status=source_completeness_status,
                strict_quality_provenance=False,
            )
            if not derived_allowed:
                return (
                    False,
                    f"explicit_package_replay_executable_rejected:{derived_reason}",
                    "explicit_package_replay_executable_revalidated_failed",
                )
        return (
            allowed,
            reason
            or (
                "explicit_package_replay_executable_authority_allowed"
                if allowed
                else "explicit_package_replay_executable_authority_false"
            ),
            "explicit_package_replay_executable_or_replay_candidate_use_allowed_now",
        )
    derived_allowed, derived_reason = _candidate_derived_package_executable_authority(
        candidate,
        broker_cost_rank,
        source_bound_executable_present=source_bound_executable_present,
        source_completeness_floor=source_completeness_floor,
        expected_net_r=expected_net_r,
        probability=probability,
        fill_probability=fill_probability,
        source_completeness=source_completeness,
        source_completeness_status=source_completeness_status,
    )
    return (
        derived_allowed,
        derived_reason,
        "derived_predecision_quality_source_cost_authority"
        if derived_allowed
        else "missing_explicit_or_derived_package_executable_authority",
    )


def _str_tuple(value: Any, default: Sequence[str] = ()) -> tuple[str, ...]:
    if value in (None, ""):
        return tuple(default)
    if isinstance(value, str):
        raw_items = value.split(",")
    elif isinstance(value, Sequence) and not isinstance(value, (bytes, bytearray)):
        raw_items = value
    else:
        raw_items = (value,)
    return tuple(item for item in (_lower(raw) for raw in raw_items) if item)


def _num(value: Any, default: float | None = None) -> float | None:
    if value in (None, "") or isinstance(value, bool):
        return default
    try:
        number = float(value)
    except (TypeError, ValueError):
        return default
    if number != number or number in (float("inf"), float("-inf")):
        return default
    return number


def _broker_cost_passed_for_bounded_risk_intent(row: Mapping[str, Any]) -> bool:
    packet = _pretrade_cost_packet(row)
    status = _text(packet.get("status")).upper()
    source_gap_status = _text(packet.get("cost_source_gap_status"))
    fallback_is_authority = _truthy(
        packet.get("candidate_cost_r_fallback_is_authority")
    )
    authority = _lower(packet.get("authority"))
    return bool(
        status in {"PASSED", "PASS", "OK"}
        and source_gap_status in {"", "source_bound_cost_authority_present"}
        and not fallback_is_authority
        and not tuple(packet.get("atomic_conflicts") or ())
        and row.get("broker_pretrade_cost_executable") is not False
        and authority != "timewarp_candidate_cost_proxy"
    )




def _exact_package_candidate_time_binding_present(row: Mapping[str, Any]) -> bool:
    expected_key = _candidate_decision_instance_key(row)
    if not expected_key:
        return False
    canonical_key = _text(row.get("canonical_replay_candidate_instance_key"))
    source_bound_key = _text(row.get("source_bound_replay_candidate_instance_key"))
    if canonical_key != expected_key or source_bound_key != expected_key:
        return False
    probe_key = _text(row.get("risk_finalizer_probe_instance_key"))
    if probe_key and probe_key != expected_key:
        return False
    if not _candidate_identity_status_is_materialized(
        row.get("candidate_instance_identity_status")
    ):
        return False
    return _signed_authority_reconstitutes_source_bound_use(row)


def _bounded_package_risk_per_trade_pct_request(
    row: Mapping[str, Any],
) -> tuple[float | None, str]:
    """Recover signed reduced-risk intent when explicit selected-cell aliases are zero."""

    risk_per_trade = _num(row.get("risk_per_trade_pct"))
    if risk_per_trade is None or risk_per_trade <= 0.0:
        return None, ""
    selector_action = (
        _materialized_selector_action(row)
        or _lower(row.get("effective_selector_action"))
        or _raw_selector_action(row)
    )
    if selector_action not in REDUCED_RISK_NEW_ENTRY_SELECTOR_ACTIONS:
        return None, ""
    open_reduced_authority = _mapping(
        row.get("ultimate_candidate_package_open_reduced_risk_authority")
    )
    reduce_risk_authority = _mapping(
        row.get("ultimate_candidate_package_reduce_risk_authority")
        or row.get("ultimate_candidate_package_reduced_risk_authority")
    )
    signed_authority_valid = bool(
        _exact_package_candidate_time_binding_present(row)
        and (
            _signed_package_new_entry_authority_scalar_valid(row)
            or _signed_new_entry_authority_claim_valid(row, open_reduced_authority)
            or _signed_new_entry_authority_claim_valid(row, reduce_risk_authority)
        )
    )
    if not signed_authority_valid:
        return None, ""
    if not (
        _truthy(row.get("package_replay_executable_candidate_use_allowed"))
        or _truthy(row.get("replay_candidate_use_allowed_now"))
        or _truthy(row.get("risk_finalizer_package_replay_executable_candidate_use_allowed"))
    ):
        return None, ""
    if not _source_completeness_clean_for_execution(
        row.get("source_completeness"),
        row.get("source_completeness_status"),
        floor=0.95,
    ):
        return None, ""
    if not _broker_cost_passed_for_bounded_risk_intent(row):
        return None, ""
    return risk_per_trade, "bounded_package_risk_per_trade_pct"


def _candidate_requested_risk_pct_with_source(
    row: Mapping[str, Any],
) -> tuple[float | None, str]:
    """Return explicit replay risk intent without inferring from final approvals."""

    nonpositive_source = ""
    nonpositive_value: float | None = None
    flat_sources = (
        ("requested_risk_pct", row.get("requested_risk_pct")),
        ("selected_cell_risk_pct", row.get("selected_cell_risk_pct")),
        ("scheduler_requested_risk_pct", row.get("scheduler_requested_risk_pct")),
        ("scheduler_selected_risk_pct", row.get("scheduler_selected_risk_pct")),
        ("requested_replay_risk_pct", row.get("requested_replay_risk_pct")),
        ("package_requested_risk_pct", row.get("package_requested_risk_pct")),
        ("risk_pct", row.get("risk_pct")),
    )
    for source, value in flat_sources:
        number = _num(value)
        if number is not None:
            if number > 0.0:
                return number, source
            if not nonpositive_source:
                nonpositive_source = source
                nonpositive_value = number

    nested_sources = (
        ("risk_expression_ladder", row.get("risk_expression_ladder")),
        ("finalizer_primary_probe_risk_expression_ladder", row.get("finalizer_primary_probe_risk_expression_ladder")),
        ("scorecard_reported_risk_expression_ladder", row.get("scorecard_reported_risk_expression_ladder")),
        ("risk_authority", row.get("risk_authority")),
        ("risk_authority_packet", row.get("risk_authority_packet")),
        ("selected_cell_risk_authority", row.get("selected_cell_risk_authority")),
    )
    nested_keys = (
        "requested_risk_pct",
        "selected_cell_risk_pct",
        "scheduler_requested_risk_pct",
        "package_requested_risk_pct",
    )
    for source, container in nested_sources:
        packet = _mapping(container)
        if not packet:
            continue
        for key in nested_keys:
            number = _num(packet.get(key))
            if number is not None:
                if number > 0.0:
                    return number, f"{source}.{key}"
                if not nonpositive_source:
                    nonpositive_source = f"{source}.{key}"
                    nonpositive_value = number
    bounded_value, bounded_source = _bounded_package_risk_per_trade_pct_request(row)
    if bounded_value is not None:
        return bounded_value, bounded_source
    if nonpositive_source:
        return nonpositive_value, nonpositive_source
    return None, ""


def _first_num(row: Mapping[str, Any], *keys: str) -> float | None:
    """Return the first parseable numeric across alias keys, preserving 0.0."""

    for key in keys:
        value = _num(row.get(key))
        if value is not None:
            return value
    return None


def _first_text(row: Mapping[str, Any], *keys: str) -> str | None:
    """Return the first non-empty text across alias keys."""

    for key in keys:
        value = _text(row.get(key))
        if value:
            return value
    return None


def _first_num_from_sources(
    sources: Sequence[Mapping[str, Any]],
    *keys: str,
) -> float | None:
    for source in sources:
        value = _first_num(source, *keys)
        if value is not None:
            return value
    return None


def _first_text_from_sources(
    sources: Sequence[Mapping[str, Any]],
    *keys: str,
) -> str | None:
    for source in sources:
        value = _first_text(source, *keys)
        if value:
            return value
    return None


def _candidate_decision_inputs(row: Mapping[str, Any]) -> Mapping[str, Any]:
    for key in (
        "scheduler_candidate_decision_inputs",
        "candidate_decision_inputs",
        "decision_inputs",
    ):
        value = _mapping(row.get(key))
        if value:
            return value
    components = _mapping(row.get("score_components"))
    return _mapping(components.get("candidate_decision_inputs"))


def _value_is_present(value: Any) -> bool:
    return value is not None and value != "" and value != [] and value != {}


def _first_present_source_label(
    sources: Sequence[tuple[str, Mapping[str, Any]]],
    *keys: str,
) -> str | None:
    for source_name, source in sources:
        for key in keys:
            if _value_is_present(source.get(key)):
                return f"{source_name}.{key}"
    return None


def _raw_config_lookup(raw_config: Mapping[str, Any], key: str) -> Any:
    runtime_config = _mapping(raw_config.get("gtos_vnext_runtime"))
    if key in raw_config:
        return raw_config.get(key)
    if key in runtime_config:
        return runtime_config.get(key)
    return None


def _package_execution_authority_enabled(raw_config: Mapping[str, Any]) -> bool:
    return bool(
        _truthy(
            _raw_config_lookup(
                raw_config,
                "ultimate_candidate_package_final_package_selected",
            )
        )
        and _truthy(
            _raw_config_lookup(
                raw_config,
                "ultimate_candidate_package_apply_to_execution",
            )
        )
        and _truthy(
            _raw_config_lookup(
                raw_config,
                "ultimate_candidate_package_live_activation_allowed",
            )
        )
    )


def _option_requires_package_runtime_authority(option: "AllocatorOption") -> bool:
    components = _mapping(option.score_components)
    decision_inputs = _mapping(components.get("candidate_decision_inputs"))
    selector_action = _lower(decision_inputs.get("selector_action"))
    if selector_action in {"open-reduced-risk", "source-required"}:
        return True
    if selector_action == "reduce-risk" and option.action_class in NEW_RISK_ACTIONS:
        return True
    package_boolean_fields = (
        "ultimate_package_source_bound_candidate_use_allowed",
        "source_bound_package_candidate_use_allowed",
        "package_replay_candidate_use_allowed",
        "package_replay_executable_candidate_use_allowed",
        "ultimate_package_admission_candidate_use_allowed",
    )
    if any(_truthy(decision_inputs.get(field)) for field in package_boolean_fields):
        return True
    package_authority_fields = (
        "ultimate_candidate_package_open_reduced_risk_authority",
        "ultimate_candidate_package_reduce_risk_authority",
        "ultimate_candidate_package_reduced_risk_authority",
    )
    return any(
        bool(_mapping(decision_inputs.get(field)))
        for field in package_authority_fields
    )


def _pretrade_cost_packet(row: Mapping[str, Any]) -> Mapping[str, Any]:
    row = _mapping(row)
    packet = _mapping(
        row.get("pretrade_broker_net_cost_packet")
        or row.get("pretrade_cost_packet")
        or row.get("pretrade_cost_model")
        or row.get("gtos_vnext_pretrade_cost_model")
    )
    if not packet:
        return {
            "status": row.get("pretrade_cost_packet_status"),
            "authority": _first_present_value(
                row.get("cost_authority"),
                row.get("execution_cost_authority"),
            ),
            "cost_source_gap_status": row.get("cost_source_gap_status"),
            "candidate_cost_r_fallback_is_authority": row.get(
                "candidate_cost_r_fallback_is_authority"
            ),
            "source_gap_cost_fallback_blocked": row.get(
                "source_gap_cost_fallback_blocked"
            ),
            "refusal_reasons": row.get("pretrade_cost_refusal_reasons"),
            "total_cost_r": _first_present_value(
                row.get("broker_pretrade_cost_r"),
                row.get("broker_calibrated_expected_cost_r"),
                row.get("expected_cost_r"),
                row.get("cost_total_r"),
                row.get("cost_r"),
            ),
            "atomic_nested_cost_packet": False,
            "atomic_conflicts": (),
        }
    scalar_fields = _mapping(packet.get("scalar_fields"))
    merged = dict(packet)
    conflicts: list[str] = []
    for key, value in scalar_fields.items():
        if value in (None, "", [], {}):
            continue
        if key in {
            "status",
            "authority",
            "cost_source_gap_status",
            "candidate_cost_r_fallback_is_authority",
            "source_gap_cost_fallback_blocked",
            "refusal_reasons",
        } and packet.get(key) not in (None, "", [], {}):
            if packet.get(key) != value:
                conflicts.append(f"scalar_fields.{key}")
            continue
        merged[key] = value
    outer_aliases = {
        "status": ("pretrade_cost_packet_status",),
        "authority": ("cost_authority", "execution_cost_authority"),
        "cost_source_gap_status": ("cost_source_gap_status",),
        "candidate_cost_r_fallback_is_authority": (
            "candidate_cost_r_fallback_is_authority",
        ),
        "refusal_reasons": ("pretrade_cost_refusal_reasons",),
        "total_cost_r": (
            "broker_pretrade_cost_r",
            "broker_calibrated_expected_cost_r",
            "expected_cost_r",
            "cost_total_r",
            "cost_r",
        ),
    }
    for packet_key, aliases in outer_aliases.items():
        packet_value = merged.get(packet_key)
        outer_value = _first_present_value(*(row.get(alias) for alias in aliases))
        if packet_value in (None, "") or outer_value in (None, ""):
            continue
        if packet_key == "status":
            equal = _text(packet_value).upper() == _text(outer_value).upper()
        elif packet_key == "candidate_cost_r_fallback_is_authority":
            equal = _truthy(packet_value) == _truthy(outer_value)
        elif packet_key == "total_cost_r":
            left = _num(packet_value)
            right = _num(outer_value)
            equal = bool(
                left is not None
                and right is not None
                and abs(left - right) <= 0.000000001
            )
        else:
            equal = _canonical_hash_payload(packet_value) == _canonical_hash_payload(
                outer_value
            )
        if not equal:
            conflicts.append(packet_key)
    merged["atomic_nested_cost_packet"] = True
    merged["atomic_conflicts"] = tuple(dict.fromkeys(conflicts))
    return merged


_ATOMIC_EXECUTION_FILLABILITY_FLAT_VALUE_FIELDS = (
    "pending_limit_fillability_probability",
    "pending_fill_probability",
    "predecision_limit_fillability_probability",
    "limit_fillability_probability",
    "limit_fill_probability",
)
_ATOMIC_EXECUTION_FILLABILITY_NESTED_VALUE_FIELDS = (
    "fill_probability",
    "expected_fill_probability",
    "limit_fill_probability",
    "limit_fillability_probability",
    "probability",
)
_ATOMIC_EXECUTION_FILLABILITY_DIRECT_VALUE_FIELDS = (
    "execution_fill_probability",
    "package_risk_expression_execution_fill_probability",
    "risk_finalizer_execution_fill_probability",
    "causal_finalizer_candidate_fill_probability",
)


def execution_fillability_source_is_authoritative(
    source: Any,
    authority_class: Any = None,
) -> bool:
    """Accept only predecision order, limit, or pending fillability provenance."""

    source_text = _text(source).lower().replace("-", "_")
    authority_text = _text(authority_class).lower().replace("-", "_")
    if not source_text:
        return False
    combined = f"{source_text} {authority_text}"
    if any(
        marker in combined
        for marker in (
            "not_predecision",
            "fallback",
            "heuristic",
            "candidate_fill",
            "entry_quality",
            "synthetic",
            "proxy",
            "inferred",
            "generic",
            "model",
            "unknown",
            "postdecision",
            "post_decision",
            "posttrade",
            "post_trade",
            "broker_real",
            "broker_live",
            "future",
            "realized",
            "outcome",
            "after_fill",
            "after_trade",
            "observed_quote",
            "executed_fill",
            "observed_fill",
            "actual_fill",
        )
    ):
        return False
    if any(
        marker in source_text
        for marker in (
            "predecision_limit_fill",
            "predecision_pending_fill",
            "predecision_order_fill",
            "pending_limit_fill",
            "pending_fill_probability",
        )
    ):
        return True
    return source_text in {
        "limit_fillability_probability",
        "limit_fill_probability",
    } or source_text.endswith(
        (
            ".limit_fillability_probability",
            ".limit_fill_probability",
        )
    )


def _execution_fillability_source_family(source: Any) -> str | None:
    source_text = _text(source).lower().replace("-", "_")
    if "predecision_limit_fill" in source_text:
        return "predecision_limit_fillability"
    if any(
        marker in source_text
        for marker in (
            "predecision_pending_fill",
            "pending_limit_fill",
            "pending_fill_probability",
        )
    ):
        return "pending_limit_fillability"
    if "predecision_order_fill" in source_text:
        return "predecision_order_fillability"
    if source_text in {
        "limit_fillability_probability",
        "limit_fill_probability",
    } or source_text.endswith(
        (
            ".limit_fillability_probability",
            ".limit_fill_probability",
        )
    ):
        return "predecision_limit_fillability"
    return None


def _atomic_predecision_execution_fillability_claim(
    row: Mapping[str, Any],
) -> dict[str, Any]:
    """Resolve one temporally bound execution-fillability claim per envelope."""

    row = row if isinstance(row, Mapping) else {}
    decision_inputs = _mapping(row.get("candidate_decision_inputs"))
    outer_decision_time = _first_present_value(
        row.get("decision_time_utc"),
        row.get("asof_utc"),
        row.get("candle_close_utc"),
        row.get("source_candle_time_utc"),
        decision_inputs.get("decision_time_utc"),
        decision_inputs.get("asof_utc"),
    )
    named_surfaces: list[tuple[str, Mapping[str, Any]]] = []
    seen_surfaces: set[int] = set()
    for name, surface in (
        (
            "candidate_decision_inputs.candidate_decision_quality",
            _mapping(decision_inputs.get("candidate_decision_quality")),
        ),
        ("candidate_decision_quality", _mapping(row.get("candidate_decision_quality"))),
        ("candidate_decision_inputs", decision_inputs),
        ("row", row),
    ):
        if not surface or id(surface) in seen_surfaces:
            continue
        seen_surfaces.add(id(surface))
        named_surfaces.append((name, surface))

    claims: list[dict[str, Any]] = []
    for surface_name, surface in named_surfaces:
        decision_time = _first_present_value(
            surface.get("decision_time_utc"),
            surface.get("asof_utc"),
            surface.get("candle_close_utc"),
            surface.get("source_candle_time_utc"),
            outer_decision_time,
        )
        explicit_source = _text(
            _first_present_value(
                surface.get("execution_fill_probability_source"),
                surface.get(
                    "package_new_entry_authority_execution_fill_probability_source"
                ),
                surface.get("execution_fillability_source"),
                surface.get(
                    "package_risk_expression_execution_fill_probability_source"
                ),
                surface.get("risk_finalizer_execution_fill_probability_source"),
                surface.get("causal_finalizer_candidate_fill_probability_source"),
            )
        )
        explicit_authority_class = _text(
            _first_present_value(
                surface.get("execution_fill_probability_authority_class"),
                surface.get("execution_fillability_authority_class"),
                surface.get(
                    "package_risk_expression_execution_fill_probability_authority_class"
                ),
                surface.get(
                    "risk_finalizer_execution_fill_probability_authority_class"
                ),
                surface.get(
                    "causal_finalizer_candidate_fill_probability_authority_class"
                ),
            )
        )
        flat_source_time = _first_present_value(
            surface.get("execution_fill_probability_source_time_utc"),
            surface.get(
                "package_new_entry_authority_execution_fill_probability_source_time_utc"
            ),
            surface.get("execution_fillability_source_time_utc"),
            surface.get(
                "package_risk_expression_execution_fill_probability_source_time_utc"
            ),
            surface.get("risk_finalizer_execution_fill_probability_source_time_utc"),
            surface.get(
                "causal_finalizer_candidate_fill_probability_source_time_utc"
            ),
            surface.get("predecision_limit_fillability_source_time_utc"),
            surface.get("predecision_current_price_source_time_utc"),
            surface.get("current_price_source_time_utc"),
        )
        flat_boundary = _first_present_value(
            surface.get("execution_fill_probability_source_boundary"),
            surface.get(
                "package_new_entry_authority_execution_fill_probability_source_boundary"
            ),
            surface.get("execution_fillability_source_boundary"),
            surface.get(
                "package_risk_expression_execution_fill_probability_source_boundary"
            ),
            surface.get("risk_finalizer_execution_fill_probability_source_boundary"),
            surface.get(
                "causal_finalizer_candidate_fill_probability_source_boundary"
            ),
            surface.get("predecision_limit_fillability_source_boundary"),
            surface.get("predecision_current_price_source_boundary"),
            surface.get("current_price_source_boundary"),
        )
        nested_provenance = _mapping(
            surface.get("predecision_limit_fillability")
        )
        nested_provenance_value = _num(
            _first_present_value(
                *(
                    nested_provenance.get(key)
                    for key in _ATOMIC_EXECUTION_FILLABILITY_NESTED_VALUE_FIELDS
                )
            )
        )
        nested_provenance_source = _text(
            _first_present_value(
                nested_provenance.get("execution_fill_probability_source"),
                nested_provenance.get("fill_probability_source"),
                nested_provenance.get("limit_fillability_source"),
                nested_provenance.get("source"),
            )
        )
        nested_provenance_authority_class = _text(
            _first_present_value(
                nested_provenance.get(
                    "execution_fill_probability_authority_class"
                ),
                nested_provenance.get("fill_probability_authority_class"),
                nested_provenance.get("authority_class"),
            )
        )
        nested_provenance_source_time = _first_present_value(
            nested_provenance.get("current_price_source_time_utc"),
            nested_provenance.get("source_time_utc"),
        )
        nested_provenance_boundary = _first_present_value(
            nested_provenance.get("current_price_source_boundary"),
            nested_provenance.get("source_boundary"),
        )
        explicit_source_authoritative = execution_fillability_source_is_authoritative(
            explicit_source,
            explicit_authority_class,
        )

        def nested_provenance_for_equal_value(value: float) -> dict[str, Any]:
            if (
                nested_provenance_value is None
                or round(float(value), 12)
                != round(float(nested_provenance_value), 12)
            ):
                return {}
            return {
                "source": nested_provenance_source
                or "predecision_limit_fillability.fill_probability",
                "source_time_utc": nested_provenance_source_time,
                "source_boundary": nested_provenance_boundary,
                "authority_class": nested_provenance_authority_class
                or "predecision_passive_limit_fillability_authority",
            }

        for key in _ATOMIC_EXECUTION_FILLABILITY_FLAT_VALUE_FIELDS:
            value = _num(surface.get(key))
            if value is None:
                continue
            inherited = nested_provenance_for_equal_value(value)
            claims.append(
                {
                    "value": _clamp(value, 0.0, 1.0),
                    "source": (
                        explicit_source
                        if explicit_source_authoritative
                        else inherited.get("source")
                        or explicit_source
                        or key
                    ),
                    "source_time_utc": (
                        flat_source_time
                        if flat_source_time not in (None, "")
                        else inherited.get("source_time_utc")
                    ),
                    "source_boundary": (
                        flat_boundary
                        if flat_boundary not in (None, "")
                        else inherited.get("source_boundary")
                    ),
                    "decision_time_utc": decision_time,
                    "surface": f"{surface_name}.{key}",
                    "available": not (
                        "predecision_limit_fillability_available" in surface
                        and not _truthy(
                            surface.get("predecision_limit_fillability_available")
                        )
                    ),
                    "authority_class": (
                        explicit_authority_class
                        or "predecision_passive_limit_fillability_authority"
                        if explicit_source_authoritative
                        else inherited.get("authority_class")
                        or "predecision_passive_limit_fillability_authority"
                    ),
                }
            )
        direct_source_authoritative = explicit_source_authoritative
        for key in _ATOMIC_EXECUTION_FILLABILITY_DIRECT_VALUE_FIELDS:
            direct_value = _num(surface.get(key))
            if direct_value is None:
                continue
            inherited = nested_provenance_for_equal_value(direct_value)
            claims.append(
                {
                    "value": _clamp(direct_value, 0.0, 1.0),
                    "source": (
                        explicit_source
                        if direct_source_authoritative
                        else inherited.get("source")
                        or explicit_source
                        or None
                    ),
                    "source_time_utc": (
                        flat_source_time
                        if flat_source_time not in (None, "")
                        else inherited.get("source_time_utc")
                    ),
                    "source_boundary": (
                        flat_boundary
                        if flat_boundary not in (None, "")
                        else inherited.get("source_boundary")
                    ),
                    "decision_time_utc": decision_time,
                    "surface": f"{surface_name}.{key}",
                    "available": not (
                        "predecision_limit_fillability_available" in surface
                        and not _truthy(
                            surface.get("predecision_limit_fillability_available")
                        )
                    ),
                    "authority_class": (
                        explicit_authority_class
                        or (
                            "predecision_passive_limit_fillability_authority"
                            if direct_source_authoritative
                            and _execution_fillability_source_family(explicit_source)
                            in {
                                "predecision_limit_fillability",
                                "pending_limit_fillability",
                            }
                            else "predecision_execution_fillability_alias"
                            if direct_source_authoritative
                            else inherited.get("authority_class")
                            or "unbound_direct_execution_fillability_alias"
                        )
                    ),
                }
            )

        nested = _mapping(surface.get("predecision_limit_fillability"))
        if nested:
            nested_declared_source = _text(
                _first_present_value(
                    nested.get("execution_fill_probability_source"),
                    nested.get("fill_probability_source"),
                    nested.get("limit_fillability_source"),
                    nested.get("source"),
                )
            )
            nested_declared_authority_class = _text(
                _first_present_value(
                    nested.get("execution_fill_probability_authority_class"),
                    nested.get("fill_probability_authority_class"),
                    nested.get("authority_class"),
                )
            )
            outer_execution_source_authoritative = (
                execution_fillability_source_is_authoritative(
                    explicit_source,
                    explicit_authority_class,
                )
            )
            inherited_execution_source = (
                explicit_source if outer_execution_source_authoritative else ""
            )
            inherited_execution_authority_class = (
                explicit_authority_class
                if outer_execution_source_authoritative
                else "predecision_passive_limit_fillability_authority"
            )
            nested_source_time = _first_present_value(
                nested.get("current_price_source_time_utc"),
                nested.get("source_time_utc"),
                flat_source_time,
            )
            nested_boundary = _first_present_value(
                nested.get("current_price_source_boundary"),
                nested.get("source_boundary"),
                flat_boundary,
            )
            nested_available = not (
                "available" in nested and not _truthy(nested.get("available"))
            )
            nested_uses_outcome_fields = bool(
                _truthy(nested.get("uses_outcome_fields"))
                or nested.get("outcome_fields_used") not in (None, "", [], (), {})
            )
            for key in _ATOMIC_EXECUTION_FILLABILITY_NESTED_VALUE_FIELDS:
                value = _num(nested.get(key))
                if value is None:
                    continue
                claims.append(
                    {
                        "value": _clamp(value, 0.0, 1.0),
                        "source": nested_declared_source
                        or inherited_execution_source
                        or f"predecision_limit_fillability.{key}",
                        "source_time_utc": nested_source_time,
                        "source_boundary": nested_boundary,
                        "decision_time_utc": decision_time,
                        "surface": (
                            f"{surface_name}.predecision_limit_fillability.{key}"
                        ),
                        "available": nested_available,
                        "uses_outcome_fields": nested_uses_outcome_fields,
                        "authority_class": (
                            nested_declared_authority_class
                            or inherited_execution_authority_class
                        ),
                    }
                )

    if not claims:
        return {
            "value": None,
            "source": None,
            "source_time_utc": None,
            "source_boundary": None,
            "decision_time_utc": outer_decision_time,
            "surface": None,
            "authority_class": None,
            "failure": None,
            "atomic_conflicts": (),
        }
    distinct_values = sorted({round(float(claim["value"]), 12) for claim in claims})
    if len(distinct_values) > 1:
        return {
            "value": None,
            "source": None,
            "source_time_utc": None,
            "source_boundary": None,
            "decision_time_utc": outer_decision_time,
            "surface": None,
            "authority_class": None,
            "failure": "predecision_limit_fillability_atomic_value_conflict",
            "atomic_conflicts": tuple(
                f"{claim['surface']}={_round(claim['value'])}" for claim in claims
            ),
        }

    valid_claims: list[dict[str, Any]] = []
    invalid_claims: list[tuple[dict[str, Any], str]] = []
    for claim in claims:
        failure = None
        if not claim["available"]:
            failure = "predecision_limit_fillability_explicitly_unavailable"
        if failure is None and claim.get("uses_outcome_fields"):
            failure = "predecision_limit_fillability_uses_outcome_fields"
        boundary = _text(claim["source_boundary"])
        if failure is None and not boundary:
            failure = "predecision_limit_fillability_source_boundary_missing"
        if (
            failure is None
            and not predecision_execution_fillability_source_boundary_allowed(boundary)
        ):
            failure = "predecision_limit_fillability_source_boundary_unsafe"
        source_time = parse_dt(claim["source_time_utc"])
        decision_time = parse_dt(claim["decision_time_utc"])
        if failure is None and source_time is None:
            failure = "predecision_limit_fillability_source_time_missing_or_invalid"
        if failure is None and decision_time is None:
            failure = "predecision_limit_fillability_decision_time_missing_or_invalid"
        if failure is None and source_time >= decision_time:
            failure = "predecision_limit_fillability_source_time_not_before_decision"
        if failure is None and not _text(claim["source"]):
            failure = "execution_fill_probability_source_missing"
        if failure is None and not execution_fillability_source_is_authoritative(
            claim["source"],
            claim["authority_class"],
        ):
            failure = "execution_fill_probability_source_unrecognized"
        if failure is not None:
            invalid_claims.append((claim, failure))
            continue
        valid_claims.append(
            {
                **claim,
                "source_family": _execution_fillability_source_family(
                    claim["source"]
                ),
                "source_time_utc": source_time.isoformat(),
                "source_boundary": boundary,
                "decision_time_utc": decision_time.isoformat(),
            }
        )

    if invalid_claims:
        invalid_failures = tuple(dict.fromkeys(failure for _, failure in invalid_claims))
        failure = (
            "predecision_limit_fillability_atomic_provenance_conflict"
            if valid_claims or len(invalid_failures) > 1
            else invalid_failures[0]
        )
        return {
            **claims[0],
            "value": None,
            "source": None,
            "source_time_utc": None,
            "source_boundary": None,
            "surface": None,
            "authority_class": None,
            "failure": failure,
            "atomic_conflicts": tuple(
                f"{claim['surface']}:{claim_failure}"
                for claim, claim_failure in invalid_claims
            ),
        }

    normalized_tuples = {
        (
            round(float(claim["value"]), 12),
            claim["source_family"],
            claim["source_time_utc"],
                _lower(claim["source_boundary"])
                .replace("-", "_")
                .replace(" ", "_"),
            claim["decision_time_utc"],
            bool(claim["available"]),
        )
        for claim in valid_claims
    }
    if len(normalized_tuples) > 1:
        return {
            **claims[0],
            "value": None,
            "source": None,
            "source_time_utc": None,
            "source_boundary": None,
            "surface": None,
            "authority_class": None,
            "failure": "predecision_limit_fillability_atomic_provenance_conflict",
            "atomic_conflicts": tuple(
                f"{claim['surface']}="
                f"{claim['source_family']}@{claim['source_time_utc']}#"
                f"{claim['source_boundary']}"
                for claim in valid_claims
            ),
        }

    selected_claim = valid_claims[0]
    selected_claim.pop("source_family", None)
    return {
        **selected_claim,
        "failure": None,
        "atomic_conflicts": (),
    }


def _normalized_candidate_quality_fields(
    row: Mapping[str, Any],
) -> dict[str, Any]:
    """Normalize pre-decision quality aliases used by scheduler scoring."""

    decision_inputs = _candidate_decision_inputs(row)
    decision_quality = _mapping(decision_inputs.get("candidate_decision_quality"))
    row_quality = _mapping(row.get("candidate_decision_quality"))
    explicit_quality = decision_quality or row_quality
    candidate_quality_source_boundary = _text(
        _first_present_value(
            explicit_quality.get("candidate_decision_quality_source_boundary"),
            row.get("candidate_decision_quality_source_boundary"),
            decision_inputs.get("candidate_decision_quality_source_boundary"),
            explicit_quality.get("source_boundary"),
        )
    )
    cost_packet = _pretrade_cost_packet(row)
    row_fillability = _mapping(row.get("predecision_limit_fillability"))
    decision_fillability = _mapping(decision_inputs.get("predecision_limit_fillability"))
    geometry = _mapping(row.get("geometry_contract"))
    geometry_scalar_fields = _mapping(geometry.get("scalar_fields"))
    geometry_hash_material = _mapping(geometry.get("source_event_hash_material"))
    decision_geometry = _mapping(decision_inputs.get("geometry_contract"))
    decision_geometry_scalar_fields = _mapping(decision_geometry.get("scalar_fields"))
    decision_geometry_hash_material = _mapping(
        decision_geometry.get("source_event_hash_material")
    )
    fallback_quality_sources = (
        decision_inputs,
        row,
        decision_geometry,
        decision_geometry_scalar_fields,
        decision_geometry_hash_material,
        geometry,
        geometry_scalar_fields,
        geometry_hash_material,
    )
    quality_sources = (
        (explicit_quality, *fallback_quality_sources)
        if explicit_quality
        else fallback_quality_sources
    )
    cost_sources = (
        (cost_packet,)
        if cost_packet.get("atomic_nested_cost_packet")
        else (explicit_quality, cost_packet, decision_inputs, row)
        if explicit_quality
        else (cost_packet, decision_inputs, row)
    )
    fallback_named_quality_sources = (
        ("candidate_decision_inputs", decision_inputs),
        ("row", row),
        ("candidate_decision_inputs.geometry_contract", decision_geometry),
        (
            "candidate_decision_inputs.geometry_contract.scalar_fields",
            decision_geometry_scalar_fields,
        ),
        (
            "candidate_decision_inputs.geometry_contract.source_event_hash_material",
            decision_geometry_hash_material,
        ),
        ("row.geometry_contract", geometry),
        ("row.geometry_contract.scalar_fields", geometry_scalar_fields),
        ("row.geometry_contract.source_event_hash_material", geometry_hash_material),
    )
    named_quality_sources = (
        (("candidate_decision_quality", explicit_quality), *fallback_named_quality_sources)
        if explicit_quality
        else fallback_named_quality_sources
    )
    named_limit_fillability_sources = (
        (
            ("candidate_decision_quality", explicit_quality),
            ("candidate_decision_inputs", decision_inputs),
            ("row", row),
            (
                "candidate_decision_inputs.predecision_limit_fillability",
                decision_fillability,
            ),
            ("row.predecision_limit_fillability", row_fillability),
        )
        if explicit_quality
        else (
            ("candidate_decision_inputs", decision_inputs),
            ("row", row),
            (
                "candidate_decision_inputs.predecision_limit_fillability",
                decision_fillability,
            ),
            ("row.predecision_limit_fillability", row_fillability),
        )
    )
    probability = _first_num_from_sources(
        quality_sources,
        "probability",
        "candidate_probability",
        "scheduler_probability",
        "calibrated_probability",
    )
    entry_quality_fill_probability = _first_num_from_sources(
        quality_sources,
        "entry_quality_fill_probability",
        "heuristic_fill_probability",
        "fill_probability",
        "candidate_fill_probability",
        "scheduler_fill_probability",
        "predecision_fill_probability",
    )
    fill_probability = entry_quality_fill_probability
    atomic_fillability = _atomic_predecision_execution_fillability_claim(row)
    limit_fillability_probability = atomic_fillability.get("value")
    execution_fill_probability_source = _text(atomic_fillability.get("source"))
    execution_fill_probability_source_time_utc = _text(
        atomic_fillability.get("source_time_utc")
    )
    execution_fill_probability_source_boundary = _text(
        atomic_fillability.get("source_boundary")
    )
    confidence = _first_num_from_sources(
        quality_sources,
        "confidence",
        "candidate_confidence",
        "scheduler_confidence",
        "confluence_confidence",
    )
    source_completeness = _first_num_from_sources(
        quality_sources,
        "source_completeness",
        "scheduler_source_completeness",
        "candidate_source_completeness",
    )
    source_completeness_status = _first_text_from_sources(
        quality_sources,
        "source_completeness_status",
        "scheduler_source_completeness_status",
        "candidate_source_completeness_status",
        "source_completeness_state",
        "source_status",
    )
    cost_r = _first_num_from_sources(
        cost_sources,
        "cost_r",
        "broker_pretrade_cost_r",
        "broker_calibrated_expected_cost_r",
        "expected_cost_r",
        "total_cost_r",
        "spread_r",
    )
    expected_net_r = _first_num_from_sources(
        quality_sources,
        "expected_net_r",
        "candidate_expected_net_r",
        "broker_net_expected_r",
        "scheduler_expected_net_r",
    )
    expected_net_r_semantics = _first_text_from_sources(
        quality_sources,
        "expected_net_r_semantics",
        "selected_policy_expected_net_r_semantics",
    )
    expected_net_r_semantics_source = _first_text_from_sources(
        quality_sources,
        "expected_net_r_semantics_source",
    )
    if expected_net_r is not None and not expected_net_r_semantics:
        expected_net_r_semantics = LEGACY_UNTYPED_EXPECTED_VALUE
        expected_net_r_semantics_source = LEGACY_UNTYPED_EXPECTED_VALUE_SOURCE
    quality_alias_mismatches: list[str] = []
    if atomic_fillability.get("failure"):
        quality_alias_mismatches.append(
            "execution_fillability_atomic_contract:"
            + _text(atomic_fillability.get("failure"))
        )
    for declared_quality_source in (
        explicit_quality,
        decision_quality,
        row_quality,
        decision_inputs,
        row,
    ):
        declared_alias_status = _canonical_quality_alias_status(
            declared_quality_source.get("candidate_decision_quality_alias_status")
            or declared_quality_source.get("alias_status")
        )
        if declared_alias_status != "mismatch":
            continue
        quality_alias_mismatches.extend(
            _str_tuple(
                declared_quality_source.get(
                    "candidate_decision_quality_alias_mismatches"
                )
                or declared_quality_source.get("alias_mismatches")
            )
        )
    missing_confidence_default_evidence = (
        _missing_confidence_default_evidence_present(
            row,
            decision_inputs,
            row_quality,
            decision_quality,
            explicit_quality,
        )
    )
    explicit_field_sources = dict(
        _mapping(explicit_quality.get("field_sources"))
        or _mapping(explicit_quality.get("candidate_decision_quality_field_sources"))
        if explicit_quality
        else _mapping(row.get("candidate_decision_quality_field_sources"))
        or _mapping(decision_inputs.get("candidate_decision_quality_field_sources"))
    )
    field_sources = {
        field: _canonical_quality_source_label(
            field,
            source_label,
            missing_confidence_default_evidence=(
                missing_confidence_default_evidence
            ),
        )
        for field, source_label in explicit_field_sources.items()
    }
    field_source_surfaces = (
        (
            "candidate_decision_inputs.candidate_decision_quality",
            _mapping(
                decision_quality.get("field_sources")
                or decision_quality.get("candidate_decision_quality_field_sources")
            ),
        ),
        (
            "row.candidate_decision_quality",
            _mapping(
                row_quality.get("field_sources")
                or row_quality.get("candidate_decision_quality_field_sources")
            ),
        ),
        (
            "row",
            _mapping(row.get("candidate_decision_quality_field_sources")),
        ),
        (
            "candidate_decision_inputs",
            _mapping(
                decision_inputs.get("candidate_decision_quality_field_sources")
            ),
        ),
    )
    for surface_name, surface_sources in field_source_surfaces:
        for field, raw_source_label in surface_sources.items():
            source_label = _canonical_quality_source_label(
                field,
                raw_source_label,
                missing_confidence_default_evidence=(
                    missing_confidence_default_evidence
                ),
            )
            if not source_label:
                continue
            canonical_source_label = _text(field_sources.get(field))
            if canonical_source_label and canonical_source_label != source_label:
                quality_alias_mismatches.append(
                    f"field_sources:{field}:{surface_name}_vs_canonical"
                )
            elif not canonical_source_label:
                field_sources[field] = source_label
    if missing_confidence_default_evidence:
        current_confidence_sources = [
            _canonical_quality_source_label(
                "confidence",
                surface_sources.get("confidence"),
                missing_confidence_default_evidence=True,
            )
            for _, surface_sources in field_source_surfaces
            if _text(surface_sources.get("confidence"))
        ]
        canonical_confidence_source = _canonical_quality_source_label(
            "confidence",
            field_sources.get("confidence"),
            missing_confidence_default_evidence=True,
        )
        if canonical_confidence_source:
            current_confidence_sources.append(canonical_confidence_source)
        if current_confidence_sources and all(
            source == DEFAULT_MISSING_CONFIDENCE_SOURCE
            for source in current_confidence_sources
        ):
            field_sources["confidence"] = DEFAULT_MISSING_CONFIDENCE_SOURCE
            quality_alias_mismatches = [
                mismatch
                for mismatch in quality_alias_mismatches
                if not _text(mismatch).startswith("field_sources:confidence:")
            ]
    inferred_field_sources: dict[str, str] = {}
    source_aliases = {
        "probability": (
            "probability",
            "candidate_probability",
            "scheduler_probability",
            "calibrated_probability",
        ),
        "confidence": (
            "confidence",
            "candidate_confidence",
            "scheduler_confidence",
            "confluence_confidence",
        ),
        "fill_probability": (
            "entry_quality_fill_probability",
            "heuristic_fill_probability",
            "fill_probability",
            "candidate_fill_probability",
            "scheduler_fill_probability",
            "predecision_fill_probability",
        ),
        "entry_quality_fill_probability": (
            "entry_quality_fill_probability",
            "heuristic_fill_probability",
            "fill_probability",
            "candidate_fill_probability",
            "scheduler_fill_probability",
            "predecision_fill_probability",
        ),
        "limit_fillability_probability": (
            "limit_fillability_probability",
            "predecision_limit_fillability_probability",
            "limit_fill_probability",
        ),
        "source_completeness": (
            "source_completeness",
            "scheduler_source_completeness",
            "candidate_source_completeness",
        ),
        "expected_net_r": (
            "expected_net_r",
            "candidate_expected_net_r",
            "broker_net_expected_r",
            "scheduler_expected_net_r",
        ),
    }
    row_quality_sources = (
        row,
        geometry,
        geometry_scalar_fields,
        geometry_hash_material,
    )
    decision_quality_sources = (
        decision_inputs,
        decision_geometry,
        decision_geometry_scalar_fields,
        decision_geometry_hash_material,
    )
    if explicit_quality:
        for surface_name, surface in (
            ("row", row),
            ("candidate_decision_inputs", decision_inputs),
        ):
            outer_boundary = _text(
                surface.get("candidate_decision_quality_source_boundary")
            )
            nested_boundary = _text(
                explicit_quality.get("candidate_decision_quality_source_boundary")
                or explicit_quality.get("source_boundary")
            )
            if (
                outer_boundary
                and nested_boundary
                and outer_boundary != nested_boundary
            ):
                quality_alias_mismatches.append(
                    f"source_boundary:{surface_name}_vs_nested"
                )
        nested_policy = _candidate_decision_quality_envelope(explicit_quality)
        policy_aliases = {
            "selected_policy_for_expected_net_r": (
                "selected_policy_for_expected_net_r",
                "expected_net_r_selected_policy",
                "selected_policy_expected_net_r_policy",
                "selected_execution_policy",
                "dynamic_geometry_policy",
                "selected_policy",
            ),
            "selected_policy_expected_net_calibration_status": (
                "selected_policy_expected_net_calibration_status",
                "selected_policy_expected_net_r_calibration_status",
                "expected_net_r_selected_policy_calibration_status",
            ),
            "selected_policy_expected_net_calibrated": (
                "selected_policy_expected_net_calibrated",
                "selected_policy_expected_net_r_calibrated",
                "expected_net_r_selected_policy_calibrated",
            ),
            "selected_policy_expected_net_calibration_required": (
                "selected_policy_expected_net_calibration_required",
                "selected_policy_expected_net_r_calibration_required",
                "expected_net_r_selected_policy_calibration_required",
            ),
            "selected_policy_expected_net_calibration_source": (
                "selected_policy_expected_net_calibration_source",
                "selected_policy_expected_net_r_calibration_source",
                "expected_net_r_selected_policy_calibration_source",
            ),
            "selected_policy_expected_net_calibration_source_boundary": (
                "selected_policy_expected_net_calibration_source_boundary",
                "selected_policy_expected_net_calibration_boundary",
                "selected_policy_expected_net_r_calibration_boundary",
                "expected_net_r_selected_policy_calibration_boundary",
            ),
            "selected_policy_expected_net_assumption_hash": (
                "selected_policy_expected_net_assumption_hash",
                "selected_policy_expected_net_calibration_hash",
                "selected_policy_expected_net_r_assumption_hash",
                "selected_policy_expected_net_r_calibration_hash",
                "expected_net_r_selected_policy_assumption_hash",
                "expected_net_r_selected_policy_calibration_hash",
            ),
        }

        def canonical_policy_atom(field: str, value: Any) -> Any:
            if field in {
                "selected_policy_expected_net_calibrated",
                "selected_policy_expected_net_calibration_required",
            }:
                return _truthy(value)
            text = _lower(value).replace("-", "_").replace(" ", "_")
            if field == "selected_policy_expected_net_calibration_status":
                if (
                    "calibrated" in text
                    and "uncalibrated" not in text
                    and "missing" not in text
                    and "proxy_diagnostic" not in text
                ):
                    return "calibrated"
            return text

        for surface_name, surface in (
            ("row", row),
            ("candidate_decision_inputs", decision_inputs),
        ):
            for policy_field, aliases in policy_aliases.items():
                nested_value = nested_policy.get(policy_field)
                if nested_value in (None, ""):
                    continue
                for alias in aliases:
                    flat_value = surface.get(alias)
                    if flat_value in (None, ""):
                        continue
                    if canonical_policy_atom(
                        policy_field,
                        nested_value,
                    ) != canonical_policy_atom(policy_field, flat_value):
                        quality_alias_mismatches.append(
                            f"{policy_field}:{surface_name}_vs_nested"
                        )
                        break
    for conflict in cost_packet.get("atomic_conflicts") or ():
        quality_alias_mismatches.append(f"cost:{_text(conflict)}")
    for field in (
        "expected_net_r",
        "probability",
        "confidence",
        "entry_quality_fill_probability",
        "limit_fillability_probability",
        "source_completeness",
    ):
        aliases = source_aliases[field]
        row_value = _first_num_from_sources(row_quality_sources, *aliases)
        decision_value = _first_num_from_sources(decision_quality_sources, *aliases)
        if field == "limit_fillability_probability":
            if row_value is None:
                row_value = _first_num(
                    row_fillability,
                    "fill_probability",
                    "expected_fill_probability",
                    "limit_fill_probability",
                )
            if decision_value is None:
                decision_value = _first_num(
                    decision_fillability,
                    "fill_probability",
                    "expected_fill_probability",
                    "limit_fill_probability",
                )
        if (
            row_value is not None
            and decision_value is not None
            and abs(row_value - decision_value) > 0.000000001
        ):
            quality_alias_mismatches.append(field)
        if decision_quality and row_quality:
            decision_nested_value = _first_num(decision_quality, *aliases)
            row_nested_value = _first_num(row_quality, *aliases)
            if (
                decision_nested_value is not None
                and row_nested_value is not None
                and abs(decision_nested_value - row_nested_value) > 0.000000001
            ):
                quality_alias_mismatches.append(
                    f"{field}:candidate_decision_inputs_nested_vs_row_nested"
                )
        if explicit_quality:
            nested_value = _first_num(explicit_quality, *aliases)
            for surface_name, surface in (
                ("row", row),
                ("candidate_decision_inputs", decision_inputs),
            ):
                surface_value = _first_num(surface, *aliases)
                if (
                    nested_value is not None
                    and surface_value is not None
                    and abs(nested_value - surface_value) > 0.000000001
                ):
                    quality_alias_mismatches.append(
                        f"{field}:{surface_name}_vs_nested"
                    )
    for field, aliases in source_aliases.items():
        if _text(field_sources.get(field)):
            continue
        value = {
        "probability": probability,
        "confidence": confidence,
        "fill_probability": fill_probability,
        "entry_quality_fill_probability": entry_quality_fill_probability,
        "limit_fillability_probability": limit_fillability_probability,
        "source_completeness": source_completeness,
        "expected_net_r": expected_net_r,
        }[field]
        if value is not None:
            source_label = _first_present_source_label(
                (
                    ("row", row),
                    ("candidate_decision_inputs", decision_inputs),
                    *named_quality_sources,
                )
                if field == "confidence"
                else named_quality_sources,
                *aliases,
            )
            if source_label:
                field_sources[field] = source_label
                inferred_field_sources[field] = source_label
    if entry_quality_fill_probability is not None:
        field_sources.setdefault(
            "entry_quality_fill_probability",
            _first_present_source_label(
                named_quality_sources,
                *source_aliases["entry_quality_fill_probability"],
            )
            or field_sources.get("fill_probability")
            or "scheduler.normalized_quality.entry_quality_fill_probability",
        )
    if limit_fillability_probability is not None:
        field_sources.setdefault(
            "limit_fillability_probability",
            _first_present_source_label(
                named_limit_fillability_sources,
                *source_aliases["limit_fillability_probability"],
            )
            or "scheduler.normalized_quality.limit_fillability_probability",
        )
    canonical_quality_alias_mismatches = list(
        dict.fromkeys(quality_alias_mismatches)
    )
    has_quality_material = any(
        value is not None
        for value in (
            expected_net_r,
            probability,
            confidence,
            entry_quality_fill_probability,
            limit_fillability_probability,
            source_completeness,
        )
    )
    inferred_required_quality = any(
        _text(inferred_field_sources.get(field))
        for field in PACKAGE_NEW_ENTRY_REQUIRED_QUALITY_FIELDS
    )
    if canonical_quality_alias_mismatches:
        canonical_quality_alias_status = "mismatch"
    elif explicit_quality:
        canonical_quality_alias_status = "exact_materialized"
    elif has_quality_material or field_sources:
        canonical_quality_alias_status = (
            "inferred_materialized"
            if inferred_required_quality
            else "materialized"
        )
    else:
        canonical_quality_alias_status = ""
    out = {
        "probability": probability,
        "candidate_probability": probability,
        "fill_probability": fill_probability,
        "candidate_fill_probability": fill_probability,
        "entry_quality_fill_probability": entry_quality_fill_probability,
        "execution_fill_probability": limit_fillability_probability,
        "execution_fill_probability_source": execution_fill_probability_source,
        "execution_fill_probability_source_time_utc": (
            execution_fill_probability_source_time_utc
        ),
        "execution_fill_probability_source_boundary": (
            execution_fill_probability_source_boundary
        ),
        "execution_fill_probability_authority_class": atomic_fillability.get(
            "authority_class"
        ),
        "execution_fillability_atomic_surface": atomic_fillability.get("surface"),
        "execution_fillability_atomic_failure": atomic_fillability.get("failure"),
        "execution_fillability_atomic_conflicts": list(
            atomic_fillability.get("atomic_conflicts") or ()
        ),
        "limit_fillability_probability": limit_fillability_probability,
        "predecision_limit_fillability_probability": limit_fillability_probability,
        "confidence": confidence,
        "candidate_confidence": confidence,
        "source_completeness": source_completeness,
        "source_completeness_status": source_completeness_status,
        "cost_r": cost_r,
        "expected_cost_r": cost_r,
        "cost_total_r": cost_r,
        "expected_net_r": expected_net_r,
        "candidate_expected_net_r": expected_net_r,
        "expected_net_r_semantics": expected_net_r_semantics,
        "expected_net_r_semantics_source": expected_net_r_semantics_source,
        "candidate_decision_quality_field_sources": field_sources,
        "candidate_decision_quality_inferred_field_sources": inferred_field_sources,
        "candidate_decision_quality_alias_mismatches": (
            canonical_quality_alias_mismatches
        ),
        "candidate_decision_quality_alias_status": canonical_quality_alias_status,
        "candidate_decision_quality_source_boundary": (
            candidate_quality_source_boundary
        ),
        "candidate_decision_quality_provenance_failures": (
            explicit_quality.get("provenance_failures")
            or explicit_quality.get("candidate_decision_quality_provenance_failures")
            if explicit_quality
            else row.get("candidate_decision_quality_provenance_failures")
            or decision_inputs.get("candidate_decision_quality_provenance_failures")
            or ()
        ),
        "candidate_decision_quality_optional_provenance_warnings": (
            explicit_quality.get("optional_provenance_warnings")
            or explicit_quality.get(
                "candidate_decision_quality_optional_provenance_warnings"
            )
            if explicit_quality
            else row.get("candidate_decision_quality_optional_provenance_warnings")
            or decision_inputs.get(
                "candidate_decision_quality_optional_provenance_warnings"
            )
            or ()
        ),
    }
    selected_policy_source = {
        **dict(row),
        **dict(decision_inputs),
        **dict(explicit_quality),
    }
    direct_owner_approved_selected_policy_atom: dict[str, Any] = {}
    for selected_policy_surface in (row, decision_inputs):
        direct_owner_approved_selected_policy_atom = (
            _direct_owner_approved_selected_policy_expected_net_atom(
                selected_policy_surface
            )
        )
        if direct_owner_approved_selected_policy_atom:
            selected_policy_source.update(
                direct_owner_approved_selected_policy_atom
            )
            break
    selected_policy_projection = _candidate_decision_quality_envelope(
        selected_policy_source
    )
    for key in (
        "selected_policy_for_expected_net_r",
        "selected_policy_expected_net_calibration_status",
        "selected_policy_expected_net_calibrated",
        "selected_policy_expected_net_calibration_required",
        "selected_policy_expected_net_calibration_source",
        "selected_policy_expected_net_calibration_source_boundary",
        "selected_policy_expected_net_assumption_hash",
    ):
        value = selected_policy_projection.get(key)
        if value not in (None, ""):
            out[key] = value
    out["candidate_decision_quality"] = _candidate_decision_quality_envelope(out)
    return out


def _candidate_decision_quality_envelope(
    fields: Mapping[str, Any],
) -> dict[str, Any]:
    """Canonical nested quality object; flat fields remain compatibility API."""

    existing = _mapping(fields.get("candidate_decision_quality"))
    envelope = dict(existing)
    scalar_aliases = {
        "expected_net_r": ("expected_net_r", "candidate_expected_net_r"),
        "candidate_expected_net_r": ("candidate_expected_net_r", "expected_net_r"),
        "expected_net_r_semantics": (
            "expected_net_r_semantics",
            "selected_policy_expected_net_r_semantics",
        ),
        "expected_net_r_semantics_source": (
            "expected_net_r_semantics_source",
        ),
        "probability": ("probability", "candidate_probability"),
        "candidate_probability": ("candidate_probability", "probability"),
        "confidence": ("confidence", "candidate_confidence", "scheduler_confidence"),
        "candidate_confidence": ("candidate_confidence", "confidence", "scheduler_confidence"),
        "fill_probability": (
            "entry_quality_fill_probability",
            "heuristic_fill_probability",
            "fill_probability",
            "candidate_fill_probability",
        ),
        "candidate_fill_probability": (
            "entry_quality_fill_probability",
            "heuristic_fill_probability",
            "candidate_fill_probability",
            "fill_probability",
        ),
        "entry_quality_fill_probability": (
            "entry_quality_fill_probability",
            "heuristic_fill_probability",
            "fill_probability",
            "candidate_fill_probability",
        ),
        "execution_fill_probability": (
            "execution_fill_probability",
            "predecision_limit_fillability_probability",
            "limit_fillability_probability",
            "limit_fill_probability",
        ),
        "execution_fill_probability_source": (
            "execution_fill_probability_source",
            "package_new_entry_authority_execution_fill_probability_source",
            "execution_fillability_source",
        ),
        "execution_fill_probability_source_time_utc": (
            "execution_fill_probability_source_time_utc",
            "execution_fillability_source_time_utc",
            "predecision_limit_fillability_source_time_utc",
            "predecision_current_price_source_time_utc",
            "current_price_source_time_utc",
        ),
        "execution_fill_probability_source_boundary": (
            "execution_fill_probability_source_boundary",
            "execution_fillability_source_boundary",
            "predecision_limit_fillability_source_boundary",
            "predecision_current_price_source_boundary",
            "current_price_source_boundary",
        ),
        "limit_fillability_probability": (
            "limit_fillability_probability",
            "predecision_limit_fillability_probability",
            "limit_fill_probability",
        ),
        "predecision_limit_fillability_probability": (
            "predecision_limit_fillability_probability",
            "limit_fillability_probability",
            "limit_fill_probability",
        ),
        "source_completeness": ("source_completeness", "candidate_source_completeness"),
        "source_completeness_status": (
            "source_completeness_status",
            "candidate_source_completeness_status",
        ),
        "expected_cost_r": (
            "expected_cost_r",
            "predecision_expected_cost_r",
            "cost_total_r",
            "cost_r",
        ),
        "cost_total_r": ("cost_total_r", "expected_cost_r", "cost_r"),
        "cost_r": ("cost_r", "expected_cost_r", "cost_total_r"),
        "source_boundary": (
            "candidate_decision_quality_source_boundary",
            "source_boundary",
        ),
        "selected_policy_for_expected_net_r": (
            "package_new_entry_authority_selected_policy_for_expected_net_r",
            "selected_policy_for_expected_net_r",
            "expected_net_r_selected_policy",
            "selected_policy_expected_net_r_policy",
            "selected_execution_policy",
            "dynamic_geometry_policy",
            "gtos_vnext_selected_cell_risk_selected_policy",
            "selected_policy",
        ),
        "selected_policy_expected_net_calibration_status": (
            "package_new_entry_authority_selected_policy_expected_net_calibration_status",
            "selected_policy_expected_net_calibration_status",
            "selected_policy_expected_net_r_calibration_status",
            "expected_net_r_selected_policy_calibration_status",
            "selected_policy_exit_assumption_status",
            "expected_net_r_exit_assumption_status",
        ),
        "selected_policy_expected_net_calibrated": (
            "package_new_entry_authority_selected_policy_expected_net_calibrated",
            "selected_policy_expected_net_calibrated",
            "selected_policy_expected_net_r_calibrated",
            "expected_net_r_selected_policy_calibrated",
            "selected_policy_exit_assumption_calibrated",
            "expected_net_r_exit_assumption_calibrated",
        ),
        "selected_policy_expected_net_calibration_required": (
            "package_new_entry_authority_selected_policy_expected_net_calibration_required",
            "selected_policy_expected_net_calibration_required",
            "selected_policy_expected_net_r_calibration_required",
            "expected_net_r_selected_policy_calibration_required",
            "selected_policy_exit_assumption_required",
            "expected_net_r_exit_assumption_required",
        ),
        "selected_policy_expected_net_calibration_source": (
            "package_new_entry_authority_selected_policy_expected_net_calibration_source",
            "selected_policy_expected_net_calibration_source",
            "selected_policy_expected_net_r_calibration_source",
            "expected_net_r_selected_policy_calibration_source",
        ),
        "selected_policy_expected_net_calibration_source_boundary": (
            "package_new_entry_authority_selected_policy_expected_net_calibration_source_boundary",
            "selected_policy_expected_net_calibration_source_boundary",
            "selected_policy_expected_net_calibration_boundary",
            "selected_policy_expected_net_r_calibration_boundary",
            "expected_net_r_selected_policy_calibration_boundary",
        ),
        "selected_policy_expected_net_assumption_hash": (
            "package_new_entry_authority_selected_policy_expected_net_calibration_hash",
            "selected_policy_expected_net_assumption_hash",
            "selected_policy_expected_net_calibration_hash",
            "selected_policy_expected_net_r_assumption_hash",
            "selected_policy_expected_net_r_calibration_hash",
            "expected_net_r_selected_policy_assumption_hash",
            "expected_net_r_selected_policy_calibration_hash",
            "selected_policy_exit_assumption_hash",
            "expected_net_r_exit_assumption_hash",
        ),
    }
    selected_policy_keys = tuple(
        key for key in scalar_aliases if key.startswith("selected_policy_")
    )
    nested_selected_policy = {
        key: envelope.get(key)
        for key in selected_policy_keys
        if envelope.get(key) not in (None, "")
    }
    prefixed_selected_policy = {
        key: _first_present_value(
            *(
                fields.get(alias)
                for alias in aliases
                if alias.startswith("package_new_entry_authority_")
            )
        )
        for key, aliases in scalar_aliases.items()
        if key in selected_policy_keys
    }
    prefixed_selected_policy = {
        key: value
        for key, value in prefixed_selected_policy.items()
        if value not in (None, "")
    }
    existing_signed_selected_policy = (
        nested_selected_policy or prefixed_selected_policy
    )
    direct_selected_policy = {
        key: _first_present_value(
            *(
                fields.get(alias)
                for alias in aliases
                if not alias.startswith("package_new_entry_authority_")
            )
        )
        for key, aliases in scalar_aliases.items()
        if key in selected_policy_keys
    }
    direct_selected_policy = {
        key: value
        for key, value in direct_selected_policy.items()
        if value not in (None, "")
    }
    flat_status = _lower(
        direct_selected_policy.get("selected_policy_expected_net_calibration_status")
    )
    flat_source = _lower(
        direct_selected_policy.get("selected_policy_expected_net_calibration_source")
    )
    flat_owner_approved_calibration = bool(
        "owner_approved_reconstructed" in flat_status
        or flat_source == "owner_approved_reconstructed_proxy_package_expected_net_r"
    )
    existing_signed_selected_policy_complete = bool(
        existing_signed_selected_policy.get("selected_policy_for_expected_net_r")
        and existing_signed_selected_policy.get(
            "selected_policy_expected_net_calibration_status"
        )
        and _truthy(
            existing_signed_selected_policy.get(
                "selected_policy_expected_net_calibrated"
            )
        )
        and existing_signed_selected_policy.get(
            "selected_policy_expected_net_calibration_source"
        )
        and existing_signed_selected_policy.get(
            "selected_policy_expected_net_calibration_source_boundary"
        )
        and existing_signed_selected_policy.get(
            "selected_policy_expected_net_assumption_hash"
        )
        and selected_policy_expected_net_calibration_failure_reason(
            existing_signed_selected_policy
        )
        is None
    )
    replace_with_direct_owner_approved_calibration = bool(
        existing_signed_selected_policy
        and direct_selected_policy
        and not existing_signed_selected_policy_complete
        and flat_owner_approved_calibration
        and _truthy(
            direct_selected_policy.get("selected_policy_expected_net_calibrated")
        )
    )
    if replace_with_direct_owner_approved_calibration:
        for key in selected_policy_keys:
            envelope.pop(key, None)
        envelope[
            "selected_policy_expected_net_nested_replaced_by_owner_approved_calibration"
        ] = True
    for out_key, candidates in scalar_aliases.items():
        if out_key.startswith("selected_policy_") and envelope.get(out_key) not in (
            None,
            "",
        ):
            continue
        value = (
            direct_selected_policy.get(out_key)
            if replace_with_direct_owner_approved_calibration
            and out_key.startswith("selected_policy_")
            else _first_present_value(*(fields.get(key) for key in candidates))
        )
        if value not in (None, ""):
            envelope[out_key] = value
    field_sources = (
        _mapping(fields.get("candidate_decision_quality_field_sources"))
        or _mapping(fields.get("field_sources"))
        or _mapping(envelope.get("field_sources"))
    )
    if field_sources:
        envelope["field_sources"] = dict(field_sources)
        envelope["candidate_decision_quality_field_sources"] = dict(field_sources)
    for out_key, candidates in {
        "alias_status": ("candidate_decision_quality_alias_status", "alias_status"),
        "alias_mismatches": (
            "candidate_decision_quality_alias_mismatches",
            "alias_mismatches",
        ),
        "provenance_failures": (
            "candidate_decision_quality_provenance_failures",
            "provenance_failures",
        ),
        "source_boundary": (
            "candidate_decision_quality_source_boundary",
            "source_boundary",
        ),
    }.items():
        value = _first_present_value(*(fields.get(key) for key in candidates))
        if value not in (None, ""):
            envelope[out_key] = list(value) if isinstance(value, tuple) else value
            if out_key == "source_boundary":
                envelope["candidate_decision_quality_source_boundary"] = value
            elif out_key == "alias_status":
                envelope["candidate_decision_quality_alias_status"] = value
            elif out_key == "alias_mismatches":
                envelope["candidate_decision_quality_alias_mismatches"] = (
                    list(value) if isinstance(value, tuple) else value
                )
    if envelope.get("expected_net_r") not in (None, "") and not _text(
        envelope.get("expected_net_r_semantics")
    ):
        calibration_source = _lower(
            envelope.get("selected_policy_expected_net_calibration_source")
        )
        owner_proxy = (
            calibration_source
            == "owner_approved_reconstructed_proxy_package_expected_net_r"
        )
        envelope["expected_net_r_semantics"] = (
            EXPECTED_VALUE_GIVEN_FILL
            if owner_proxy
            else LEGACY_UNTYPED_EXPECTED_VALUE
        )
        envelope["expected_net_r_semantics_source"] = (
            calibration_source
            if owner_proxy
            else LEGACY_UNTYPED_EXPECTED_VALUE_SOURCE
        )
    return {
        key: value
        for key, value in envelope.items()
        if value not in (None, "")
    }


def _selected_policy_expected_net_calibration(
    candidate: "AllocatorCandidate",
    field_sources: Mapping[str, Any],
) -> dict[str, Any]:
    metadata = _mapping(candidate.metadata)
    geometry = _mapping(metadata.get("geometry_contract"))
    geometry_scalar_fields = _mapping(geometry.get("scalar_fields"))
    geometry_hash_material = _mapping(geometry.get("source_event_hash_material"))
    selected_policy = _lower(
        geometry.get("selected_policy")
        or geometry_scalar_fields.get("selected_policy")
        or geometry_hash_material.get("selected_policy")
        or metadata.get("dynamic_geometry_policy")
        or metadata.get("gtos_vnext_selected_cell_risk_selected_policy")
        or metadata.get("selected_execution_policy")
        or metadata.get("selected_policy_for_expected_net_r")
        or metadata.get("package_new_entry_authority_selected_policy_for_expected_net_r")
        or metadata.get("selected_policy")
    )
    expected_policy = _lower(
        metadata.get("expected_net_r_selected_policy")
        or metadata.get("selected_policy_expected_net_r_policy")
        or metadata.get("expected_net_r_exit_policy")
        or metadata.get("candidate_expected_net_r_exit_policy")
    )
    status_text = _lower(
        metadata.get("package_new_entry_authority_selected_policy_expected_net_calibration_status")
        or metadata.get("selected_policy_expected_net_r_calibration_status")
        or metadata.get("selected_policy_expected_net_calibration_status")
        or metadata.get("expected_net_r_selected_policy_calibration_status")
        or metadata.get("selected_policy_exit_assumption_status")
        or metadata.get("expected_net_r_exit_assumption_status")
    )
    explicit_selected_policy_source = _lower(
        metadata.get("package_new_entry_authority_selected_policy_expected_net_calibration_source")
        or metadata.get("selected_policy_expected_net_calibration_source")
        or metadata.get("selected_policy_expected_net_r_calibration_source")
        or metadata.get("expected_net_r_selected_policy_calibration_source")
    )
    generic_expected_net_source = _lower(field_sources.get("expected_net_r"))
    expected_source = _lower(
        explicit_selected_policy_source or generic_expected_net_source
    )
    source_boundary = _lower(
        metadata.get(
            "package_new_entry_authority_selected_policy_expected_net_calibration_source_boundary"
        )
        or metadata.get("selected_policy_expected_net_calibration_source_boundary")
        or metadata.get("selected_policy_expected_net_calibration_boundary")
        or metadata.get("selected_policy_expected_net_r_calibration_boundary")
        or metadata.get("expected_net_r_selected_policy_calibration_boundary")
        or metadata.get("candidate_decision_quality_source_boundary")
        or metadata.get("candidate_scheduler_quality_source_boundary")
        or metadata.get("source_boundary")
    )
    assumption_hash = _text(
        metadata.get("package_new_entry_authority_selected_policy_expected_net_calibration_hash")
        or metadata.get("selected_policy_exit_assumption_hash")
        or metadata.get("expected_net_r_exit_assumption_hash")
        or metadata.get("selected_policy_expected_net_r_assumption_hash")
        or metadata.get("selected_policy_expected_net_assumption_hash")
        or metadata.get("selected_policy_expected_net_calibration_hash")
        or metadata.get("selected_policy_expected_net_r_calibration_hash")
    )
    selector_action = _lower(metadata.get("selector_action") or candidate.selector_action)
    selector_reason = _lower(metadata.get("selector_reason") or candidate.selector_reason)
    selected_policy_required = bool(
        selector_action == "open-reduced-risk"
        and selector_reason in PACKAGE_REDUCE_RISK_NUMERIC_REASONS
    )
    if not selected_policy and selected_policy_required:
        calibrated = False
        status = "selected_policy_expected_net_calibration_missing_no_selected_policy"
    elif not selected_policy:
        selected_policy = "unspecified_expected_net_r_policy"
        calibrated = True
        status = "not_required_no_selected_policy"
    elif candidate.expected_net_r is None:
        calibrated = False
        status = "expected_net_r_missing"
    else:
        searchable = " ".join(
            text
            for text in (
                status_text,
                expected_source,
                source_boundary,
                expected_policy,
            )
            if text
        )
        stale_markers = ("missing", "stale", "legacy", "uncalibrated", "mismatch")
        positive_markers = (
            "selected_policy",
            "selected_execution_policy",
            "dynamic_execution_policy",
            "policy_replay",
            selected_policy,
        )
        status_calibrated = (
            ("calibrated" in status_text or "aligned" in status_text)
            and not any(marker in status_text for marker in stale_markers)
        )
        policy_calibrated = bool(expected_policy and expected_policy == selected_policy)
        source_calibrated = bool(
            searchable
            and any(marker and marker in searchable for marker in positive_markers)
            and not any(marker in searchable for marker in stale_markers)
        )
        calibrated = bool(status_calibrated or policy_calibrated or source_calibrated)
        status = (
            "selected_policy_expected_net_calibrated"
            if calibrated
            else "selected_policy_expected_net_calibration_missing"
        )
        calibration_failure = selected_policy_expected_net_calibration_failure_reason(
            {
                "selected_policy_for_expected_net_r": selected_policy,
                "selected_policy_expected_net_calibration_status": status_text,
                "selected_policy_expected_net_calibrated": calibrated,
                "selected_policy_expected_net_calibration_required": True,
                "selected_policy_expected_net_calibration_source": expected_source,
                "selected_policy_expected_net_calibration_source_boundary": (
                    source_boundary
                ),
                "expected_net_r_selected_policy": expected_policy,
            }
        )
        if calibration_failure:
            calibrated = False
            status = (
                "selected_policy_expected_net_bridge_proxy_diagnostic_only"
                if calibration_failure
                == "selected_policy_expected_net_bridge_proxy_not_executable"
                else calibration_failure
            )
    return {
        "selected_policy": selected_policy or None,
        "expected_policy": expected_policy or None,
        "calibrated": calibrated,
        "status": status,
        "source": expected_source or None,
        "source_boundary": source_boundary
        or (
            "predecision_row_candidate_quality_aliases_no_outcome_fields"
            if expected_source or generic_expected_net_source
            else None
        ),
        "assumption_hash": assumption_hash or None,
    }


def _clamp(value: float, low: float, high: float) -> float:
    return max(low, min(high, value))


def _round(value: float | None) -> float | None:
    if value is None:
        return None
    return round(float(value), 9)


def parse_dt(value: Any) -> datetime | None:
    if value in (None, ""):
        return None
    if isinstance(value, datetime):
        dt = value
    else:
        text = _text(value).replace("Z", "+00:00")
        if " " in text and "T" not in text:
            text = text.replace(" ", "T")
        try:
            dt = datetime.fromisoformat(text)
        except ValueError:
            return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def iso(value: datetime | None) -> str | None:
    return value.isoformat() if value else None


def normalize_side(value: Any) -> str:
    side = _lower(value)
    if side in {
        "buy",
        "bull",
        "long",
        "0",
        "2",
        "4",
        "6",
        "buy_limit",
        "buy stop",
        "buy_stop",
        "buy stop limit",
        "buy_stop_limit",
        "mt5_order_type_buy_limit",
        "mt5_order_type_buy_stop",
        "mt5_order_type_buy_stop_limit",
    }:
        return "LONG"
    if side in {
        "sell",
        "bear",
        "short",
        "1",
        "3",
        "5",
        "7",
        "sell_limit",
        "sell stop",
        "sell_stop",
        "sell stop limit",
        "sell_stop_limit",
        "mt5_order_type_sell_limit",
        "mt5_order_type_sell_stop",
        "mt5_order_type_sell_stop_limit",
    }:
        return "SHORT"
    return _text(value, "UNKNOWN").upper()


def pending_exposure_id_from_mapping(row: Mapping[str, Any], *, input_sequence: int = 0) -> str:
    return _text(
        row.get("pending_id")
        or row.get("order_ticket")
        or row.get("pending_ticket")
        or row.get("mt5_order_ticket")
        or row.get("MT5_order_ticket")
        or row.get("ticket")
        or row.get("simulated_order_id")
        or f"pending:{input_sequence}"
    )


def pending_exposure_side_from_mapping(row: Mapping[str, Any]) -> str:
    return normalize_side(
        row.get("side")
        or row.get("direction")
        or row.get("native_pending_order_type")
        or row.get("native_pending_order_type_source_safe")
        or row.get("type")
        or row.get("order_type")
    )


def cluster_key(symbol: str) -> str:
    key = _text(symbol).upper().replace(".", "_")
    clusters = {
        "metals": {"XAUUSD", "XAGUSD", "GC", "SI"},
        "crypto": {"BTCUSD", "ETHUSD"},
        "us_index": {"NAS100", "NDX100", "SPX500", "US500", "US30", "US30_CASH"},
        "europe_index": {"GER40", "UK100"},
        "energy": {"UKOIL_CASH", "USOIL_CASH", "UKOIL", "USOIL"},
        "jpy_fx": {"AUDJPY", "CHFJPY", "EURJPY", "GBPJPY", "USDJPY", "JP225"},
        "usd_fx": {"AUDUSD", "EURUSD", "GBPUSD", "NZDUSD", "USDCAD", "USDCHF"},
    }
    for cluster, members in clusters.items():
        if key in members:
            return cluster
    return f"solo:{key or 'UNKNOWN'}"


def source_completeness_score(value: Any, status: Any = None) -> float:
    if (number := _num(value)) is not None:
        if number > 1.0:
            number = number / 100.0
        return _clamp(number, 0.0, 1.0)
    text = _lower(status or value)
    if text in {"complete", "source_window_complete", "pass", "verified"}:
        return 1.0
    if "complete_with" in text:
        return 0.85
    if "incomplete" in text or "gap" in text:
        return 0.45
    if "missing" in text or "unknown" in text:
        return 0.25
    return 0.25


