def build_exposure_snapshot(window: DecisionWindow, config: SchedulerV4Config) -> ExposureSnapshot:
    same_symbol_risk: dict[str, float] = {}
    same_symbol_side_map: dict[str, list[str]] = {}
    cluster_risk: dict[str, float] = {}
    stale_open: list[str] = []
    stale_pending: list[str] = []

    open_rows: list[Mapping[str, Any]] = []
    for exposure in window.open_positions:
        key = exposure.symbol.upper()
        same_symbol_risk[key] = same_symbol_risk.get(key, 0.0) + max(0.0, exposure.risk_pct)
        same_symbol_side_map.setdefault(key, [])
        if exposure.side not in same_symbol_side_map[key]:
            same_symbol_side_map[key].append(exposure.side)
        cluster = cluster_key(exposure.symbol)
        cluster_risk[cluster] = cluster_risk.get(cluster, 0.0) + max(0.0, exposure.risk_pct)
        if (exposure.stale_thesis_score or 0.0) >= config.stale_reduce_threshold:
            stale_open.append(exposure.exposure_id)
        row = asdict(exposure)
        row["missing_sources"] = list(exposure.missing_sources)
        open_rows.append(row)

    pending_rows: list[Mapping[str, Any]] = []
    for pending in window.pending_orders:
        key = pending.symbol.upper()
        same_symbol_risk[key] = same_symbol_risk.get(key, 0.0) + max(
            0.0,
            pending.reserved_risk_pct,
        )
        same_symbol_side_map.setdefault(key, [])
        if pending.side not in same_symbol_side_map[key]:
            same_symbol_side_map[key].append(pending.side)
        cluster = cluster_key(pending.symbol)
        cluster_risk[cluster] = cluster_risk.get(cluster, 0.0) + max(
            0.0,
            pending.reserved_risk_pct,
        )
        if (pending.stale_thesis_score or 0.0) >= config.pending_cancel_threshold:
            stale_pending.append(pending.pending_id)
        row = asdict(pending)
        if (
            pending.fill_probability is not None
            and pending.pending_fill_probability_authority_class
            != "pending_order_fillability_missing"
        ):
            pending_fill = _round(pending.fill_probability)
            row["pending_fill_probability"] = pending_fill
            row["pending_limit_fillability_probability"] = pending_fill
            row["pending_fill_probability_authority_class"] = (
                pending.pending_fill_probability_authority_class
            )
        row["missing_sources"] = list(pending.missing_sources)
        pending_rows.append(row)

    open_risk = sum(max(0.0, exposure.risk_pct) for exposure in window.open_positions)
    pending_risk = sum(max(0.0, pending.reserved_risk_pct) for pending in window.pending_orders)
    missing = tuple(window.missing_runtime_truth)
    source_status = (
        "complete"
        if not missing
        else "prospective_capture_required:" + ",".join(sorted(set(missing))[:8])
    )
    return ExposureSnapshot(
        schema_version=EXPOSURE_SNAPSHOT_SCHEMA_VERSION,
        asof_utc=window.asof_utc,
        open_position_count=len(window.open_positions),
        pending_order_count=len(window.pending_orders),
        open_risk_pct=_round(open_risk) or 0.0,
        pending_risk_pct=_round(pending_risk) or 0.0,
        total_reserved_risk_pct=_round(open_risk + pending_risk) or 0.0,
        same_symbol_risk_pct={k: _round(v) or 0.0 for k, v in same_symbol_risk.items()},
        same_symbol_side_map=same_symbol_side_map,
        cluster_risk_pct={k: _round(v) or 0.0 for k, v in cluster_risk.items()},
        stale_open_exposure_ids=stale_open,
        stale_pending_order_ids=stale_pending,
        source_completeness_status=source_status,
        evidence_class=window.evidence_class,
        missing_runtime_truth=missing,
        open_positions=tuple(open_rows),
        pending_orders=tuple(pending_rows),
    )


def _candidate_value(candidate: AllocatorCandidate) -> tuple[float, str]:
    if candidate.ev_r is not None:
        return candidate.ev_r, "decision_time_ev_r"
    if candidate.expectancy_r is not None:
        return candidate.expectancy_r, "decision_time_expectancy_r"
    if candidate.expected_net_r is not None:
        return candidate.expected_net_r, "decision_time_expected_net_r"
    return 0.0, "missing_decision_time_value"


def _source_token_matches(value: str, tokens: Sequence[str]) -> bool:
    missing = _lower(value).replace("-", "_")
    return any(
        token
        and (
            token in missing
            or missing in token
        )
        for token in (_lower(item).replace("-", "_") for item in tokens)
    )


def critical_missing_source_vetoes(
    candidate: AllocatorCandidate,
    snapshot: ExposureSnapshot,
    config: SchedulerV4Config,
) -> tuple[str, ...]:
    """Return hard vetoes for source gaps that make allocation authority unsafe."""

    if not config.require_full_window_source:
        return ()
    vetoes: list[str] = []
    tokens = config.critical_missing_source_tokens
    for missing in snapshot.missing_runtime_truth:
        if _source_token_matches(missing, tokens):
            vetoes.append(f"scheduler_v4_full_window_source_required:{missing}")
    for missing in candidate.missing_sources:
        if _source_token_matches(missing, tokens):
            vetoes.append(f"scheduler_v4_critical_candidate_source_missing:{missing}")
    return tuple(dict.fromkeys(vetoes))


def _candidate_edge_score(
    *,
    ev_r: float,
    probability: float,
    cost_total: float,
    fill_probability: float,
    source_completeness: float,
    fill_probability_weight: float = 0.10,
) -> float:
    net_edge = ev_r - cost_total
    executable_transfer = _candidate_executable_transfer_score(
        expected_net_r=net_edge,
        probability=probability,
        fill_probability=fill_probability,
        source_completeness=source_completeness,
    )
    return (
        executable_transfer * 2.0
        + max(0.0, probability - 0.50) * 0.25
        + fill_probability * fill_probability_weight
        + source_completeness * 0.05
        - max(0.0, -net_edge)
    )


SCHEDULER_LEGACY_SCORE_COMPONENT_KEYS = (
    "ev_component",
    "probability_component",
    "confidence_component",
    "source_completeness_component",
    "fill_probability_component",
    "executable_transfer_component",
    "confluence_component",
    "uncertainty_penalty",
    "cost_penalty",
    "missing_source_penalty",
    "freshness_penalty",
    "selector_reduce_risk_new_entry_penalty",
    "package_fill_floor_execution_drag_penalty_component",
    "execution_fill_shortfall_rank_penalty_component",
    "selected_policy_expected_net_calibration_penalty_component",
)


def _candidate_executable_transfer_score(
    *,
    expected_net_r: float,
    probability: float,
    fill_probability: float,
    source_completeness: float,
    expected_net_r_semantics: Any = None,
) -> float:
    return float(
        executable_expected_value(
            expected_net_r=expected_net_r,
            semantics=expected_net_r_semantics,
            probability=probability,
            execution_fill_probability=fill_probability,
            source_completeness=source_completeness,
        )["executable_expected_value"]
    )


def _sum_scheduler_score_components(score_components: Mapping[str, Any]) -> float:
    total = 0.0
    for key in SCHEDULER_LEGACY_SCORE_COMPONENT_KEYS:
        value = score_components.get(key)
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            total += float(value)
    return total


def _candidate_broker_cost_rank_diagnostic(
    candidate: AllocatorCandidate,
) -> dict[str, Any]:
    """Return executable-cost ranking diagnostics from pretrade packet fields."""

    metadata = candidate.metadata if isinstance(candidate.metadata, Mapping) else {}
    packet = _pretrade_cost_packet(metadata)
    status = _text(packet.get("status")).upper()
    source_gap_status = _text(packet.get("cost_source_gap_status"))
    authority = _text(packet.get("authority"))
    fallback_authority = _truthy(
        packet.get("candidate_cost_r_fallback_is_authority")
    )
    conflict_fields = list(packet.get("atomic_conflicts") or ())
    refusal_reasons = packet.get("refusal_reasons")
    if isinstance(refusal_reasons, str):
        refusal_reason_list = [refusal_reasons]
    elif isinstance(refusal_reasons, Sequence) and not isinstance(
        refusal_reasons,
        (bytes, bytearray),
    ):
        refusal_reason_list = [str(item) for item in refusal_reasons]
    else:
        refusal_reason_list = []

    hard_veto_reason = None
    if conflict_fields:
        hard_veto_reason = (
            "nested_broker_cost_packet_conflict_not_executable:"
            + ",".join(_text(field) for field in conflict_fields)
        )
    elif not status:
        hard_veto_reason = "broker_cost_packet_status_missing_not_executable"
    elif status == "REFUSED":
        hard_veto_reason = "broker_cost_packet_refused_not_executable"
    elif status not in {"PASSED", "PASS", "OK"}:
        hard_veto_reason = f"broker_cost_packet_status_not_executable:{status}"
    elif not source_gap_status:
        hard_veto_reason = "broker_cost_source_gap_missing_not_executable"
    elif source_gap_status != "source_bound_cost_authority_present":
        hard_veto_reason = (
            f"broker_cost_source_gap_not_executable:{source_gap_status}"
        )
    elif fallback_authority:
        hard_veto_reason = "candidate_cost_r_fallback_not_order_authority"
    elif not authority:
        hard_veto_reason = "broker_cost_authority_missing_not_executable"
    elif authority and authority != "broker_calibrated_replay_cost":
        hard_veto_reason = f"broker_cost_authority_unexpected:{authority}"

    return {
        "status": (
            "broker_cost_rank_veto"
            if hard_veto_reason
            else "broker_cost_rank_clear"
        ),
        "hard_veto_reason": hard_veto_reason,
        "pretrade_cost_packet_status": status or None,
        "pretrade_cost_refusal_reasons": refusal_reason_list,
        "cost_source_gap_status": source_gap_status or None,
        "candidate_cost_r_fallback_is_authority": fallback_authority,
        "cost_authority": authority or None,
        "cost_packet_conflict_status": (
            "nested_broker_cost_packet_conflict_fail_closed"
            if conflict_fields
            else None
        ),
        "cost_packet_conflict_fields": conflict_fields,
        "diagnostic_uses_outcome_fields": False,
    }


def _candidate_execution_authority_vetoes(
    candidate: AllocatorCandidate,
    broker_cost_rank: Mapping[str, Any],
    *,
    source_completeness_floor: float = 0.95,
    expected_net_r: float | None = None,
    probability: float | None = None,
    fill_probability: float | None = None,
    source_completeness: float | None = None,
    source_completeness_status: str | None = None,
) -> tuple[str, ...]:
    """Return hard vetoes from explicit selector/package execution authority."""

    if candidate.action_intent not in NEW_RISK_ACTIONS:
        return ()
    metadata = candidate.metadata if isinstance(candidate.metadata, Mapping) else {}
    selector_action = _lower(candidate.selector_action)
    selector_reason = _lower(candidate.selector_reason).replace("-", "_")
    vetoes: list[str] = []
    if selector_action == "reject":
        if selector_reason.startswith("broker_net_pretrade_cost_packet_refused"):
            vetoes.append("broker_cost_packet_refused_not_executable:selector_reason")
        else:
            vetoes.append("selector_reject_not_trade_authority")
    elif selector_reason.startswith("broker_net_pretrade_cost_packet_refused"):
        vetoes.append("broker_cost_packet_refused_not_executable:selector_reason")
    if _truthy(metadata.get("broker_net_pretrade_cost_packet_refused")):
        vetoes.append("broker_cost_packet_refused_not_executable:selector_flag")
    package_executable = metadata.get("package_replay_executable_candidate_use_allowed")
    if package_executable is None:
        package_executable = metadata.get("replay_candidate_use_allowed_now")
    package_evidence_present = bool(
        _truthy(
            metadata.get("package_source_bound_admission_diagnostic")
            or metadata.get("source_bound_package_candidate_use_allowed")
            or metadata.get("ultimate_package_source_bound_candidate_use_allowed")
            or metadata.get("package_replay_source_bound_candidate_use_allowed")
            or metadata.get("package_replay_candidate_use_allowed")
        )
        or (_num(metadata.get("ultimate_package_effective_admission_count"), 0.0) or 0.0)
        > 0.0
        or (_num(metadata.get("ultimate_package_effective_matched_count"), 0.0) or 0.0)
        > 0.0
        or (_num(metadata.get("ultimate_package_admission_sleeve_match_count"), 0.0) or 0.0)
        > 0.0
        or (_num(metadata.get("ultimate_package_matched_sleeve_count"), 0.0) or 0.0)
        > 0.0
        or bool(_mapping(metadata.get("ultimate_candidate_package_open_reduced_risk_authority")))
        or bool(_mapping(metadata.get("ultimate_candidate_package_reduce_risk_authority")))
    )
    if package_executable is False:
        reason = _text(
            metadata.get("package_replay_executable_candidate_use_allowed_reason")
            or metadata.get("replay_candidate_use_allowed_now_reason")
            or "explicit_package_execution_authority_false"
        )
        router_refusal_signed_self_lock = (
            _candidate_source_bound_router_refusal_signed_self_lock_can_rederive(
                candidate,
                reason,
            )
        )
        if reason.startswith("broker_cost_packet_refused"):
            vetoes.append("broker_cost_packet_refused_not_executable:package_status")
        elif (
            _explicit_package_false_reason_can_be_rederived(reason)
            or (
                reason == "ultimate_package_effective_source_bound_not_allowed"
                and _candidate_package_source_bound_executable_present(candidate)
            )
            or router_refusal_signed_self_lock
        ):
            derived_allowed, derived_reason = _candidate_derived_package_executable_authority(
                candidate,
                broker_cost_rank,
                source_bound_executable_present=(
                    True if router_refusal_signed_self_lock else None
                ),
                source_completeness_floor=source_completeness_floor,
                expected_net_r=expected_net_r,
                probability=probability,
                fill_probability=fill_probability,
                source_completeness=source_completeness,
                source_completeness_status=source_completeness_status,
            )
            if not derived_allowed:
                vetoes.append(
                    "package_replay_executable_candidate_use_not_allowed:"
                    f"explicit_false_rederived_failed:{derived_reason}"
                )
        else:
            vetoes.append(f"package_replay_executable_candidate_use_not_allowed:{reason}")
    elif package_executable is True or package_evidence_present:
        allowed, reason, _source = _candidate_package_executable_authority(
            candidate,
            broker_cost_rank,
            source_completeness_floor=source_completeness_floor,
            expected_net_r=expected_net_r,
            probability=probability,
            fill_probability=fill_probability,
            source_completeness=source_completeness,
            source_completeness_status=source_completeness_status,
        )
        if not allowed:
            vetoes.append(
                "package_replay_executable_candidate_use_not_allowed:"
                f"{reason or 'package_execution_authority_revalidation_failed'}"
            )
    package_status = _lower(metadata.get("selected_package_candidate_use_allowed_status"))
    if package_status.startswith("broker_cost_packet_refused"):
        vetoes.append("broker_cost_packet_refused_not_executable:package_status")
    if broker_cost_rank.get("hard_veto_reason") is not None:
        vetoes.append(str(broker_cost_rank.get("hard_veto_reason")))
    return tuple(dict.fromkeys(vetoes))


def _ultimate_package_rank_boost(
    candidate: AllocatorCandidate,
    config: SchedulerV4Config,
) -> tuple[float, dict[str, Any]]:
    if not config.ultimate_candidate_package_rank_boost_enabled:
        return 0.0, {
            "enabled": False,
            "status": "disabled",
        }
    metadata = _mapping(candidate.metadata)
    admission_count = (
        _first_num(
            metadata,
            "ultimate_package_effective_admission_count",
            "ultimate_package_admission_sleeve_match_count",
        )
        if _first_num(
            metadata,
            "ultimate_package_effective_admission_count",
            "ultimate_package_admission_sleeve_match_count",
        )
        is not None
        else
        candidate.ultimate_package_effective_admission_count
        if candidate.ultimate_package_effective_admission_count is not None
        else candidate.ultimate_package_admission_sleeve_match_count
        or 0.0
    )
    matched_count = (
        _first_num(
            metadata,
            "ultimate_package_effective_matched_count",
            "ultimate_package_matched_sleeve_count",
        )
        if _first_num(
            metadata,
            "ultimate_package_effective_matched_count",
            "ultimate_package_matched_sleeve_count",
        )
        is not None
        else
        candidate.ultimate_package_effective_matched_count
        if candidate.ultimate_package_effective_matched_count is not None
        else candidate.ultimate_package_matched_sleeve_count
        or 0.0
    )
    broker_cost_rank = _candidate_broker_cost_rank_diagnostic(candidate)
    source_bound_diagnostic_present = bool(
        _candidate_package_source_bound_diagnostic_present(candidate)
        or candidate.ultimate_package_effective_source_bound_candidate_use_allowed
        or candidate.ultimate_package_source_bound_candidate_use_allowed
    )
    resolved_expected_net_r = _first_num(
        metadata,
        "expected_net_r",
        "candidate_expected_net_r",
        "selected_policy_expected_net_r",
        "broker_net_expected_r",
    )
    if resolved_expected_net_r is None:
        resolved_expected_net_r = candidate.expected_net_r
    resolved_probability = _first_num(
        metadata,
        "probability",
        "candidate_probability",
        "calibrated_probability",
    )
    if resolved_probability is None:
        resolved_probability = candidate.probability
    resolved_fill_probability, _fill_probability_source = (
        _candidate_execution_fill_probability(candidate, fallback=candidate.fill_probability)
    )
    resolved_source_completeness = _first_num(
        metadata,
        "source_completeness",
        "candidate_source_completeness",
        "scheduler_source_completeness",
    )
    if resolved_source_completeness is None:
        resolved_source_completeness = candidate.source_completeness
    resolved_source_completeness_status = _text(
        metadata.get("source_completeness_status")
        or candidate.source_completeness_status
    )
    package_authority_allowed, package_authority_reason, package_authority_source = (
        _candidate_package_executable_authority(
            candidate,
            broker_cost_rank,
            source_completeness_floor=(
                config.selector_reduce_risk_package_fill_floor_min_source_completeness
            ),
            expected_net_r=resolved_expected_net_r,
            probability=resolved_probability,
            fill_probability=resolved_fill_probability,
            source_completeness=resolved_source_completeness,
            source_completeness_status=resolved_source_completeness_status,
        )
    )
    allowed = bool(source_bound_diagnostic_present and package_authority_allowed)
    execution_authority_vetoes = _candidate_execution_authority_vetoes(
        candidate,
        broker_cost_rank,
        source_completeness_floor=(
            config.selector_reduce_risk_package_fill_floor_min_source_completeness
        ),
        expected_net_r=resolved_expected_net_r,
        probability=resolved_probability,
        fill_probability=resolved_fill_probability,
        source_completeness=resolved_source_completeness,
        source_completeness_status=resolved_source_completeness_status,
    )
    explicit_executable = candidate.metadata.get(
        "package_replay_executable_candidate_use_allowed"
    )
    if explicit_executable is None:
        explicit_executable = candidate.metadata.get(
            "replay_candidate_use_allowed_now"
        )
    explicit_executable_present = explicit_executable is not None
    explicit_executable_allowed = (
        _truthy(explicit_executable) if explicit_executable_present else None
    )
    source_status = _lower(resolved_source_completeness_status)
    rank_source_completeness_floor = max(
        config.selector_reduce_risk_package_fill_floor_min_source_completeness,
        config.replay_order_fillability_policy_v1_min_source_completeness,
    )
    source_complete_for_rank = bool(
        (resolved_source_completeness or 0.0) >= rank_source_completeness_floor
        and not any(
            token in source_status
            for token in SOURCE_COMPLETENESS_BLOCKED_STATUS_TOKENS
        )
    )
    poi_lifecycle_contract = _row_causal_poi_lifecycle_contract(metadata)
    poi_lifecycle = _mapping(poi_lifecycle_contract.get("envelope"))
    poi_scheduler_rankable_now = bool(
        not poi_lifecycle_contract.get("required")
        or (
            not poi_lifecycle_contract.get("failures")
            and poi_lifecycle.get("scheduler_rankable_now") is True
        )
    )
    cost_status = broker_cost_rank.get("pretrade_cost_packet_status")
    cost_source_gap_status = broker_cost_rank.get("cost_source_gap_status")
    cost_authority = broker_cost_rank.get("cost_authority")
    source_r_sum = max(
        0.0,
        candidate.ultimate_package_effective_source_bound_signal_r
        if candidate.ultimate_package_effective_source_bound_signal_r is not None
        else candidate.ultimate_package_combined_source_bound_signal_r_sum
        or 0.0,
    )
    source_r_max = max(
        0.0,
        candidate.ultimate_package_max_combined_source_bound_signal_r or 0.0,
    )
    source_r_for_rank = max(source_r_sum, source_r_max)
    source_r_provenance_diagnostic = (
        min(2.0, math.log1p(source_r_for_rank) / 8.0)
        if source_r_for_rank > 0.0
        else 0.0
    )
    source_r_component = min(
        0.03,
        source_r_provenance_diagnostic
        * config.ultimate_candidate_package_rank_source_r_weight
        * 0.05,
    )
    executable_for_rank = bool(
        (explicit_executable_allowed is not False)
        and broker_cost_rank.get("hard_veto_reason") is None
        and cost_status in {"PASSED", "PASS", "OK"}
        and cost_source_gap_status == "source_bound_cost_authority_present"
        and cost_authority == "broker_calibrated_replay_cost"
        and source_complete_for_rank
        and poi_scheduler_rankable_now
    )
    if config.ultimate_candidate_package_rank_boost_require_admission and (
        admission_count <= 0.0 or not allowed
    ):
        return 0.0, {
            "enabled": True,
            "status": "non_admission_or_source_bound_use_not_allowed",
            "require_admission": True,
            "matched_sleeve_count": _round(matched_count),
            "admission_sleeve_match_count": _round(admission_count),
            "source_bound_candidate_use_allowed": allowed,
            "source_bound_candidate_diagnostic_present": source_bound_diagnostic_present,
            "package_executable_authority_source": package_authority_source,
            "package_executable_authority_reason": package_authority_reason,
            "role_disposition": candidate.ultimate_package_role_disposition,
            "effective_evidence_source": candidate.ultimate_package_effective_evidence_source,
            "executable_admission_status": candidate.ultimate_package_executable_admission_status,
            "executable_for_rank": executable_for_rank,
            "broker_cost_rank_status": broker_cost_rank.get("status"),
            "broker_cost_hard_veto_reason": broker_cost_rank.get("hard_veto_reason"),
            "pretrade_cost_packet_status": cost_status,
            "cost_source_gap_status": cost_source_gap_status,
            "cost_authority": cost_authority,
            "source_completeness": _round(candidate.source_completeness),
            "source_completeness_floor": _round(rank_source_completeness_floor),
            "source_completeness_status": candidate.source_completeness_status,
            "poi_lifecycle_required": poi_lifecycle_contract.get("required"),
            "poi_scheduler_rankable_now": poi_scheduler_rankable_now,
            "poi_lifecycle_failures": list(
                poi_lifecycle_contract.get("failures") or []
            ),
            "combined_source_bound_signal_r_sum": _round(source_r_sum),
            "max_combined_source_bound_signal_r": _round(source_r_max),
            "source_r_component": _round(source_r_component),
            "source_r_component_cap": 0.03,
            "source_r_provenance_diagnostic": _round(source_r_provenance_diagnostic),
            "source_r_is_provenance_not_execution_score": True,
            "boost": 0.0,
            "evidence_class": "source_bound_package_replay_parity_scheduler_rank_diagnostic",
        }
    if not executable_for_rank:
        if explicit_executable_allowed is False:
            status = "explicit_package_executable_admission_false"
        elif broker_cost_rank.get("hard_veto_reason"):
            status = "broker_cost_not_executable_for_package_rank_boost"
        elif cost_status not in {"PASSED", "PASS", "OK"}:
            status = "broker_cost_packet_not_passed_for_package_rank_boost"
        elif cost_source_gap_status != "source_bound_cost_authority_present":
            status = "broker_cost_source_gap_not_executable_for_package_rank_boost"
        elif cost_authority != "broker_calibrated_replay_cost":
            status = "broker_cost_authority_not_executable_for_package_rank_boost"
        elif not source_complete_for_rank:
            status = "source_completeness_not_executable_for_package_rank_boost"
        elif not poi_scheduler_rankable_now:
            status = "poi_lifecycle_not_scheduler_rankable_for_package_rank_boost"
        else:
            status = "package_executable_rank_boost_not_allowed"
        return 0.0, {
            "enabled": True,
            "status": status,
            "require_admission": bool(
                config.ultimate_candidate_package_rank_boost_require_admission
            ),
            "matched_sleeve_count": _round(matched_count),
            "admission_sleeve_match_count": _round(admission_count),
            "source_bound_candidate_use_allowed": allowed,
            "source_bound_candidate_diagnostic_present": source_bound_diagnostic_present,
            "package_executable_authority_source": package_authority_source,
            "package_executable_authority_reason": package_authority_reason,
            "explicit_executable_candidate_use_allowed": explicit_executable_allowed,
            "explicit_executable_candidate_use_allowed_present": explicit_executable_present,
            "executable_for_rank": False,
            "effective_evidence_source": candidate.ultimate_package_effective_evidence_source,
            "executable_admission_status": candidate.ultimate_package_executable_admission_status,
            "role_disposition": candidate.ultimate_package_role_disposition,
            "broker_cost_rank_status": broker_cost_rank.get("status"),
            "broker_cost_hard_veto_reason": broker_cost_rank.get("hard_veto_reason"),
            "pretrade_cost_packet_status": cost_status,
            "cost_source_gap_status": cost_source_gap_status,
            "cost_authority": cost_authority,
            "source_completeness": _round(candidate.source_completeness),
            "source_completeness_floor": _round(rank_source_completeness_floor),
            "source_completeness_status": candidate.source_completeness_status,
            "poi_lifecycle_required": poi_lifecycle_contract.get("required"),
            "poi_scheduler_rankable_now": poi_scheduler_rankable_now,
            "poi_lifecycle_failures": list(
                poi_lifecycle_contract.get("failures") or []
            ),
            "source_r_is_provenance_not_execution_score": True,
            "boost": 0.0,
            "evidence_class": "source_bound_package_replay_parity_scheduler_rank_diagnostic",
        }

    selector_shadow_score = max(
        0.0,
        candidate.ultimate_package_selector_shadow_score or 0.0,
    )
    selector_component = (
        selector_shadow_score * config.ultimate_candidate_package_rank_score_weight
    )
    admission_component = (
        min(5.0, admission_count)
        * config.ultimate_candidate_package_rank_admission_weight
    )
    raw_boost = selector_component + source_r_component + admission_component
    boost = _clamp(
        raw_boost,
        0.0,
        max(0.0, config.ultimate_candidate_package_rank_max_boost),
    )
    return boost, {
        "enabled": True,
        "status": "package_parity_rank_boost_applied" if boost > 0.0 else "no_positive_boost",
        "require_admission": bool(
            config.ultimate_candidate_package_rank_boost_require_admission
        ),
        "matched_sleeve_count": _round(matched_count),
        "admission_sleeve_match_count": _round(admission_count),
        "source_bound_candidate_use_allowed": allowed,
        "source_bound_candidate_diagnostic_present": source_bound_diagnostic_present,
        "package_executable_authority_source": package_authority_source,
        "package_executable_authority_reason": package_authority_reason,
        "explicit_executable_candidate_use_allowed": explicit_executable_allowed,
        "explicit_executable_candidate_use_allowed_present": explicit_executable_present,
        "executable_for_rank": True,
        "effective_evidence_source": candidate.ultimate_package_effective_evidence_source,
        "executable_admission_status": candidate.ultimate_package_executable_admission_status,
        "role_disposition": candidate.ultimate_package_role_disposition,
        "broker_cost_rank_status": broker_cost_rank.get("status"),
        "broker_cost_hard_veto_reason": broker_cost_rank.get("hard_veto_reason"),
        "pretrade_cost_packet_status": cost_status,
        "cost_source_gap_status": cost_source_gap_status,
        "source_completeness": _round(candidate.source_completeness),
        "source_completeness_floor": _round(rank_source_completeness_floor),
        "source_completeness_status": candidate.source_completeness_status,
        "poi_lifecycle_required": poi_lifecycle_contract.get("required"),
        "poi_scheduler_rankable_now": poi_scheduler_rankable_now,
        "poi_lifecycle_failures": list(
            poi_lifecycle_contract.get("failures") or []
        ),
        "selector_shadow_score": _round(selector_shadow_score),
        "combined_source_bound_signal_r_sum": _round(source_r_sum),
        "max_combined_source_bound_signal_r": _round(source_r_max),
        "selector_component": _round(selector_component),
        "source_r_component": _round(source_r_component),
        "source_r_component_cap": 0.03,
        "source_r_provenance_diagnostic": _round(source_r_provenance_diagnostic),
        "source_r_is_provenance_not_execution_score": True,
        "admission_component": _round(admission_component),
        "raw_boost": _round(raw_boost),
        "boost": _round(boost),
        "max_boost": _round(config.ultimate_candidate_package_rank_max_boost),
        "evidence_class": "source_bound_package_replay_parity_scheduler_rank",
    }


def _pending_edge_score(row: Mapping[str, Any]) -> float:
    ev = _num(row.get("ev_r") or row.get("candidate_ev_r") or row.get("expectancy_r"), 0.0) or 0.0
    probability = (
        _num(
            row.get("probability")
            or row.get("candidate_probability")
            or row.get("calibrated_probability"),
            0.50,
        )
        or 0.50
    )
    fill_probability, _fill_source = _execution_fillability_from_source(row)
    fill_probability = fill_probability if fill_probability is not None else 0.0
    cost = _num(row.get("cost_r") or row.get("expected_cost_r") or row.get("spread_r"), 0.0) or 0.0
    scheduler_score = _num(
        row.get("scheduler_score")
        or row.get("scheduler_option_score")
        or row.get("selected_scheduler_score")
    )
    if scheduler_score is not None:
        return scheduler_score
    return (
        ev
        - cost
        + max(0.0, probability - 0.50)
        + fill_probability * 0.10
    )


def _pending_row_sources(row: Mapping[str, Any]) -> tuple[Mapping[str, Any], ...]:
    sources: list[Mapping[str, Any]] = [row]
    for key in ("metadata", "risk_authority", "execution_quality_attribution"):
        nested = row.get(key)
        if isinstance(nested, Mapping):
            sources.append(nested)
    return tuple(sources)


def _pending_first_num_with_source(
    row: Mapping[str, Any],
    *keys: str,
) -> tuple[float | None, str | None]:
    for source_index, source in enumerate(_pending_row_sources(row)):
        for key in keys:
            value = _num(source.get(key))
            if value is not None:
                prefix = "pending_row" if source_index == 0 else f"pending_nested:{key}"
                return value, f"{prefix}.{key}" if source_index == 0 else prefix
    return None, None


def _pending_execution_fillability_with_source(
    row: Mapping[str, Any],
) -> tuple[float | None, str | None]:
    for source_index, source in enumerate(_pending_row_sources(row)):
        value, key = _execution_fillability_from_source(source)
        if value is not None:
            prefix = "pending_row" if source_index == 0 else "pending_nested"
            return value, f"{prefix}.{key}"
        if key == INVALID_SIGNED_EXECUTION_FILLABILITY_SOURCE:
            return None, key
    return None, None


def _pending_expected_net_with_source(
    row: Mapping[str, Any],
) -> tuple[float | None, str | None, list[str]]:
    value, source = _pending_first_num_with_source(
        row,
        "candidate_expected_net_r",
        "expected_net_r",
        "selected_expected_net_r",
        "scheduler_expected_net_r",
        "broker_net_expected_r",
        "expected_net_after_cost_r",
    )
    if value is not None:
        return value, source, []
    ev, ev_source = _pending_first_num_with_source(
        row,
        "candidate_ev_r",
        "ev_r",
        "expectancy_r",
    )
    cost, cost_source = _pending_first_num_with_source(
        row,
        "expected_cost_r",
        "cost_r",
        "predecision_expected_cost_r",
        "execution_expected_cost_r",
        "spread_r",
    )
    if ev is None or cost is None:
        return None, None, ["pending_expected_net_r_missing"]
    return ev - cost, f"derived:{ev_source}-minus-{cost_source}", [
        "pending_expected_net_r_derived_from_predecision_ev_minus_cost"
    ]


def _pending_replacement_causal_quality_gate(
    *,
    candidate_expected_net_r: float,
    candidate_fill_probability: float,
    candidate_source_completeness: float,
    candidate_risk_pct: float,
    candidate_cost_r: float,
    candidate_broker_cost_rank: Mapping[str, Any],
    pending_row: Mapping[str, Any],
    min_expected_net_delta: float,
    release_reason: str,
    require_stronger_net_for_higher_cost_or_risk: bool = True,
    allow_fill_tradeoff_when_expected_transfer_improves: bool = False,
) -> dict[str, Any]:
    failures: list[str] = []
    notes: list[str] = []
    hard_veto = _text(candidate_broker_cost_rank.get("hard_veto_reason"))
    if hard_veto:
        failures.append(f"candidate_broker_cost_not_executable:{hard_veto}")

    pending_expected_net, pending_expected_net_source, pending_net_notes = (
        _pending_expected_net_with_source(pending_row)
    )
    notes.extend(pending_net_notes)
    pending_fill, pending_fill_source = _pending_execution_fillability_with_source(
        pending_row
    )
    pending_cost, pending_cost_source = _pending_first_num_with_source(
        pending_row,
        "expected_cost_r",
        "cost_r",
        "predecision_expected_cost_r",
        "execution_expected_cost_r",
        "spread_r",
    )
    pending_source, pending_source_source = _pending_first_num_with_source(
        pending_row,
        "source_completeness",
        "candidate_source_completeness",
        "scheduler_source_completeness",
    )
    pending_risk, pending_risk_source = _pending_first_num_with_source(
        pending_row,
        "reserved_risk_pct",
        "risk_pct",
        "worst_case_risk_pct",
    )
    if pending_expected_net is None:
        failures.append("pending_expected_net_r_missing")
        pending_expected_net = 0.0
    pending_fill_missing = pending_fill is None
    if pending_fill_missing:
        failures.append("pending_fill_probability_missing")
        pending_fill = 1.0
    if pending_cost is None:
        failures.append("pending_expected_cost_r_missing")
        pending_cost = 0.0
    if pending_source is None:
        failures.append("pending_source_completeness_missing")
        pending_source = 1.0
    if pending_risk is None:
        failures.append("pending_reserved_risk_pct_missing")
        pending_risk = 0.0

    expected_net_delta = candidate_expected_net_r - pending_expected_net
    fill_delta = candidate_fill_probability - pending_fill
    candidate_expected_transfer_score = (
        candidate_expected_net_r * candidate_fill_probability
    )
    pending_expected_transfer_score = pending_expected_net * pending_fill
    expected_transfer_delta = (
        candidate_expected_transfer_score - pending_expected_transfer_score
    )
    min_expected_transfer_delta = max(0.0, min_expected_net_delta) * min(
        candidate_fill_probability,
        pending_fill,
    )
    fill_tradeoff_expected_transfer_dominates = bool(
        allow_fill_tradeoff_when_expected_transfer_improves
        and expected_transfer_delta + 1e-12 >= min_expected_transfer_delta
    )
    cost_delta = candidate_cost_r - pending_cost
    source_delta = candidate_source_completeness - pending_source
    risk_delta = candidate_risk_pct - pending_risk
    stronger_delta_floor = max(min_expected_net_delta * 2.0, 0.40)
    if expected_net_delta + 1e-12 < min_expected_net_delta:
        failures.append("candidate_expected_net_delta_below_pending_floor")
    if (
        not pending_fill_missing
        and fill_delta < -1e-12
        and not fill_tradeoff_expected_transfer_dominates
    ):
        failures.append("candidate_fill_probability_worse_than_pending")
    elif not pending_fill_missing and fill_delta < -1e-12:
        notes.append(
            "candidate_lower_fill_probability_accepted_by_expected_transfer_dominance"
        )
    if (
        require_stronger_net_for_higher_cost_or_risk
        and cost_delta > 1e-12
        and expected_net_delta + 1e-12 < stronger_delta_floor
    ):
        failures.append("candidate_expected_cost_worse_than_pending_without_stronger_net_delta")
    if source_delta < -1e-12:
        failures.append("candidate_source_completeness_worse_than_pending")
    if (
        require_stronger_net_for_higher_cost_or_risk
        and risk_delta > 1e-12
        and expected_net_delta + 1e-12 < stronger_delta_floor
    ):
        failures.append("candidate_risk_pct_exceeds_pending_without_stronger_net_delta")

    return {
        "status": "passed" if not failures else "failed",
        "passed": not failures,
        "failures": failures,
        "notes": notes,
        "release_reason": release_reason,
        "min_expected_net_delta": _round(min_expected_net_delta),
        "stronger_delta_floor": _round(stronger_delta_floor),
        "require_stronger_net_for_higher_cost_or_risk": (
            require_stronger_net_for_higher_cost_or_risk
        ),
        "allow_fill_tradeoff_when_expected_transfer_improves": (
            allow_fill_tradeoff_when_expected_transfer_improves
        ),
        "candidate_expected_net_r": _round(candidate_expected_net_r),
        "pending_expected_net_r": _round(pending_expected_net),
        "expected_net_delta": _round(expected_net_delta),
        "pending_expected_net_source": pending_expected_net_source,
        "candidate_fill_probability": _round(candidate_fill_probability),
        "pending_fill_probability": _round(pending_fill),
        "fill_probability_delta": _round(fill_delta),
        "candidate_expected_transfer_score": _round(
            candidate_expected_transfer_score
        ),
        "pending_expected_transfer_score": _round(
            pending_expected_transfer_score
        ),
        "expected_transfer_delta": _round(expected_transfer_delta),
        "min_expected_transfer_delta": _round(min_expected_transfer_delta),
        "fill_tradeoff_expected_transfer_dominates": (
            fill_tradeoff_expected_transfer_dominates
        ),
        "pending_fill_probability_source": pending_fill_source,
        "candidate_expected_cost_r": _round(candidate_cost_r),
        "pending_expected_cost_r": _round(pending_cost),
        "expected_cost_delta": _round(cost_delta),
        "pending_expected_cost_source": pending_cost_source,
        "candidate_source_completeness": _round(candidate_source_completeness),
        "pending_source_completeness": _round(pending_source),
        "source_completeness_delta": _round(source_delta),
        "pending_source_completeness_source": pending_source_source,
        "candidate_risk_pct": _round(candidate_risk_pct),
        "pending_reserved_risk_pct": _round(pending_risk),
        "risk_pct_delta": _round(risk_delta),
        "pending_reserved_risk_source": pending_risk_source,
        "candidate_broker_cost_rank_status": candidate_broker_cost_rank.get("status"),
        "candidate_broker_cost_hard_veto_reason": (
            candidate_broker_cost_rank.get("hard_veto_reason")
        ),
        "source_boundary": "predecision_candidate_quality_vs_pending_order_snapshot",
        "uses_outcome_fields": False,
    }


def _pending_replacement_diagnostic(
    *,
    candidate: AllocatorCandidate,
    snapshot: ExposureSnapshot,
    config: SchedulerV4Config,
    candidate_edge: float,
    ev_r: float,
    probability: float,
    cost_total: float,
) -> dict[str, Any]:
    cluster = cluster_key(candidate.symbol)
    symbol_key = candidate.symbol.upper()
    diagnostic: dict[str, Any] = {
        "enabled": bool(config.pending_replacement_enabled),
        "candidate_edge_score": _round(candidate_edge),
        "candidate_ev_r": _round(ev_r),
        "candidate_probability": _round(probability),
        "candidate_cost_total_r": _round(cost_total),
        "candidate_cluster_key": cluster,
        "candidate_symbol": symbol_key,
        "replacement_applied": False,
        "release_pending_ids": [],
        "release_candidates": [],
        "rejected_release_candidates": [],
        "portfolio_release_risk_pct": 0.0,
        "cluster_release_risk_pct": 0.0,
        "same_symbol_release_risk_pct": 0.0,
        "pending_replacement_causal_quality_gate_required": True,
        "pending_replacement_causal_quality_gate_status": "not_evaluated",
        "reason": "not_evaluated",
    }
    if not config.pending_replacement_enabled:
        diagnostic["reason"] = "pending_replacement_disabled"
        return diagnostic
    if candidate.action_intent not in NEW_RISK_ACTIONS:
        diagnostic["reason"] = "candidate_action_not_new_risk"
        return diagnostic
    if ev_r < config.pending_replacement_min_candidate_ev_r:
        diagnostic["reason"] = "candidate_ev_below_pending_replacement_floor"
        return diagnostic
    if probability < config.pending_replacement_min_candidate_probability:
        diagnostic["reason"] = "candidate_probability_below_pending_replacement_floor"
        return diagnostic

    expected_net_r = (
        candidate.expected_net_r
        if candidate.expected_net_r is not None
        else ev_r - cost_total
    )
    fill_probability = _clamp(
        candidate.fill_probability if candidate.fill_probability is not None else 0.25,
        0.0,
        1.0,
    )
    entry_quality_fill_probability = fill_probability
    execution_fill_probability, execution_fill_probability_source = (
        _candidate_execution_fill_probability(candidate, fallback=None)
    )
    execution_fill_probability_for_gate = (
        execution_fill_probability
        if execution_fill_probability is not None
        else 0.0
    )
    collision_release_fill_probability = execution_fill_probability_for_gate
    candidate_risk_pct = (
        _num(candidate.requested_risk_pct)
        or _num(candidate.selected_cell_risk_pct)
        or 0.0
    )
    source_completeness = source_completeness_score(
        candidate.source_completeness,
        candidate.source_completeness_status,
    )
    package_admission_count = (
        candidate.ultimate_package_effective_admission_count
        if candidate.ultimate_package_effective_admission_count is not None
        else candidate.ultimate_package_admission_sleeve_match_count
        or 0.0
    )
    package_matched_count = (
        candidate.ultimate_package_effective_matched_count
        if candidate.ultimate_package_effective_matched_count is not None
        else candidate.ultimate_package_matched_sleeve_count
        or 0.0
    )
    package_role = _lower(candidate.ultimate_package_role_disposition)
    candidate_metadata = _mapping(candidate.metadata)
    explicit_package_replay_executable_allowed = _truthy(
        _first_present_value(
            candidate_metadata.get("package_replay_executable_candidate_use_allowed"),
            candidate_metadata.get("replay_candidate_use_allowed_now"),
        )
    )
    broker_cost_rank = _candidate_broker_cost_rank_diagnostic(candidate)
    package_source_bound_diagnostic_present = (
        _candidate_package_source_bound_diagnostic_present(candidate)
    )
    package_source_bound_executable_present = (
        _candidate_package_source_bound_executable_present(candidate)
    )
    package_authority_allowed, package_authority_reason, package_authority_source = (
        _candidate_package_executable_authority(
            candidate,
            broker_cost_rank,
            source_completeness_floor=(
                config.selector_reduce_risk_package_fill_floor_min_source_completeness
            ),
        )
    )
    package_source_bound_allowed = bool(
        package_source_bound_executable_present
        and package_authority_allowed
    )
    package_admission_allowed = bool(
        package_source_bound_allowed
        and (
            (package_admission_count > 0.0 and package_matched_count > 0.0)
            or explicit_package_replay_executable_allowed
        )
        and package_role not in PACKAGE_HOLD_ROLE_DISPOSITIONS
    )
    package_opposite_pending_collision_release_enabled = bool(
        config.package_opposite_side_close_reverse_enabled
        and package_admission_allowed
        and not broker_cost_rank.get("hard_veto_reason")
        and expected_net_r >= config.package_opposite_side_close_reverse_min_expected_net_r
        and probability >= config.package_opposite_side_close_reverse_min_probability
        and collision_release_fill_probability
        >= config.package_opposite_side_pending_collision_min_fill_probability
        and source_completeness
        >= config.package_opposite_side_close_reverse_min_source_completeness
    )
    diagnostic["package_opposite_pending_collision_release"] = {
        "enabled": config.package_opposite_side_close_reverse_enabled,
        "eligible": package_opposite_pending_collision_release_enabled,
        "package_admission_allowed": package_admission_allowed,
        "source_bound_package_candidate_diagnostic_present": (
            package_source_bound_diagnostic_present
        ),
        "package_executable_authority_source": package_authority_source,
        "package_executable_authority_reason": package_authority_reason,
        "broker_cost_rank_status": broker_cost_rank.get("status"),
        "broker_cost_hard_veto_reason": broker_cost_rank.get("hard_veto_reason"),
        "expected_net_r": _round(expected_net_r),
        "probability": _round(probability),
        "fill_probability": _round(execution_fill_probability),
        "entry_quality_fill_probability": _round(entry_quality_fill_probability),
        "collision_release_fill_probability": _round(
            collision_release_fill_probability
        ),
        "min_collision_release_fill_probability": _round(
            config.package_opposite_side_pending_collision_min_fill_probability
        ),
        "execution_fill_probability": _round(execution_fill_probability),
        "execution_fill_probability_source": execution_fill_probability_source,
        "source_completeness": _round(source_completeness),
        "min_edge_delta": _round(
            config.package_opposite_side_pending_collision_min_edge_delta
        ),
        "source_boundary": "predecision_package_quality_cost_and_pending_state",
    }

    release_rows: list[dict[str, Any]] = []
    rejected_release_rows: list[dict[str, Any]] = []
    for row in snapshot.pending_orders:
        pending_symbol = _text(row.get("symbol")).upper()
        pending_cluster = cluster_key(pending_symbol)
        if pending_cluster != cluster and pending_symbol != symbol_key:
            continue
        pending_id = pending_exposure_id_from_mapping(row)
        pending_side = pending_exposure_side_from_mapping(row)
        reserved = _num(row.get("reserved_risk_pct") or row.get("risk_pct"), 0.0) or 0.0
        if not pending_id or reserved <= 0.0:
            continue
        age = _num(row.get("age_minutes"), 0.0) or 0.0
        if age < config.pending_replacement_min_pending_age_minutes:
            continue
        pending_edge = _pending_edge_score(row)
        edge_delta = candidate_edge - pending_edge
        pending_ev = (
            _num(row.get("ev_r") or row.get("candidate_ev_r") or row.get("expectancy_r"), 0.0)
            or 0.0
        )
        pending_probability = (
            _num(
                row.get("probability")
                or row.get("candidate_probability")
                or row.get("calibrated_probability"),
                0.50,
            )
            or 0.50
        )
        pending_expected_net_for_collision, pending_expected_net_source, _ = (
            _pending_expected_net_with_source(row)
        )
        collision_expected_net_delta = (
            expected_net_r - pending_expected_net_for_collision
            if pending_expected_net_for_collision is not None
            else None
        )
        dominated = (
            edge_delta >= config.pending_replacement_min_edge_delta
            or pending_ev < 0.0
            or pending_probability < 0.55
        )
        same_symbol_opposite_pending_collision = (
            package_opposite_pending_collision_release_enabled
            and pending_symbol == symbol_key
            and pending_side not in {"UNKNOWN", candidate.side}
            and collision_expected_net_delta is not None
            and collision_expected_net_delta
            >= config.package_opposite_side_pending_collision_min_edge_delta
        )
        package_same_side_pending_duplicate_release = (
            candidate.action_intent == "replace_pending"
            and package_admission_allowed
            and not broker_cost_rank.get("hard_veto_reason")
            and pending_symbol == symbol_key
            and pending_side == candidate.side
        )
        if (
            not dominated
            and not same_symbol_opposite_pending_collision
            and not package_same_side_pending_duplicate_release
        ):
            continue
        generic_gate = (
            _pending_replacement_causal_quality_gate(
                candidate_expected_net_r=expected_net_r,
                candidate_fill_probability=execution_fill_probability_for_gate,
                candidate_source_completeness=source_completeness,
                candidate_risk_pct=candidate_risk_pct,
                candidate_cost_r=cost_total,
                candidate_broker_cost_rank=broker_cost_rank,
                pending_row=row,
                min_expected_net_delta=config.pending_replacement_min_edge_delta,
                release_reason="candidate_dominates_pending_risk_in_cluster",
            )
            if dominated
            else None
        )
        collision_gate = (
            _pending_replacement_causal_quality_gate(
                candidate_expected_net_r=expected_net_r,
                candidate_fill_probability=collision_release_fill_probability,
                candidate_source_completeness=source_completeness,
                candidate_risk_pct=candidate_risk_pct,
                candidate_cost_r=cost_total,
                candidate_broker_cost_rank=broker_cost_rank,
                pending_row=row,
                min_expected_net_delta=(
                    config.package_opposite_side_pending_collision_min_edge_delta
                ),
                release_reason="package_opposite_side_pending_collision_release",
                require_stronger_net_for_higher_cost_or_risk=False,
                allow_fill_tradeoff_when_expected_transfer_improves=True,
            )
            if same_symbol_opposite_pending_collision
            else None
        )
        same_side_duplicate_gate = (
            _pending_replacement_causal_quality_gate(
                candidate_expected_net_r=expected_net_r,
                candidate_fill_probability=execution_fill_probability_for_gate,
                candidate_source_completeness=source_completeness,
                candidate_risk_pct=candidate_risk_pct,
                candidate_cost_r=cost_total,
                candidate_broker_cost_rank=broker_cost_rank,
                pending_row=row,
                min_expected_net_delta=(
                    config.package_same_side_pending_duplicate_min_expected_net_delta
                ),
                release_reason="package_same_side_pending_duplicate_release",
                require_stronger_net_for_higher_cost_or_risk=(
                    config.package_same_side_pending_duplicate_require_stronger_net_for_higher_cost_or_risk
                ),
            )
            if package_same_side_pending_duplicate_release
            else None
        )
        passed_gate = (
            collision_gate
            if collision_gate and collision_gate.get("passed") is True
            else same_side_duplicate_gate
            if same_side_duplicate_gate
            and same_side_duplicate_gate.get("passed") is True
            else generic_gate
            if generic_gate and generic_gate.get("passed") is True
            else None
        )
        if not passed_gate:
            rejected_release_reason = (
                "package_opposite_side_pending_collision_release"
                if same_symbol_opposite_pending_collision
                else "package_same_side_pending_duplicate_release"
                if package_same_side_pending_duplicate_release
                else "candidate_dominates_pending_risk_in_cluster"
            )
            rejected_release_gate_delta = (
                collision_expected_net_delta
                if rejected_release_reason
                == "package_opposite_side_pending_collision_release"
                else edge_delta
            )
            rejected_release_rows.append(
                {
                    "pending_id": pending_id,
                    "symbol": pending_symbol,
                    "side": pending_side,
                    "cluster_key": pending_cluster,
                    "reserved_risk_pct": _round(reserved),
                    "age_minutes": _round(age),
                    "pending_edge_score": _round(pending_edge),
                    "pending_ev_r": _round(pending_ev),
                    "pending_probability": _round(pending_probability),
                    "candidate_edge_delta": _round(edge_delta),
                    "collision_expected_net_delta": (
                        _round(collision_expected_net_delta)
                        if collision_expected_net_delta is not None
                        else None
                    ),
                    "release_gate_delta": _round(rejected_release_gate_delta),
                    "release_gate_delta_metric": (
                        "collision_expected_net_delta"
                        if rejected_release_reason
                        == "package_opposite_side_pending_collision_release"
                        else "candidate_edge_delta"
                    ),
                    "collision_pending_expected_net_source": (
                        pending_expected_net_source
                    ),
                    "dominated_by_generic_edge_rule": dominated,
                    "same_symbol_same_side_pending_duplicate_release": (
                        package_same_side_pending_duplicate_release
                    ),
                    "same_symbol_opposite_pending_collision": (
                        same_symbol_opposite_pending_collision
                    ),
                    "pending_replacement_causal_quality_gate_status": "failed",
                    "generic_causal_quality_gate": generic_gate,
                    "collision_causal_quality_gate": collision_gate,
                    "same_side_duplicate_causal_quality_gate": same_side_duplicate_gate,
                    "release_rejected_reason": (
                        "pending_replacement_causal_quality_gate_failed"
                    ),
                }
            )
            continue
        release_reason = str(passed_gate.get("release_reason") or "")
        release_gate_delta = (
            collision_expected_net_delta
            if release_reason == "package_opposite_side_pending_collision_release"
            else edge_delta
        )
        release_rows.append(
            {
                "pending_id": pending_id,
                "symbol": pending_symbol,
                "side": pending_side,
                "cluster_key": pending_cluster,
                "reserved_risk_pct": _round(reserved),
                "age_minutes": _round(age),
                "pending_edge_score": _round(pending_edge),
                "pending_ev_r": _round(pending_ev),
                "pending_probability": _round(pending_probability),
                "candidate_edge_delta": _round(edge_delta),
                "collision_expected_net_delta": (
                    _round(collision_expected_net_delta)
                    if collision_expected_net_delta is not None
                    else None
                ),
                "release_gate_delta": _round(release_gate_delta),
                "release_gate_delta_metric": (
                    "collision_expected_net_delta"
                    if release_reason == "package_opposite_side_pending_collision_release"
                    else "candidate_edge_delta"
                ),
                "collision_pending_expected_net_source": (
                    pending_expected_net_source
                ),
                "release_reason": release_reason,
                "dominated_by_generic_edge_rule": dominated,
                "same_symbol_same_side_pending_duplicate_release": (
                    package_same_side_pending_duplicate_release
                ),
                "same_symbol_opposite_pending_collision": (
                    same_symbol_opposite_pending_collision
                ),
                "pending_replacement_causal_quality_gate_status": "passed",
                "pending_replacement_causal_quality_gate": passed_gate,
            }
        )

    for release_row in release_rows:
        release_quality = _pending_release_quality_score(release_row)
        release_row["replacement_release_quality_score"] = _round(release_quality)
        release_row[
            "replacement_release_quality_source_boundary"
        ] = "predecision_pending_replacement_causal_quality_gate_no_outcome_fields"
    diagnostic["rejected_release_candidates"] = rejected_release_rows
    release_rows.sort(
        key=lambda item: (
            1 if item.get("symbol") == symbol_key else 0,
            item.get("replacement_release_quality_score") or 0.0,
            item.get("candidate_edge_delta") or 0.0,
            item.get("reserved_risk_pct") or 0.0,
        ),
        reverse=True,
    )
    if not release_rows:
        diagnostic["reason"] = "no_dominated_pending_risk_in_candidate_cluster"
        if rejected_release_rows:
            diagnostic["reason"] = "pending_replacement_causal_quality_gate_failed"
            diagnostic["pending_replacement_causal_quality_gate_status"] = "failed"
        return diagnostic

    portfolio_release = sum(float(row["reserved_risk_pct"] or 0.0) for row in release_rows)
    cluster_release = sum(
        float(row["reserved_risk_pct"] or 0.0)
        for row in release_rows
        if row.get("cluster_key") == cluster
    )
    same_symbol_release = sum(
        float(row["reserved_risk_pct"] or 0.0)
        for row in release_rows
        if row.get("symbol") == symbol_key
    )
    diagnostic.update(
        {
            "replacement_applied": True,
            "release_pending_ids": [row["pending_id"] for row in release_rows],
            "release_candidates": release_rows,
            "portfolio_release_risk_pct": _round(portfolio_release) or 0.0,
            "cluster_release_risk_pct": _round(cluster_release) or 0.0,
            "same_symbol_release_risk_pct": _round(same_symbol_release) or 0.0,
            "pending_replacement_causal_quality_gate_status": "passed",
            "reason": (
                "package_opposite_side_pending_collision_release"
                if any(
                    row.get("release_reason")
                    == "package_opposite_side_pending_collision_release"
                    for row in release_rows
                )
                else "package_same_side_pending_duplicate_release"
                if any(
                    row.get("release_reason")
                    == "package_same_side_pending_duplicate_release"
                    for row in release_rows
                )
                else "candidate_dominates_pending_risk_in_cluster"
            ),
        }
    )
    return diagnostic


def _pending_replacement_from_option(option: AllocatorOption) -> Mapping[str, Any]:
    components = option.score_components
    if not isinstance(components, Mapping):
        return {}
    diagnostic = components.get("pending_replacement_diagnostic")
    return diagnostic if isinstance(diagnostic, Mapping) else {}


def _pending_replacement_runtime_applied(
    diagnostic: Mapping[str, Any] | None,
) -> bool:
    diagnostic = diagnostic if isinstance(diagnostic, Mapping) else {}
    if (
        _lower(diagnostic.get("pending_replacement_causal_quality_gate_status"))
        != "passed"
    ):
        return False
    if "runtime_replacement_applied" in diagnostic:
        return _truthy(diagnostic.get("runtime_replacement_applied"))
    return False


def _pending_replacement_runtime_release_pending_ids(
    diagnostic: Mapping[str, Any] | None,
) -> set[str]:
    diagnostic = diagnostic if isinstance(diagnostic, Mapping) else {}
    if (
        _pending_replacement_runtime_applied(diagnostic)
        and "runtime_release_pending_ids" in diagnostic
    ):
        raw_ids = diagnostic.get("runtime_release_pending_ids")
    else:
        raw_ids = []
    if raw_ids in (None, "", [], {}):
        return set()
    values = raw_ids if isinstance(raw_ids, (list, tuple, set)) else (raw_ids,)
    return {str(raw or "").strip() for raw in values if str(raw or "").strip()}


def _unused_pending_release(
    option: AllocatorOption,
    *,
    cluster: str,
    used_pending_ids: set[str],
) -> tuple[float, float, list[str]]:
    diagnostic = _pending_replacement_from_option(option)
    runtime_release_ids = _pending_replacement_runtime_release_pending_ids(diagnostic)
    if not runtime_release_ids:
        return 0.0, 0.0, []
    rows = diagnostic.get("release_candidates")
    if not isinstance(rows, Sequence) or isinstance(rows, (str, bytes, bytearray)):
        return 0.0, 0.0, []
    portfolio_release = 0.0
    cluster_release = 0.0
    released_ids: list[str] = []
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        pending_id = _text(row.get("pending_id"))
        if (
            not pending_id
            or pending_id in used_pending_ids
            or pending_id not in runtime_release_ids
        ):
            continue
        risk = _num(row.get("reserved_risk_pct"), 0.0) or 0.0
        if risk <= 0.0:
            continue
        portfolio_release += risk
        if row.get("cluster_key") == cluster:
            cluster_release += risk
        released_ids.append(pending_id)
    return portfolio_release, cluster_release, released_ids


def _candidate_predecision_limit_fillability(
    candidate: "AllocatorCandidate",
) -> Mapping[str, Any]:
    metadata = candidate.metadata if isinstance(candidate.metadata, Mapping) else {}
    decision_inputs = _candidate_decision_inputs(metadata)
    for value in (
        decision_inputs.get("predecision_limit_fillability"),
        metadata.get("predecision_limit_fillability"),
        metadata.get("limit_fillability"),
    ):
        fillability = _mapping(value)
        if fillability:
            return fillability
    return {}


def _candidate_source_fields(candidate: "AllocatorCandidate") -> Mapping[str, Any]:
    metadata = candidate.metadata if isinstance(candidate.metadata, Mapping) else {}
    decision_inputs = _candidate_decision_inputs(metadata)
    for value in (
        decision_inputs.get("source_fields"),
        metadata.get("source_fields"),
        metadata.get("candidate_source_fields"),
    ):
        fields = _mapping(value)
        if fields:
            return fields
    return {}


POI_STATE_DECISION_INPUT_KEYS = (
    "poi_state",
    "poi_state_hash_sha256",
    "poi_state_contract_status",
    "poi_state_contract_failures",
    "poi_state_contract_valid",
    "poi_state_execution_allowed",
    "poi_distance_to_zone_price",
    "poi_distance_to_zone_atr",
    "poi_distance_to_midpoint_price",
    "poi_distance_to_midpoint_atr",
    "poi_state_transfer_status",
    "causal_poi_lifecycle_required",
    "causal_poi_lifecycle",
    "causal_poi_lifecycle_hash_sha256",
    "poi_scheduler_rankable_now",
    "poi_execution_allowed_by_lifecycle",
    *POI_STATE_ATOMIC_FIELDS,
)

PREDECISION_MARKET_DECISION_INPUT_KEYS = (
    "current_price",
    "predecision_current_price",
    "predecision_current_price_source",
    "predecision_current_price_source_boundary",
    "predecision_current_price_source_time_utc",
    "predecision_market_snapshot_transfer_status",
    "predecision_market_snapshot_source_boundary",
    "predecision_market_snapshot_source_field_keys",
    *POI_STATE_DECISION_INPUT_KEYS,
)


def _candidate_predecision_market_decision_input_payload(
    candidate: "AllocatorCandidate",
) -> Mapping[str, Any]:
    metadata = candidate.metadata if isinstance(candidate.metadata, Mapping) else {}
    decision_inputs = _candidate_decision_inputs(metadata)
    source_fields = _candidate_source_fields(candidate)
    payload: dict[str, Any] = {}
    if source_fields:
        payload["source_fields"] = dict(source_fields)
        payload["candidate_source_fields"] = dict(source_fields)
    source_field_aliases = {
        "current_price": ("current_price",),
        "predecision_current_price": ("current_price",),
        "predecision_current_price_source": ("current_price_source",),
        "predecision_current_price_source_boundary": (
            "current_price_source_boundary",
        ),
        "predecision_current_price_source_time_utc": (
            "current_price_source_time_utc",
        ),
    }
    source_field_aliases.update(
        {key: (key,) for key in POI_STATE_DECISION_INPUT_KEYS}
    )
    for key in PREDECISION_MARKET_DECISION_INPUT_KEYS:
        value = _first_present_value(
            metadata.get(key),
            decision_inputs.get(key),
            *(
                source_fields.get(alias)
                for alias in source_field_aliases.get(key, ())
            ),
        )
        if value in (None, "", [], {}):
            continue
        payload[key] = list(value) if isinstance(value, list) else value
    if payload and not payload.get("predecision_market_snapshot_transfer_status"):
        payload["predecision_market_snapshot_transfer_status"] = (
            "source_safe_predecision_market_snapshot_transferred"
        )
    if payload and not payload.get("predecision_market_snapshot_source_boundary"):
        payload["predecision_market_snapshot_source_boundary"] = (
            "closed_m15_predecision_asof_no_postdecision_path"
        )
    return payload


def _merge_predecision_market_decision_input_payload(
    decision_inputs: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> dict[str, Any]:
    merged = dict(decision_inputs) if isinstance(decision_inputs, Mapping) else {}
    if not payload:
        return merged
    for key, value in payload.items():
        if key in {"source_fields", "candidate_source_fields"}:
            if not isinstance(value, Mapping):
                continue
            fields = (
                dict(merged.get(key))
                if isinstance(merged.get(key), Mapping)
                else {}
            )
            for field_key, field_value in value.items():
                if field_value in (None, "", [], {}):
                    continue
                if fields.get(field_key) in (None, "", [], {}):
                    fields[field_key] = field_value
            merged[key] = fields
            continue
        if value in (None, "", [], {}):
            continue
        if merged.get(key) in (None, "", [], {}):
            merged[key] = list(value) if isinstance(value, list) else value
    return merged


def _scheduler_package_marketable_immediate_entry_quality_signal(
    *,
    candidate: "AllocatorCandidate",
    fillability: Mapping[str, Any],
    config: SchedulerV4Config,
) -> dict[str, Any]:
    metadata = candidate.metadata if isinstance(candidate.metadata, Mapping) else {}
    source_fields = _candidate_source_fields(candidate)
    side = _text(candidate.side).upper()
    current_framework = _lower(
        metadata.get("current_framework")
        or metadata.get("framework")
        or metadata.get("candidate_origin_family")
        or metadata.get("origin_family")
        or source_fields.get("generation_rule")
    )
    unit_risk = _num(
        _first_present_value(
            fillability.get("unit_risk"),
            metadata.get("unit_risk"),
            metadata.get("risk_distance"),
        ),
        math.nan,
    )
    entry = _num(metadata.get("entry_price"), math.nan)
    stop = _num(metadata.get("stop_loss"), math.nan)
    if (
        unit_risk is not None
        and not math.isfinite(unit_risk)
        and entry is not None
        and stop is not None
        and math.isfinite(entry)
        and math.isfinite(stop)
    ):
        unit_risk = abs(entry - stop)
    atr14 = _num(
        _first_present_value(
            fillability.get("atr14"),
            metadata.get("atr14"),
            metadata.get("atr"),
            source_fields.get("atr14"),
            source_fields.get("atr"),
        ),
        math.nan,
    )
    m15_open = _num(
        _first_present_value(source_fields.get("m15_open"), source_fields.get("open")),
        math.nan,
    )
    m15_high = _num(
        _first_present_value(source_fields.get("m15_high"), source_fields.get("high")),
        math.nan,
    )
    m15_low = _num(
        _first_present_value(source_fields.get("m15_low"), source_fields.get("low")),
        math.nan,
    )
    m15_close = _num(
        _first_present_value(source_fields.get("m15_close"), source_fields.get("close")),
        math.nan,
    )
    open_range_high = _num(source_fields.get("open_range_high"), math.nan)
    open_range_low = _num(source_fields.get("open_range_low"), math.nan)
    m15_range = (
        m15_high - m15_low
        if m15_high is not None
        and m15_low is not None
        and math.isfinite(m15_high)
        and math.isfinite(m15_low)
        else math.nan
    )
    close_position_side: float | None = None
    signed_body_atr: float | None = None
    breakout_extension_atr: float | None = None
    open_range_width_atr: float | None = None
    if (
        math.isfinite(m15_range)
        and m15_range > 0.0
        and m15_close is not None
        and math.isfinite(m15_close)
    ):
        if side == "LONG":
            close_position_side = (m15_close - m15_low) / m15_range
        elif side == "SHORT":
            close_position_side = (m15_high - m15_close) / m15_range
    if (
        side in {"LONG", "SHORT"}
        and m15_open is not None
        and m15_close is not None
        and atr14 is not None
        and math.isfinite(m15_open)
        and math.isfinite(m15_close)
        and math.isfinite(atr14)
        and atr14 > 0.0
    ):
        signed = 1.0 if side == "LONG" else -1.0
        signed_body_atr = signed * (m15_close - m15_open) / atr14
    if (
        side in {"LONG", "SHORT"}
        and m15_close is not None
        and open_range_high is not None
        and open_range_low is not None
        and atr14 is not None
        and math.isfinite(m15_close)
        and math.isfinite(open_range_high)
        and math.isfinite(open_range_low)
        and math.isfinite(atr14)
        and atr14 > 0.0
    ):
        open_range_width_atr = (open_range_high - open_range_low) / atr14
        if side == "LONG":
            breakout_extension_atr = (m15_close - open_range_high) / atr14
        else:
            breakout_extension_atr = (open_range_low - m15_close) / atr14
    unit_risk_atr: float | None = None
    if (
        unit_risk is not None
        and atr14 is not None
        and math.isfinite(unit_risk)
        and math.isfinite(atr14)
        and atr14 > 0.0
    ):
        unit_risk_atr = unit_risk / atr14

    max_unit_risk_atr = max(
        0.0,
        config.package_marketable_entry_guard_immediate_marketable_limit_max_unit_risk_atr,
    )
    min_displacement_close_position = _clamp(
        config.package_marketable_entry_guard_immediate_marketable_limit_min_displacement_close_position_side,
        0.0,
        1.0,
    )
    min_reclaim_close_position = _clamp(
        config.package_marketable_entry_guard_immediate_marketable_limit_min_reclaim_close_position_side,
        0.0,
        1.0,
    )
    min_orb_close_position = _clamp(
        config.package_marketable_entry_guard_immediate_marketable_limit_min_open_range_break_close_position_side,
        0.0,
        1.0,
    )
    min_orb_body_atr = max(
        0.0,
        config.package_marketable_entry_guard_immediate_marketable_limit_min_open_range_break_body_atr,
    )
    min_orb_extension_atr = max(
        0.0,
        config.package_marketable_entry_guard_immediate_marketable_limit_min_open_range_break_extension_atr,
    )
    min_orb_width_atr = max(
        0.0,
        config.package_marketable_entry_guard_immediate_marketable_limit_min_open_range_break_width_atr,
    )
    max_orb_width_atr = max(
        min_orb_width_atr,
        config.package_marketable_entry_guard_immediate_marketable_limit_max_open_range_break_width_atr,
    )
    displacement_applies = "displacement" in current_framework
    reclaim_applies = (
        "liquidity_sweep_reclaim" in current_framework
        or ("sweep" in current_framework and "reclaim" in current_framework)
    )
    orb_applies = (
        "session_open_range_break" in current_framework
        or ("open_range" in current_framework and "break" in current_framework)
    )
    structure_quality_applies = bool(
        displacement_applies or reclaim_applies or orb_applies
    )
    failures: list[str] = []
    enabled = bool(
        config.package_marketable_entry_guard_immediate_marketable_limit_entry_quality_enabled
    )
    if (
        enabled
        and fillability.get("limit_marketable_at_decision") is True
        and structure_quality_applies
    ):
        if unit_risk_atr is None:
            failures.append("immediate_marketable_entry_quality_missing_unit_risk_atr")
        elif unit_risk_atr > max_unit_risk_atr:
            failures.append(
                "immediate_marketable_entry_unit_risk_atr_above_quality_ceiling"
            )
        if displacement_applies:
            if close_position_side is None:
                failures.append(
                    "immediate_marketable_displacement_close_position_missing"
                )
            elif close_position_side < min_displacement_close_position:
                failures.append(
                    "immediate_marketable_displacement_close_position_below_quality_floor"
                )
        if reclaim_applies:
            if close_position_side is None:
                failures.append("immediate_marketable_reclaim_close_position_missing")
            elif close_position_side < min_reclaim_close_position:
                failures.append(
                    "immediate_marketable_reclaim_close_position_below_quality_floor"
                )
        if orb_applies:
            if close_position_side is None:
                failures.append(
                    "immediate_marketable_open_range_break_close_position_missing"
                )
            elif close_position_side < min_orb_close_position:
                failures.append(
                    "immediate_marketable_open_range_break_close_position_below_quality_floor"
                )
            if signed_body_atr is None:
                failures.append("immediate_marketable_open_range_break_body_atr_missing")
            elif signed_body_atr < min_orb_body_atr:
                failures.append(
                    "immediate_marketable_open_range_break_body_atr_below_quality_floor"
                )
            if breakout_extension_atr is None:
                failures.append(
                    "immediate_marketable_open_range_break_extension_atr_missing"
                )
            elif breakout_extension_atr < min_orb_extension_atr:
                failures.append(
                    "immediate_marketable_open_range_break_extension_atr_below_quality_floor"
                )
            if open_range_width_atr is None:
                failures.append(
                    "immediate_marketable_open_range_break_width_atr_missing"
                )
            elif open_range_width_atr < min_orb_width_atr:
                failures.append(
                    "immediate_marketable_open_range_break_width_atr_below_quality_floor"
                )
            elif open_range_width_atr > max_orb_width_atr:
                failures.append(
                    "immediate_marketable_open_range_break_width_atr_above_quality_ceiling"
                )
    return {
        "enabled": enabled,
        "eligible": not failures,
        "status": (
            "disabled"
            if not enabled
            else "not_applicable"
            if (
                fillability.get("limit_marketable_at_decision") is not True
                or not structure_quality_applies
            )
            else "blocked"
            if failures
            else "passed"
        ),
        "failures": failures,
        "reason": failures[0] if failures else None,
        "current_framework": current_framework or None,
        "open_range_break_quality_applies": orb_applies,
        "displacement_quality_applies": displacement_applies,
        "reclaim_quality_applies": reclaim_applies,
        "structure_quality_applies": structure_quality_applies,
        "unit_risk_atr": _round(unit_risk_atr),
        "m15_close_position_side": _round(close_position_side),
        "m15_signed_body_atr": _round(signed_body_atr),
        "open_range_breakout_extension_atr": _round(breakout_extension_atr),
        "open_range_width_atr": _round(open_range_width_atr),
        "open_range_break_close_position_floor": _round(min_orb_close_position),
        "open_range_break_body_atr_floor": _round(min_orb_body_atr),
        "open_range_break_extension_atr_floor": _round(min_orb_extension_atr),
        "open_range_break_width_atr_floor": _round(min_orb_width_atr),
        "open_range_break_width_atr_ceiling": _round(max_orb_width_atr),
        "source_boundary": (
            "closed_m15_predecision_source_fields_no_postdecision_path"
        ),
        "uses_outcome_fields": False,
    }


def _package_marketable_guard_quality_release(
    *,
    config: SchedulerV4Config,
    prefix: str,
    symbol: str | None = None,
    scheduler_score: float,
    expected_net_r: float,
    probability: float,
    fill_probability: float,
    source_completeness: float,
    cost_total_r: float,
    package_executable_quality_authority: bool = False,
) -> dict[str, Any]:
    thresholds = {
        "scheduler_score": _num(
            getattr(config, f"{prefix}_min_scheduler_score", None), 0.0
        )
        or 0.0,
        "expected_net_r": _num(
            getattr(config, f"{prefix}_min_expected_net_r", None), 0.0
        )
        or 0.0,
        "probability": _num(getattr(config, f"{prefix}_min_probability", None), 0.0)
        or 0.0,
        "fill_probability": _num(
            getattr(config, f"{prefix}_min_fill_probability", None), 0.0
        )
        or 0.0,
        "source_completeness": _num(
            getattr(config, f"{prefix}_min_source_completeness", None), 0.0
        )
        or 0.0,
        "max_expected_cost_r": _num(
            getattr(config, f"{prefix}_max_expected_cost_r", None), math.inf
        ),
    }
    max_cost = thresholds["max_expected_cost_r"]
    cost_ceiling_source = "configured_scalar_max_expected_cost_r"
    tick_floor = None
    tick_floor_ceiling = None
    tick_floor_untradeable = False
    tick_floor_ceiling_enabled = bool(
        prefix == "package_marketable_entry_guard_immediate_marketable_limit"
        and config.package_marketable_entry_guard_immediate_marketable_limit_tick_floor_cost_ceiling_enabled
    )
    if tick_floor_ceiling_enabled:
        symbol_text = _text(symbol)
        tick_floor = tick_spread_floor_for(symbol_text) if symbol_text else None
        if tick_floor is not None:
            tick_floor_untradeable_r = max(
                0.0,
                config.package_marketable_entry_guard_immediate_marketable_limit_tick_floor_untradeable_r,
            )
            tick_floor_untradeable = bool(tick_floor >= tick_floor_untradeable_r)
            if not tick_floor_untradeable:
                multiplier = max(
                    1.0,
                    config.package_marketable_entry_guard_immediate_marketable_limit_tick_floor_cost_ceiling_multiplier,
                )
                tick_floor_ceiling = tick_floor * multiplier
                if max_cost is None or not math.isfinite(max_cost):
                    max_cost = tick_floor_ceiling
                    cost_ceiling_source = "measured_tick_spread_floor_ceiling"
                elif tick_floor_ceiling > max_cost:
                    max_cost = tick_floor_ceiling
                    cost_ceiling_source = (
                        "measured_tick_spread_floor_ceiling_overrode_scalar"
                    )
    failures: list[str] = []
    scheduler_score_failure = ""
    if scheduler_score < thresholds["scheduler_score"]:
        scheduler_score_failure = "scheduler_score"
    if expected_net_r < thresholds["expected_net_r"]:
        failures.append("expected_net_r")
    if probability < thresholds["probability"]:
        failures.append("probability")
    if fill_probability < thresholds["fill_probability"]:
        failures.append("fill_probability")
    if source_completeness < thresholds["source_completeness"]:
        failures.append("source_completeness")
    if tick_floor_untradeable:
        failures.append("tick_spread_floor_untradeable")
    if max_cost is not None and math.isfinite(max_cost) and cost_total_r > max_cost:
        failures.append("expected_cost_r")
    immediate_marketable_limit_quality = bool(
        prefix == "package_marketable_entry_guard_immediate_marketable_limit"
    )
    score_floor_override_applied = bool(
        scheduler_score_failure
        and package_executable_quality_authority
        and not immediate_marketable_limit_quality
        and not failures
    )
    if scheduler_score_failure and not score_floor_override_applied:
        failures.append(scheduler_score_failure)
    thresholds["effective_max_expected_cost_r"] = max_cost
    if tick_floor_ceiling is not None:
        thresholds["tick_floor_cost_ceiling_r"] = tick_floor_ceiling
    serialized_thresholds = {
        key: (
            _round(value)
            if value is None or math.isfinite(float(value))
            else None
        )
        for key, value in thresholds.items()
    }
    max_cost_unbounded = bool(max_cost is None or not math.isfinite(max_cost))
    serialized_thresholds["max_expected_cost_r_unbounded"] = bool(
        thresholds["max_expected_cost_r"] is None
        or not math.isfinite(thresholds["max_expected_cost_r"])
    )
    serialized_thresholds["effective_max_expected_cost_r_unbounded"] = (
        max_cost_unbounded
    )
    return {
        "eligible": not failures,
        "failures": failures,
        "thresholds": serialized_thresholds,
        "cost_ceiling": {
            "source": cost_ceiling_source,
            "configured_scalar_max_expected_cost_r": serialized_thresholds[
                "max_expected_cost_r"
            ],
            "configured_scalar_max_expected_cost_r_unbounded": (
                serialized_thresholds["max_expected_cost_r_unbounded"]
            ),
            "effective_max_expected_cost_r": serialized_thresholds[
                "effective_max_expected_cost_r"
            ],
            "effective_max_expected_cost_r_unbounded": max_cost_unbounded,
            "tick_floor_cost_ceiling_enabled": tick_floor_ceiling_enabled,
            "symbol": symbol,
            "tick_spread_floor_r": _round(tick_floor),
            "tick_floor_cost_ceiling_r": _round(tick_floor_ceiling),
            "tick_floor_untradeable": tick_floor_untradeable,
            "tick_floor_untradeable_r": _round(
                config.package_marketable_entry_guard_immediate_marketable_limit_tick_floor_untradeable_r
            ),
            "tick_floor_multiplier": _round(
                config.package_marketable_entry_guard_immediate_marketable_limit_tick_floor_cost_ceiling_multiplier
            ),
        },
        "quality": {
            "scheduler_score": _round(scheduler_score),
            "expected_net_r": _round(expected_net_r),
            "probability": _round(probability),
            "fill_probability": _round(fill_probability),
            "source_completeness": _round(source_completeness),
            "cost_total_r": _round(cost_total_r),
        },
        "package_score_floor_override": {
            "applied": score_floor_override_applied,
            "reason": (
                "package_executable_authority_overrode_scheduler_score_floor"
                if score_floor_override_applied
                else "immediate_marketable_limit_requires_scheduler_score_floor"
                if scheduler_score_failure and immediate_marketable_limit_quality
                else scheduler_score_failure
                if scheduler_score_failure
                else "scheduler_score_floor_satisfied"
            ),
            "failures": (
                []
                if score_floor_override_applied
                else [scheduler_score_failure]
                if scheduler_score_failure
                else []
            ),
            "original_scheduler_score": _round(scheduler_score),
            "required_scheduler_score": _round(thresholds["scheduler_score"]),
            "package_executable_quality_authority": bool(
                package_executable_quality_authority
            ),
            "score_floor_override_disabled_for_immediate_marketable_limit": bool(
                scheduler_score_failure
                and immediate_marketable_limit_quality
                and package_executable_quality_authority
            ),
            "source_boundary": (
                "predecision_package_executable_authority_score_floor_override_"
                "broker_cost_enforced_no_outcome_fields"
            ),
            "live_broker_authority": False,
            "broker_mutation_enabled": False,
            "final_selection_claim": False,
        },
        "package_score_floor_override_applied": score_floor_override_applied,
        "source_boundary": (
            "predecision_scheduler_quality_broker_cost_and_fillability_no_outcome_fields"
        ),
    }


def _configured_marketable_session(candidate: "AllocatorCandidate") -> tuple[bool, str | None, str | None]:
    metadata = candidate.metadata if isinstance(candidate.metadata, Mapping) else {}
    invalid_sessions = {
        "off_configured",
        "off_configured_session",
        "off_kz",
        "off_kz_broad",
        "off_session",
        "off_configured_kill_zone",
    }

    def valid_session(value: Any) -> str | None:
        token = _text(value)
        if not token or token in invalid_sessions:
            return None
        return token

    for source, value in (
        ("metadata.route_session_applied", metadata.get("route_session_applied")),
        ("metadata.authority_session", metadata.get("authority_session")),
        ("metadata.session", metadata.get("session")),
        ("metadata.session_bucket", metadata.get("session_bucket")),
        ("metadata.route_session", metadata.get("route_session")),
    ):
        session = valid_session(value)
        if session:
            return True, session, source
    for source, values in (
        ("metadata.authority_session_tokens", metadata.get("authority_session_tokens")),
        ("metadata.route_session_tokens", metadata.get("route_session_tokens")),
    ):
        if not isinstance(values, Iterable) or isinstance(values, (str, bytes, bytearray)):
            continue
        for value in values:
            session = valid_session(value)
            if session:
                return True, session, source
    return False, None, None


def _raw_marketable_route_session(metadata: Mapping[str, Any]) -> str | None:
    raw_session = _first_present_value(
        metadata.get("route_session_raw"),
        metadata.get("raw_route_session"),
        metadata.get("source_route_session"),
        metadata.get("route_session"),
    )
    raw_session_text = _text(raw_session)
    return raw_session_text or None


def _off_configured_immediate_marketable_limit_authority_allowed(
    *,
    authority_family: Any,
    selector_reason: Any,
) -> bool:
    family = _text(authority_family)
    if family in OFF_CONFIGURED_IMMEDIATE_MARKETABLE_LIMIT_AUTHORITY_FAMILIES:
        return True
    reason = _lower(selector_reason)
    if not reason:
        return False
    return bool(
        reason in PACKAGE_REDUCE_RISK_OFF_SESSION_REASONS
        or "positive_predecision_off_session_open_reduced_risk" in reason
    )


def _scheduler_package_marketable_entry_guard(
    *,
    candidate: "AllocatorCandidate",
    config: SchedulerV4Config,
    scheduler_score: float,
    expected_net_r: float,
    probability: float,
    fill_probability: float,
    source_completeness: float,
    cost_total_r: float,
    selector_action: str,
    package_candidate: bool,
    package_fill_floor_authority_allowed: bool,
    signed_open_reduced_new_entry_authority_allowed: bool,
    selector_open_reduced_package_authority: Mapping[str, Any],
    broker_cost_rank: Mapping[str, Any],
) -> dict[str, Any]:
    metadata = candidate.metadata if isinstance(candidate.metadata, Mapping) else {}
    fillability = dict(_candidate_predecision_limit_fillability(candidate))
    enabled = bool(config.package_marketable_entry_guard_enabled)
    limit_marketable = fillability.get("limit_marketable_at_decision") is True
    fillability_available = bool(
        fillability.get("available") is True
        or "limit_marketable_at_decision" in fillability
    )
    base = {
        "enabled": enabled,
        "status": "disabled" if not enabled else "clear",
        "reason": None,
        "candidate_id": candidate.candidate_id,
        "symbol": candidate.symbol,
        "side": candidate.side,
        "package_candidate": bool(package_candidate),
        "limit_marketable_at_decision": limit_marketable,
        "predecision_limit_fillability": fillability,
        "source_boundary": (
            "asof_candidate_fields_only_no_postdecision_path_no_broker_authority"
        ),
        "live_broker_authority": False,
        "broker_mutation_enabled": False,
        "final_selection_claim": False,
        "package_final_selection_claim": False,
    }
    if not enabled:
        return base
    if not package_candidate:
        base["reason"] = "not_package_candidate"
        return base
    if not fillability_available:
        base["status"] = "blocked"
        base["reason"] = "predecision_limit_fillability_unavailable"
        return base
    if not limit_marketable:
        return base
    package_executable_quality_authority = bool(
        _text(metadata.get("ultimate_package_executable_admission_status"))
        == "executable_source_bound_package_admission"
        and (
            _truthy(metadata.get("ultimate_package_explicit_executable_authority_present"))
            or _truthy(metadata.get("ultimate_package_derived_executable_quality_authority"))
        )
    )

    replay_quality = _package_marketable_guard_quality_release(
        config=config,
        prefix="package_marketable_entry_guard_replay_route",
        symbol=candidate.symbol,
        scheduler_score=scheduler_score,
        expected_net_r=expected_net_r,
        probability=probability,
        fill_probability=fill_probability,
        source_completeness=source_completeness,
        cost_total_r=cost_total_r,
        package_executable_quality_authority=package_executable_quality_authority,
    )
    immediate_quality = _package_marketable_guard_quality_release(
        config=config,
        prefix="package_marketable_entry_guard_immediate_marketable_limit",
        symbol=candidate.symbol,
        scheduler_score=scheduler_score,
        expected_net_r=expected_net_r,
        probability=probability,
        fill_probability=fill_probability,
        source_completeness=source_completeness,
        cost_total_r=cost_total_r,
        package_executable_quality_authority=package_executable_quality_authority,
    )
    immediate_entry_quality = (
        _scheduler_package_marketable_immediate_entry_quality_signal(
            candidate=candidate,
            fillability=fillability,
            config=config,
        )
    )
    cost_passed = (
        _text(broker_cost_rank.get("pretrade_cost_packet_status")).upper()
        in {"PASSED", "PASS", "OK"}
        and not broker_cost_rank.get("hard_veto_reason")
    )
    nested_open_reduced_authority = metadata.get(
        "ultimate_candidate_package_open_reduced_risk_authority"
    )
    if not isinstance(nested_open_reduced_authority, dict):
        nested_open_reduced_authority = {}
    nested_target_action = _text(
        nested_open_reduced_authority.get(
            "package_new_entry_authority_target_action_intent"
        )
        or nested_open_reduced_authority.get("target_action_intent")
    )
    nested_authority_family = _text(
        nested_open_reduced_authority.get("package_new_entry_authority_authority_family")
        or nested_open_reduced_authority.get("authority_family")
    )
    nested_selector_reason = _text(
        nested_open_reduced_authority.get("package_new_entry_authority_selector_reason")
        or nested_open_reduced_authority.get("selector_reason")
    )
    selector_reason = _text(
        selector_open_reduced_package_authority.get("selector_reason")
        or metadata.get("selector_reason")
        or nested_selector_reason
        or candidate.selector_reason
    )
    signed_metadata_selector_action = _text(
        metadata.get("package_new_entry_authority_selector_action")
    ) or _text(
        nested_open_reduced_authority.get("package_new_entry_authority_selector_action")
    )
    signed_metadata_target_action = _text(
        metadata.get("package_new_entry_authority_target_action_intent")
    ) or nested_target_action
    signed_metadata_authority_family = _text(
        metadata.get("package_new_entry_authority_authority_family")
    ) or nested_authority_family
    signed_metadata_uses_outcome_fields = bool(
        _truthy(metadata.get("package_new_entry_authority_uses_outcome_fields"))
        or _truthy(
            nested_open_reduced_authority.get(
                "package_new_entry_authority_uses_outcome_fields"
            )
        )
        or _truthy(nested_open_reduced_authority.get("uses_outcome_fields"))
    )
    signed_metadata_authority_row = {
        **dict(metadata),
        "candidate_id": candidate.candidate_id,
        "symbol": candidate.symbol,
        "side": candidate.side,
        "selector_action": selector_action,
        "selector_reason": selector_reason,
        "expected_net_r": expected_net_r,
        "probability": probability,
        "fill_probability": fill_probability,
        "source_completeness": source_completeness,
        "cost_total_r": cost_total_r,
    }
    if nested_open_reduced_authority:
        signed_metadata_authority_row[
            "ultimate_candidate_package_open_reduced_risk_authority"
        ] = dict(nested_open_reduced_authority)
    signed_metadata_open_reduced_authority_validation = (
        reduced_package_new_entry_authority_validation(
            signed_metadata_authority_row,
            selector_action=selector_action,
            selector_reason=selector_reason,
            action_intent=signed_metadata_target_action,
            config=config,
        )
    )
    signed_metadata_payload = _mapping(
        signed_metadata_open_reduced_authority_validation.get(
            "package_new_entry_authority_payload"
        )
    )
    (
        signed_metadata_order_executable_allowed,
        _,
        _,
    ) = _signed_order_executable_triplet(signed_metadata_payload)
    signed_metadata_open_reduced_authority_allowed = bool(
        selector_action == "open-reduced-risk"
        and signed_metadata_open_reduced_authority_validation.get("valid") is True
        and signed_metadata_order_executable_allowed is True
        and _num(
            signed_metadata_payload.get("execution_fill_probability")
        )
        is not None
        and signed_metadata_selector_action == "open-reduced-risk"
        and signed_metadata_target_action in {
            "new_position",
            "same_direction_scale_in",
            "replace_pending",
            "close_and_reverse",
        }
        and not signed_metadata_uses_outcome_fields
        and signed_metadata_authority_family in {
            "router_refusal_softening",
            "explicit_package_executable_replay_materialization",
            "source_bound_fill_floor_replay_materialization",
            "fill_floor_softening",
            "off_session_softening",
        }
    )
    fallback_text = _text(
        metadata.get("would_guarded_market_fallback")
        or metadata.get("guarded_market_fallback")
        or metadata.get("package_execution_policy_fallback")
    )
    fallback_configured = _truthy(metadata.get("guarded_market_fallback_configured"))
    effective_fallback_text = fallback_text or (
        "guarded_market_fallback_configured"
        if fallback_configured
        else ""
    )
    replay_route_allowed = bool(
        not config.live_activation_allowed
        and config.package_marketable_entry_guard_replay_route_allowed
        and cost_passed
        and replay_quality.get("eligible") is True
        and "guarded_market" in effective_fallback_text
        and (
            selector_action != "open-reduced-risk"
            or signed_metadata_open_reduced_authority_allowed
        )
    )
    authority_family = _package_authority_primary_family(
        selector_open_reduced_package_authority,
        selector_open_reduced_package_authority.get("authority_family")
        or metadata.get("package_open_reduced_authority_family")
        or metadata.get("ultimate_package_open_reduced_authority_family")
        or nested_authority_family,
        selector_open_reduced_package_authority.get("selector_reason")
        or metadata.get("selector_reason")
        or nested_selector_reason
        or candidate.selector_reason,
    )
    router_refusal_immediate_authority = _truthy(
        selector_open_reduced_package_authority.get(
            "immediate_marketable_execution_authority_allowed"
        )
        or selector_open_reduced_package_authority.get(
            "router_refusal_immediate_marketable_execution_authority_allowed"
        )
        or metadata.get("router_refusal_immediate_marketable_execution_authority_allowed")
        or nested_open_reduced_authority.get(
            "immediate_marketable_execution_authority_allowed"
        )
        or nested_open_reduced_authority.get(
            "router_refusal_immediate_marketable_execution_authority_allowed"
        )
    )
    raw_route_session = _raw_marketable_route_session(metadata)
    raw_off_configured_immediate_session = _off_configured_session_token(raw_route_session)
    off_configured_immediate_session_authority_allowed = (
        _off_configured_immediate_marketable_limit_authority_allowed(
            authority_family=authority_family,
            selector_reason=selector_reason,
        )
    )
    router_refusal_immediate_authority_source = (
        "explicit_router_refusal_immediate_marketable_execution_authority"
        if router_refusal_immediate_authority
        else None
    )
    source_bound_router_refusal_immediate_authority_from_signature = bool(
        not router_refusal_immediate_authority
        and config.package_marketable_entry_guard_router_refusal_immediate_marketable_limit_replay_authority_enabled
        and config.package_marketable_entry_guard_router_refusal_derived_immediate_marketable_limit_replay_authority_enabled
        and authority_family == "router_refusal_softening"
        and selector_reason
        == "source_bound_router_refusal_open_reduced_materialized_for_replay"
        and (
            signed_metadata_open_reduced_authority_allowed
        )
        and _truthy(selector_open_reduced_package_authority.get("allowed"))
    )
    if (
        not router_refusal_immediate_authority
        and config.package_marketable_entry_guard_router_refusal_immediate_marketable_limit_replay_authority_enabled
        and authority_family == "router_refusal_softening"
        and selector_reason
        in {
            "source_bound_router_refusal_open_reduced_materialized_for_replay",
            "ultimate_candidate_package_positive_predecision_router_refusal_open_reduced_risk",
        }
        and config.package_marketable_entry_guard_router_refusal_derived_immediate_marketable_limit_replay_authority_enabled
        and (
            signed_metadata_open_reduced_authority_allowed
        )
        and _truthy(selector_open_reduced_package_authority.get("allowed"))
    ):
        router_refusal_immediate_authority = True
        router_refusal_immediate_authority_source = (
            "signed_source_bound_router_refusal_immediate_marketable_limit_"
            "replay_authority"
            if selector_reason
            == "source_bound_router_refusal_open_reduced_materialized_for_replay"
            else "repaired_profile_signed_router_refusal_immediate_marketable_"
            "limit_replay_authority"
        )
    open_reduced_immediate_authority_allowed = bool(
        selector_action == "open-reduced-risk"
        and signed_metadata_open_reduced_authority_allowed
        and (
            package_fill_floor_authority_allowed
            or _truthy(selector_open_reduced_package_authority.get("allowed"))
            or _truthy(metadata.get("package_open_reduced_authority_allowed"))
        )
        and not (
            authority_family == "router_refusal_softening"
            and not router_refusal_immediate_authority
        )
    )
    configured_session, route_session, route_session_source = _configured_marketable_session(
        candidate
    )
    immediate_route_allowed = bool(
        not config.live_activation_allowed
        and config.package_marketable_entry_guard_replay_route_allowed
        and config.package_marketable_entry_guard_immediate_marketable_limit_allowed
        and cost_passed
        and immediate_quality.get("eligible") is True
        and immediate_entry_quality.get("eligible") is True
        and configured_session
        and not (
            raw_off_configured_immediate_session
            and not off_configured_immediate_session_authority_allowed
        )
        and (
            selector_action == "trade"
            or open_reduced_immediate_authority_allowed
        )
    )
    failures: list[str] = []
    if not replay_route_allowed:
        failures.extend(
            f"replay_route:{failure}"
            for failure in replay_quality.get("failures", [])
        )
        if "guarded_market" not in effective_fallback_text:
            failures.append("replay_route:guarded_market_fallback_not_authorized")
    if not immediate_route_allowed:
        failures.extend(
            f"immediate_marketable_limit:{failure}"
            for failure in immediate_quality.get("failures", [])
        )
        failures.extend(
            f"immediate_marketable_limit:entry_quality:{failure}"
            for failure in immediate_entry_quality.get("failures", [])
        )
        if not config.package_marketable_entry_guard_immediate_marketable_limit_allowed:
            failures.append("immediate_marketable_limit:route_not_enabled")
        if not configured_session:
            failures.append("immediate_marketable_limit:configured_session_missing")
        if (
            raw_off_configured_immediate_session
            and not off_configured_immediate_session_authority_allowed
        ):
            failures.append(
                "immediate_marketable_limit:"
                "raw_off_configured_session_requires_explicit_off_session_authority"
            )
        if selector_action == "open-reduced-risk" and not open_reduced_immediate_authority_allowed:
            failures.append(
                "immediate_marketable_limit:package_open_reduced_authority_missing"
            )
            if authority_family == "router_refusal_softening" and not router_refusal_immediate_authority:
                failures.append(
                    "immediate_marketable_limit:"
                    "router_refusal_open_reduced_immediate_marketable_execution_authority_missing"
                )
    if not cost_passed:
        failures.append("broker_cost_not_executable")
    routed = replay_route_allowed or immediate_route_allowed
    base.update(
        {
            "status": (
                "routed_to_replay_order_policy"
                if replay_route_allowed
                else "routed_to_immediate_marketable_limit_replay_order_policy"
                if immediate_route_allowed
                else "blocked"
            ),
            "reason": (
                "package_marketable_limit_entry_routed_to_guarded_market_fallback"
                if replay_route_allowed
                else "package_marketable_limit_entry_routed_to_immediate_marketable_limit"
                if immediate_route_allowed
                else "package_marketable_limit_entry_guard_blocked"
            ),
            "original_reason": (
                "package_marketable_limit_entry_guard_blocked"
                if routed
                else None
            ),
            "replay_route_allowed": replay_route_allowed,
            "immediate_marketable_limit_route_allowed": immediate_route_allowed,
            "route_allowed": routed,
            "route_failures": list(dict.fromkeys(failures)),
            "replay_route_quality_release": replay_quality,
            "immediate_marketable_limit_quality_release": immediate_quality,
            "immediate_marketable_limit_entry_quality": immediate_entry_quality,
            "open_reduced_immediate_marketable_limit_authority_allowed": (
                open_reduced_immediate_authority_allowed
            ),
            "router_refusal_immediate_marketable_execution_authority_allowed": (
                router_refusal_immediate_authority
            ),
            "router_refusal_immediate_marketable_execution_authority_source": (
                router_refusal_immediate_authority_source
            ),
            "signed_metadata_open_reduced_authority_allowed": (
                signed_metadata_open_reduced_authority_allowed
            ),
            "signed_metadata_open_reduced_authority_validation": (
                signed_metadata_open_reduced_authority_validation
            ),
            "guarded_market_fallback_configured": fallback_configured,
            "effective_guarded_market_fallback_text": effective_fallback_text or None,
            "router_refusal_immediate_marketable_execution_authority_repair_enabled": (
                config.package_marketable_entry_guard_router_refusal_immediate_marketable_limit_replay_authority_enabled
            ),
            "router_refusal_derived_immediate_marketable_execution_authority_enabled": (
                config.package_marketable_entry_guard_router_refusal_derived_immediate_marketable_limit_replay_authority_enabled
            ),
            "source_bound_router_refusal_immediate_marketable_execution_authority_from_signature": (
                source_bound_router_refusal_immediate_authority_from_signature
            ),
            "package_executable_quality_authority": (
                package_executable_quality_authority
            ),
            "authority_family": authority_family or None,
            "selector_reason": selector_reason or None,
            "route_session": route_session,
            "route_session_source": route_session_source,
            "raw_route_session_for_immediate_marketable_limit": raw_route_session,
            "raw_off_configured_session_for_immediate_marketable_limit": (
                raw_off_configured_immediate_session
            ),
            "off_configured_immediate_marketable_limit_authority_allowed": (
                off_configured_immediate_session_authority_allowed
            ),
            "configured_session_for_immediate_marketable_limit": configured_session,
            "pretrade_cost_packet_status": broker_cost_rank.get(
                "pretrade_cost_packet_status"
            ),
            "broker_cost_rank_status": broker_cost_rank.get("status"),
            "broker_cost_hard_veto_reason": broker_cost_rank.get("hard_veto_reason"),
        }
    )
    return base


def _candidate_open_reduced_guarded_market_fallback_policy(
    *,
    candidate: "AllocatorCandidate",
    selector_action: str,
    authority_family: str | None,
    package_open_reduced_authority_applies: bool,
    selector_open_reduced_package_authority: Mapping[str, Any],
    package_replay_executable_allowed: bool,
    package_admission_allowed: bool,
) -> tuple[str, str | None]:
    """Return explicit or replay-derived guarded fallback policy text."""

    metadata = candidate.metadata if isinstance(candidate.metadata, Mapping) else {}
    policy_sources: tuple[tuple[str, Mapping[str, Any]], ...] = (
        ("candidate_metadata", metadata),
        ("selector_open_reduced_package_authority", selector_open_reduced_package_authority),
        ("candidate_package_execution_policy", _mapping(metadata.get("package_execution_policy"))),
        ("candidate_execution_policy_shadow", _mapping(metadata.get("execution_policy_shadow"))),
        ("candidate_replay_order_fillability_policy", _mapping(metadata.get("replay_order_fillability_policy_v1"))),
    )
    for source, payload in policy_sources:
        fallback_text = _text(
            _first_present_value(
                payload.get("would_guarded_market_fallback"),
                payload.get("guarded_market_fallback"),
                payload.get("package_execution_policy_fallback"),
            )
        )
        if fallback_text:
            return fallback_text, source

    role = _text(metadata.get("ultimate_package_role_disposition"))
    if role in PACKAGE_HOLD_ROLE_DISPOSITIONS:
        return "", None
    admission_count = _num(
        _first_present_value(
            metadata.get("ultimate_package_effective_admission_count"),
            metadata.get("ultimate_package_admission_sleeve_match_count"),
            metadata.get("ultimate_package_matched_sleeve_count"),
        ),
        0.0,
    )
    source_bound_allowed = any(
        _truthy(metadata.get(field))
        for field in (
            "ultimate_package_effective_source_bound_candidate_use_allowed",
            "ultimate_package_source_bound_candidate_use_allowed",
            "source_bound_package_candidate_use_allowed",
            "package_replay_candidate_use_allowed",
            "ultimate_package_open_reduced_authority_allowed",
        )
    )
    if (
        selector_action == "open-reduced-risk"
        and package_open_reduced_authority_applies
        and authority_family
        in OPEN_REDUCED_PASSIVE_LIMIT_ROUTE_RESOLUTION_AUTHORITY_FAMILIES
        and (
            package_replay_executable_allowed
            or package_admission_allowed
            or source_bound_allowed
            or (admission_count is not None and admission_count > 0.0)
        )
    ):
        return (
            "guarded_market_reduced_risk_after_cost_proof",
            "derived_from_package_replay_candidate_fields",
        )
    return "", None


def _scheduler_open_reduced_passive_limit_route_resolution(
    *,
    candidate: "AllocatorCandidate",
    config: SchedulerV4Config,
    selector_action: str,
    package_open_reduced_authority_applies: bool,
    selector_open_reduced_package_authority: Mapping[str, Any],
    signed_package_new_entry_authority_valid: bool,
    package_replay_executable_allowed: bool,
    package_admission_allowed: bool,
    off_configured_session_authority_missing: bool,
    cross_asset_lead_lag_soft_authority_disabled: bool,
    broker_cost_rank: Mapping[str, Any],
    expected_net_r: float,
    probability: float,
    source_completeness: float,
    cost_total_r: float,
    package_fill_floor_failures: Sequence[str],
) -> dict[str, Any]:
    """Resolve passive-limit fill-floor failures only through explicit routes."""

    fill_failures = tuple(
        failure
        for failure in package_fill_floor_failures
        if failure in PASSIVE_LIMIT_FILL_FLOOR_FAILURES
    )
    non_fill_failures = tuple(
        failure
        for failure in package_fill_floor_failures
        if failure not in PASSIVE_LIMIT_FILL_FLOOR_FAILURES
    )
    metadata = candidate.metadata if isinstance(candidate.metadata, Mapping) else {}
    authority_family = _package_authority_primary_family(
        selector_open_reduced_package_authority,
        selector_open_reduced_package_authority.get("authority_family")
        or metadata.get("package_open_reduced_authority_family")
        or metadata.get("ultimate_package_open_reduced_authority_family"),
        selector_open_reduced_package_authority.get("selector_reason")
        or metadata.get("selector_reason")
        or candidate.selector_reason,
    )
    authority_selector_reason = _text(
        selector_open_reduced_package_authority.get("selector_reason")
        or metadata.get("selector_reason")
        or candidate.selector_reason
    )
    source_bound_router_refusal_fill_floor_non_bypassable = bool(
        authority_family == "router_refusal_softening"
        and authority_selector_reason
        == "source_bound_router_refusal_open_reduced_materialized_for_replay"
    )
    fallback_text, fallback_source = _candidate_open_reduced_guarded_market_fallback_policy(
        candidate=candidate,
        selector_action=selector_action,
        authority_family=authority_family,
        package_open_reduced_authority_applies=package_open_reduced_authority_applies,
        selector_open_reduced_package_authority=selector_open_reduced_package_authority,
        package_replay_executable_allowed=package_replay_executable_allowed,
        package_admission_allowed=package_admission_allowed,
    )
    fillability = _candidate_predecision_limit_fillability(candidate)
    limit_marketable = fillability.get("limit_marketable_at_decision") is True
    limit_queue_fill_probability = _num(
        _first_present_value(
            fillability.get("fill_probability"),
            fillability.get("probability"),
            fillability.get("limit_fillability_probability"),
        )
    )
    distance_to_limit_risk = _num(fillability.get("distance_to_limit_risk"))
    guarded_extra_cost_r = max(
        0.0,
        config.replay_order_fillability_policy_v1_guarded_market_extra_cost_r,
    )
    expected_net_after_fallback = expected_net_r - guarded_extra_cost_r
    common_failures: list[str] = []
    guarded_market_failures: list[str] = []
    passive_limit_queue_failures: list[str] = []
    passive_limit_fallback_envelope_failures: list[str] = []
    if not fill_failures:
        status = "not_applicable_no_passive_limit_fill_floor_failure"
    else:
        status = "blocked"
    if fill_failures:
        if config.live_activation_allowed:
            common_failures.append("live_activation_not_allowed_for_replay_route_resolution")
        if not config.replay_order_fillability_policy_v1_enabled:
            common_failures.append("replay_order_fillability_policy_disabled")
        if (
            not config.replay_order_fillability_policy_v1_allow_open_reduced_risk_guarded_market_fallback
        ):
            guarded_market_failures.append("open_reduced_guarded_market_fallback_disabled")
        if (
            not config.replay_order_fillability_policy_v1_allow_passive_limit_queue_for_package_replay
        ):
            passive_limit_queue_failures.append("passive_limit_queue_route_disabled")
        if selector_action != "open-reduced-risk":
            common_failures.append("selector_action_not_open_reduced_risk")
        if not package_open_reduced_authority_applies:
            common_failures.append("package_open_reduced_authority_not_applicable")
        if (
            authority_family
            not in OPEN_REDUCED_PASSIVE_LIMIT_ROUTE_RESOLUTION_AUTHORITY_FAMILIES
        ):
            common_failures.append("authority_family_not_explicit_execution_route")
        if non_fill_failures:
            common_failures.append(
                "non_passive_limit_fill_floor_failures:"
                + ",".join(dict.fromkeys(non_fill_failures))
            )
        if source_bound_router_refusal_fill_floor_non_bypassable:
            common_failures.append(
                "source_bound_router_refusal_execution_fill_floor_non_bypassable"
            )
        if not signed_package_new_entry_authority_valid:
            common_failures.append("signed_new_entry_authority_invalid")
        if not package_replay_executable_allowed:
            common_failures.append("package_replay_executable_candidate_not_allowed")
        if not package_admission_allowed:
            common_failures.append("package_admission_not_allowed")
        if off_configured_session_authority_missing:
            common_failures.append(
                "off_configured_session_requires_explicit_off_session_authority"
            )
        if cross_asset_lead_lag_soft_authority_disabled:
            common_failures.append("cross_asset_lead_lag_soft_authority_disabled")
        broker_cost_block = _candidate_broker_cost_non_executable_reason(
            broker_cost_rank
        )
        if broker_cost_block:
            common_failures.append(broker_cost_block)
        if (
            config.replay_order_fillability_policy_v1_require_package_execution_policy
            and "guarded_market" not in fallback_text
        ):
            guarded_market_failures.append("guarded_market_fallback_policy_not_authorized")
        require_passive_fallback_envelope = bool(
            config.replay_order_fillability_policy_v1_require_passive_limit_fallback_envelope
        )
        if (
            require_passive_fallback_envelope
            and "guarded_market" not in fallback_text
            and not config.replay_order_fillability_policy_v1_allow_passive_limit_queue_for_package_replay
        ):
            passive_limit_fallback_envelope_failures.append(
                "passive_limit_fallback_envelope_guarded_market_policy_not_authorized"
            )
        if probability < config.replay_order_fillability_policy_v1_min_candidate_probability:
            common_failures.append("probability")
        if (
            expected_net_after_fallback
            < config.replay_order_fillability_policy_v1_min_candidate_expected_net_r_after_fallback
        ):
            guarded_market_failures.append("expected_net_r_after_guarded_fallback_cost")
            if require_passive_fallback_envelope:
                passive_limit_fallback_envelope_failures.append(
                    "passive_limit_fallback_envelope_expected_net_r_after_guarded_fallback_cost"
                )
        if (
            expected_net_r
            < config.replay_order_fillability_policy_v1_min_candidate_expected_net_r_after_fallback
        ):
            passive_limit_queue_failures.append("expected_net_r")
        queue_min_fill = (
            config.replay_order_fillability_policy_v1_passive_limit_queue_min_fill_probability
        )
        if queue_min_fill > 0.0:
            if limit_queue_fill_probability is None:
                passive_limit_queue_failures.append(
                    "passive_limit_queue_fill_probability_missing"
                )
            elif limit_queue_fill_probability < queue_min_fill:
                passive_limit_queue_failures.append(
                    "passive_limit_queue_fill_probability"
                )
        if (
            source_completeness
            < config.replay_order_fillability_policy_v1_min_source_completeness
        ):
            common_failures.append("source_completeness")
        max_cost = config.replay_order_fillability_policy_v1_max_expected_cost_r
        if math.isfinite(max_cost) and cost_total_r > max_cost:
            common_failures.append("expected_cost_r")
        if limit_marketable:
            common_failures.append("limit_marketable_at_decision_uses_marketable_guard")
        if distance_to_limit_risk is None:
            common_failures.append("distance_to_limit_risk_missing")
            if require_passive_fallback_envelope:
                passive_limit_fallback_envelope_failures.append(
                    "passive_limit_fallback_envelope_distance_to_limit_risk_missing"
                )
        elif (
            distance_to_limit_risk
            > config.replay_order_fillability_policy_v1_max_adverse_entry_drift_r
        ):
            guarded_market_failures.append(
                "distance_to_limit_risk_above_guarded_fallback_ceiling"
            )
            if (
                require_passive_fallback_envelope
                and not config.replay_order_fillability_policy_v1_allow_passive_limit_queue_for_package_replay
            ):
                passive_limit_fallback_envelope_failures.append(
                    "passive_limit_fallback_envelope_distance_to_limit_risk_above_guarded_fallback_ceiling"
                )
        if passive_limit_fallback_envelope_failures:
            passive_limit_queue_failures.extend(
                passive_limit_fallback_envelope_failures
            )
    route_mode = ""
    if fill_failures and not common_failures:
        if not passive_limit_queue_failures:
            route_mode = "passive_limit_queue"
        elif not guarded_market_failures:
            route_mode = "guarded_market_fallback"
    allowed = bool(route_mode)
    if allowed:
        status = "passive_limit_fillability_route_resolved"
    failures = list(common_failures)
    if not allowed:
        if (
            config.replay_order_fillability_policy_v1_allow_passive_limit_queue_for_package_replay
            and passive_limit_queue_failures
        ):
            failures.extend(passive_limit_queue_failures)
        if guarded_market_failures:
            failures.extend(guarded_market_failures)
        if (
            not config.replay_order_fillability_policy_v1_allow_passive_limit_queue_for_package_replay
            and passive_limit_queue_failures
            and not guarded_market_failures
        ):
            failures.extend(passive_limit_queue_failures)
    return {
        "applies": bool(fill_failures),
        "allowed": allowed,
        "status": status,
        "reason": (
            "passive_limit_fillability_route_resolution"
            if allowed
            else failures[0]
            if failures
            else status
        ),
        "failures": list(dict.fromkeys(failures)),
        "raw_fill_floor_failures": list(package_fill_floor_failures),
        "resolved_failures": list(fill_failures) if allowed else [],
        "unresolved_non_fill_failures": list(non_fill_failures),
        "route_mode": route_mode or None,
        "guarded_market_fallback_route_allowed": route_mode == "guarded_market_fallback",
        "passive_limit_queue_route_allowed": route_mode == "passive_limit_queue",
        "passive_limit_queue_route_enabled": bool(
            config.replay_order_fillability_policy_v1_allow_passive_limit_queue_for_package_replay
        ),
        "passive_limit_fallback_envelope_required": bool(
            config.replay_order_fillability_policy_v1_require_passive_limit_fallback_envelope
        ),
        "passive_limit_fallback_envelope_failures": list(
            dict.fromkeys(passive_limit_fallback_envelope_failures)
        ),
        "authority_family": authority_family or None,
        "authority_selector_reason": authority_selector_reason or None,
        "source_bound_router_refusal_fill_floor_non_bypassable": (
            source_bound_router_refusal_fill_floor_non_bypassable
        ),
        "guarded_market_fallback_policy": fallback_text or None,
        "guarded_market_fallback_policy_source": fallback_source,
        "guarded_market_fallback_policy_authorized": "guarded_market" in fallback_text,
        "limit_marketable_at_decision": limit_marketable,
        "predecision_limit_fillability": dict(fillability),
        "passive_limit_queue_fill_probability": _round(
            limit_queue_fill_probability
        ),
        "passive_limit_queue_min_fill_probability": _round(
            config.replay_order_fillability_policy_v1_passive_limit_queue_min_fill_probability
        ),
        "distance_to_limit_risk": _round(distance_to_limit_risk),
        "max_adverse_entry_drift_r": _round(
            config.replay_order_fillability_policy_v1_max_adverse_entry_drift_r
        ),
        "expected_net_r": _round(expected_net_r),
        "guarded_market_extra_cost_r": _round(guarded_extra_cost_r),
        "expected_net_r_after_guarded_fallback_cost": _round(
            expected_net_after_fallback
        ),
        "expected_net_r_after_passive_limit_queue_cost": _round(expected_net_r),
        "probability": _round(probability),
        "source_completeness": _round(source_completeness),
        "cost_total_r": _round(cost_total_r),
        "pretrade_cost_packet_status": broker_cost_rank.get(
            "pretrade_cost_packet_status"
        ),
        "cost_source_gap_status": broker_cost_rank.get("cost_source_gap_status"),
        "cost_authority": broker_cost_rank.get("cost_authority"),
        "candidate_cost_r_fallback_is_authority": broker_cost_rank.get(
            "candidate_cost_r_fallback_is_authority"
        ),
        "source_boundary": (
            "predecision_package_authority_broker_cost_fillability_geometry_no_outcome_fields"
        ),
        "live_broker_authority": False,
    }


def _scheduler_predecision_passive_limit_too_close_guard(
    *,
    candidate: "AllocatorCandidate",
    config: SchedulerV4Config,
    selector_action: str,
    package_open_reduced_authority_applies: bool,
    passive_limit_fillability_route_resolution: Mapping[str, Any],
) -> dict[str, Any]:
    """Causal scheduler veto for passive limits already too close to entry."""

    metadata = candidate.metadata if isinstance(candidate.metadata, Mapping) else {}
    fillability = dict(_candidate_predecision_limit_fillability(candidate))
    distance_to_limit_risk = _num(fillability.get("distance_to_limit_risk"))
    distance_to_limit_atr = _num(fillability.get("distance_to_limit_atr"))
    limit_fill_probability = _num(
        _first_present_value(
            fillability.get("fill_probability"),
            fillability.get("probability"),
            metadata.get("limit_fillability_probability"),
            metadata.get("predecision_limit_fillability_probability"),
            metadata.get("limit_fill_probability"),
        )
    )
    action = _lower(config.predecision_passive_limit_too_close_guard_action, "block")
    if action not in {"block", "cap"}:
        action = "block"
    missing_fields_action = _lower(
        config.predecision_passive_limit_too_close_missing_fields_action,
        "no_block",
    )
    if missing_fields_action not in {"no_block", "block"}:
        missing_fields_action = "no_block"
    symbol_allowlist = config.predecision_passive_limit_too_close_symbol_allowlist
    framework_allowlist = config.predecision_passive_limit_too_close_framework_allowlist
    symbol_key = _lower(candidate.symbol)
    framework_key = _lower(
        metadata.get("framework")
        or metadata.get("current_framework")
        or metadata.get("generation_rule")
        or metadata.get("origin_family")
    )
    primary_order_type = _lower(
        _first_present_value(
            metadata.get("would_primary_order_type"),
            metadata.get("primary_order_type"),
            metadata.get("package_execution_policy_primary_order_type"),
            metadata.get("selected_order_type_architecture"),
            "limit"
            if passive_limit_fillability_route_resolution.get(
                "guarded_market_fallback_policy_authorized"
            )
            else None,
        )
    )
    limit_marketable = fillability.get("limit_marketable_at_decision") is True
    fillability_available = bool(
        fillability.get("available") is True
        or any(
            key in fillability
            for key in (
                "distance_to_limit_risk",
                "distance_to_limit_atr",
                "fill_probability",
                "probability",
            )
        )
    )
    base = {
        "enabled": bool(config.predecision_passive_limit_too_close_guard_enabled),
        "status": (
            "disabled"
            if not config.predecision_passive_limit_too_close_guard_enabled
            else "not_applicable"
        ),
        "reason": None,
        "action": action,
        "risk_cap_applied": False,
        "risk_cap_pct": _round(
            max(0.0, config.predecision_passive_limit_too_close_risk_cap_pct)
        ),
        "candidate_id": candidate.candidate_id,
        "symbol": candidate.symbol,
        "framework": framework_key or None,
        "selector_action": selector_action,
        "package_open_reduced_authority_applies": package_open_reduced_authority_applies,
        "passive_limit_route_resolution_allowed": (
            passive_limit_fillability_route_resolution.get("allowed")
        ),
        "primary_order_type": primary_order_type or None,
        "limit_marketable_at_decision": limit_marketable,
        "predecision_limit_fillability": fillability,
        "distance_to_limit_risk": _round(distance_to_limit_risk),
        "distance_to_limit_atr": _round(distance_to_limit_atr),
        "limit_fill_probability": _round(limit_fill_probability),
        "min_distance_to_limit_risk": _round(
            config.predecision_passive_limit_too_close_min_distance_to_limit_risk
        ),
        "min_distance_to_limit_atr": _round(
            config.predecision_passive_limit_too_close_min_distance_to_limit_atr
        ),
        "max_limit_fill_probability": _round(
            config.predecision_passive_limit_too_close_max_limit_fill_probability
        ),
        "require_all_thresholds": bool(
            config.predecision_passive_limit_too_close_require_all_thresholds
        ),
        "triggered_conditions": [],
        "missing_fields": [],
        "symbol_allowlist": list(symbol_allowlist),
        "framework_allowlist": list(framework_allowlist),
        "source_boundary": "predecision_limit_fillability_no_elapsed_or_outcome_path",
        "outcome_fields_used": False,
        "live_broker_authority": False,
    }
    if not base["enabled"]:
        return base
    if selector_action != "open-reduced-risk":
        base["reason"] = "selector_action_not_open_reduced_risk"
        return base
    if candidate.action_intent not in NEW_RISK_ACTIONS:
        base["reason"] = "action_intent_not_new_risk"
        return base
    if not package_open_reduced_authority_applies:
        base["reason"] = "package_open_reduced_authority_not_applicable"
        return base
    if symbol_allowlist and symbol_key not in symbol_allowlist:
        base["reason"] = "symbol_not_in_allowlist"
        return base
    if framework_allowlist and framework_key not in framework_allowlist:
        base["reason"] = "framework_not_in_allowlist"
        return base
    if primary_order_type and "limit" not in primary_order_type:
        base["reason"] = "primary_order_type_not_limit"
        return base
    if limit_marketable:
        base["reason"] = "limit_marketable_at_decision_uses_marketable_guard"
        return base
    if not fillability_available:
        base["reason"] = "predecision_limit_fillability_unavailable"
        if missing_fields_action == "block":
            base["status"] = "blocked"
            base["triggered_conditions"] = ["predecision_limit_fillability_missing"]
        return base

    required_conditions: list[str] = []
    triggered_conditions: list[str] = []
    missing_fields: list[str] = []
    min_distance_risk = max(
        0.0,
        config.predecision_passive_limit_too_close_min_distance_to_limit_risk,
    )
    min_distance_atr = max(
        0.0,
        config.predecision_passive_limit_too_close_min_distance_to_limit_atr,
    )
    max_fill_probability = min(
        1.0,
        max(0.0, config.predecision_passive_limit_too_close_max_limit_fill_probability),
    )
    if min_distance_risk > 0.0:
        required_conditions.append("passive_limit_distance_to_limit_risk_below_floor")
        if distance_to_limit_risk is None:
            missing_fields.append("distance_to_limit_risk")
        elif distance_to_limit_risk < min_distance_risk:
            triggered_conditions.append(
                "passive_limit_distance_to_limit_risk_below_floor"
            )
    if min_distance_atr > 0.0:
        required_conditions.append("passive_limit_distance_to_limit_atr_below_floor")
        if distance_to_limit_atr is None:
            missing_fields.append("distance_to_limit_atr")
        elif distance_to_limit_atr < min_distance_atr:
            triggered_conditions.append(
                "passive_limit_distance_to_limit_atr_below_floor"
            )
    if max_fill_probability < 1.0:
        required_conditions.append("passive_limit_fill_probability_above_ceiling")
        if limit_fill_probability is None:
            missing_fields.append("limit_fill_probability")
        elif limit_fill_probability > max_fill_probability:
            triggered_conditions.append(
                "passive_limit_fill_probability_above_ceiling"
            )
    base["triggered_conditions"] = list(dict.fromkeys(triggered_conditions))
    base["missing_fields"] = list(dict.fromkeys(missing_fields))
    base["required_conditions"] = required_conditions
    if missing_fields and missing_fields_action == "block":
        base["status"] = "blocked"
        base["reason"] = "passive_limit_too_close_missing_predecision_fields"
        return base
    if config.predecision_passive_limit_too_close_require_all_thresholds:
        blocked = bool(
            required_conditions
            and not missing_fields
            and set(required_conditions).issubset(set(triggered_conditions))
        )
    else:
        blocked = bool(triggered_conditions)
    if blocked:
        base["status"] = "blocked"
        base["reason"] = "passive_limit_too_close_predecision_guard"
    else:
        base["status"] = "passed"
        base["reason"] = (
            "passive_limit_too_close_conditions_not_all_met"
            if config.predecision_passive_limit_too_close_require_all_thresholds
            else "passive_limit_too_close_conditions_not_met"
        )
    return base


def _target_r_from_predecision_geometry(
    *,
    side: Any,
    entry: Any,
    stop: Any,
    target: Any,
) -> float | None:
    entry_value = _num(entry)
    stop_value = _num(stop)
    target_value = _num(target)
    if entry_value is None or stop_value is None or target_value is None:
        return None
    risk_distance = abs(entry_value - stop_value)
    target_distance = abs(target_value - entry_value)
    if risk_distance <= 0.0 or target_distance <= 0.0:
        return None
    side_key = str(side or "").strip().upper()
    if side_key == "LONG" and target_value <= entry_value:
        return None
    if side_key == "SHORT" and target_value >= entry_value:
        return None
    return target_distance / risk_distance


def _scheduler_stop_hazard_target_r(
    *,
    candidate: "AllocatorCandidate",
    metadata: Mapping[str, Any],
    fillability: Mapping[str, Any],
) -> tuple[float | None, str | None]:
    geometry_contract = _mapping(metadata.get("geometry_contract"))
    target_destination = _mapping(geometry_contract.get("target_destination"))
    explicit_sources: tuple[tuple[str, Any], ...] = (
        ("predecision_limit_fillability.target_r", fillability.get("target_r")),
        ("predecision_limit_fillability.dynamic_target_r", fillability.get("dynamic_target_r")),
        ("predecision_limit_fillability.expected_target_r", fillability.get("expected_target_r")),
        ("predecision_limit_fillability.risk_reward_ratio", fillability.get("risk_reward_ratio")),
        ("predecision_limit_fillability.rr", fillability.get("rr")),
        ("metadata.target_r", metadata.get("target_r")),
        ("metadata.dynamic_target_r", metadata.get("dynamic_target_r")),
        ("metadata.expected_target_r", metadata.get("expected_target_r")),
        ("metadata.raw_target_r", metadata.get("raw_target_r")),
        ("metadata.policy_target_r", metadata.get("policy_target_r")),
        ("metadata.final_target_r", metadata.get("final_target_r")),
        ("metadata.gtos_vnext_dynamic_final_target_r", metadata.get("gtos_vnext_dynamic_final_target_r")),
        ("metadata.risk_reward_ratio", metadata.get("risk_reward_ratio")),
        ("metadata.rr", metadata.get("rr")),
        ("geometry_contract.final_target_r", geometry_contract.get("final_target_r")),
        ("geometry_contract.target_destination.final_target_r", target_destination.get("final_target_r")),
    )
    for source, raw in explicit_sources:
        value = _num(raw)
        if value is not None and value > 0.0:
            return value, source
    geometry_sources: tuple[tuple[str, Any, Any, Any], ...] = (
        (
            "metadata.entry_stop_take_profit_1",
            metadata.get("entry_price"),
            metadata.get("stop_loss"),
            _first_present_value(
                metadata.get("take_profit_1"),
                metadata.get("take_profit"),
                metadata.get("target_reference"),
                metadata.get("target_price"),
            ),
        ),
        (
            "predecision_limit_fillability.entry_stop_target",
            fillability.get("entry_price"),
            fillability.get("stop_loss"),
            _first_present_value(
                fillability.get("take_profit_1"),
                fillability.get("take_profit"),
                fillability.get("target_reference"),
                fillability.get("target_price"),
            ),
        ),
    )
    for source, entry, stop, target in geometry_sources:
        value = _target_r_from_predecision_geometry(
            side=candidate.side,
            entry=entry,
            stop=stop,
            target=target,
        )
        if value is not None and value > 0.0:
            return value, source
    return None, None


def _stop_hazard_pressure_component(
    *,
    value: float | None,
    floor: float,
    higher_is_risky: bool,
) -> float | None:
    if value is None or floor <= 0.0:
        return None
    if higher_is_risky:
        return _clamp(float(value) / floor, 0.0, 1.0)
    return _clamp(1.0 - (float(value) / floor), 0.0, 1.0)


def _scheduler_predecision_stop_hazard_guard(
    *,
    candidate: "AllocatorCandidate",
    config: SchedulerV4Config,
    selector_action: str,
) -> dict[str, Any]:
    """Causal stop-hazard diagnostic/cap from predecision geometry only."""

    metadata = candidate.metadata if isinstance(candidate.metadata, Mapping) else {}
    fillability = dict(_candidate_predecision_limit_fillability(candidate))
    unit_risk = _num(
        _first_present_value(
            fillability.get("unit_risk"),
            metadata.get("unit_risk"),
            metadata.get("risk_unit"),
        )
    )
    atr14 = _num(
        _first_present_value(
            fillability.get("atr14"),
            fillability.get("atr"),
            metadata.get("atr14"),
            metadata.get("atr"),
        )
    )
    unit_risk_atr = (
        float(unit_risk) / float(atr14)
        if unit_risk is not None and atr14 not in (None, 0.0)
        else None
    )
    distance_to_limit_risk = _num(fillability.get("distance_to_limit_risk"))
    distance_to_limit_atr = _num(fillability.get("distance_to_limit_atr"))
    limit_fill_probability = _num(
        _first_present_value(
            fillability.get("fill_probability"),
            fillability.get("probability"),
            metadata.get("limit_fillability_probability"),
            metadata.get("predecision_limit_fillability_probability"),
            metadata.get("limit_fill_probability"),
        )
    )
    target_r, target_r_source = _scheduler_stop_hazard_target_r(
        candidate=candidate,
        metadata=metadata,
        fillability=fillability,
    )
    action = _lower(config.predecision_stop_hazard_guard_action, "penalize")
    if action not in {"penalize", "cap", "block"}:
        action = "penalize"
    missing_fields_action = _lower(
        config.predecision_stop_hazard_missing_fields_action,
        "no_block",
    )
    if missing_fields_action not in {"no_block", "block"}:
        missing_fields_action = "no_block"
    symbol_allowlist = config.predecision_stop_hazard_symbol_allowlist
    framework_allowlist = config.predecision_stop_hazard_framework_allowlist
    symbol_key = _lower(candidate.symbol)
    framework_key = _lower(
        metadata.get("framework")
        or metadata.get("current_framework")
        or metadata.get("generation_rule")
        or metadata.get("origin_family")
    )
    base = {
        "enabled": bool(config.predecision_stop_hazard_guard_enabled),
        "status": (
            "disabled"
            if not config.predecision_stop_hazard_guard_enabled
            else "not_applicable"
        ),
        "reason": None,
        "action": action,
        "candidate_id": candidate.candidate_id,
        "symbol": candidate.symbol,
        "framework": framework_key or None,
        "selector_action": selector_action,
        "action_intent": candidate.action_intent,
        "predecision_limit_fillability": fillability,
        "unit_risk": _round(unit_risk),
        "atr14": _round(atr14),
        "unit_risk_atr": _round(unit_risk_atr),
        "distance_to_limit_risk": _round(distance_to_limit_risk),
        "distance_to_limit_atr": _round(distance_to_limit_atr),
        "limit_fill_probability": _round(limit_fill_probability),
        "target_r": _round(target_r),
        "target_r_source": target_r_source,
        "min_unit_risk_atr": _round(
            config.predecision_stop_hazard_min_unit_risk_atr
        ),
        "max_distance_to_limit_risk": _round(
            config.predecision_stop_hazard_max_distance_to_limit_risk
        ),
        "min_limit_fill_probability": _round(
            config.predecision_stop_hazard_min_limit_fill_probability
        ),
        "min_target_r": _round(config.predecision_stop_hazard_min_target_r),
        "pressure_enabled": bool(config.predecision_stop_hazard_pressure_enabled),
        "pressure_min_score": _round(
            config.predecision_stop_hazard_pressure_min_score
        ),
        "pressure_score": None,
        "pressure_components": {},
        "pressure_weights": {
            "distance": _round(config.predecision_stop_hazard_pressure_distance_weight),
            "fill": _round(config.predecision_stop_hazard_pressure_fill_weight),
            "target": _round(config.predecision_stop_hazard_pressure_target_weight),
        },
        "pressure_triggered": False,
        "pressure_score_triggered": False,
        "pressure_requires_base_fragility": bool(
            config.predecision_stop_hazard_pressure_requires_base_fragility
        ),
        "pressure_suppressed_reason": None,
        "pressure_required_conditions": [],
        "pressure_triggered_conditions": [],
        "pressure_missing_fields": [],
        "require_all_thresholds": bool(
            config.predecision_stop_hazard_require_all_thresholds
        ),
        "score_penalty": 0.0,
        "risk_cap_applied": False,
        "risk_cap_pct": _round(max(0.0, config.predecision_stop_hazard_risk_cap_pct)),
        "triggered_conditions": [],
        "required_conditions": [],
        "missing_fields": [],
        "symbol_allowlist": list(symbol_allowlist),
        "framework_allowlist": list(framework_allowlist),
        "source_boundary": "predecision_limit_fillability_geometry_no_outcome_path",
        "outcome_fields_used": False,
        "live_broker_authority": False,
    }
    if not base["enabled"]:
        return base
    if candidate.action_intent not in NEW_RISK_ACTIONS:
        base["reason"] = "action_intent_not_new_risk"
        return base
    if symbol_allowlist and symbol_key not in symbol_allowlist:
        base["reason"] = "symbol_not_in_allowlist"
        return base
    if framework_allowlist and framework_key not in framework_allowlist:
        base["reason"] = "framework_not_in_allowlist"
        return base

    required_conditions: list[str] = []
    triggered_conditions: list[str] = []
    missing_fields: list[str] = []
    min_unit_risk_atr = max(0.0, config.predecision_stop_hazard_min_unit_risk_atr)
    max_distance_risk = max(
        0.0,
        config.predecision_stop_hazard_max_distance_to_limit_risk,
    )
    min_fill_probability = min(
        1.0,
        max(0.0, config.predecision_stop_hazard_min_limit_fill_probability),
    )
    min_target_r = max(0.0, config.predecision_stop_hazard_min_target_r)
    if min_unit_risk_atr > 0.0:
        required_conditions.append("unit_risk_atr_below_floor")
        if unit_risk_atr is None:
            missing_fields.append("unit_risk_atr")
        elif unit_risk_atr < min_unit_risk_atr:
            triggered_conditions.append("unit_risk_atr_below_floor")
    if math.isfinite(max_distance_risk) and max_distance_risk > 0.0:
        required_conditions.append("distance_to_limit_risk_below_ceiling")
        if distance_to_limit_risk is None:
            missing_fields.append("distance_to_limit_risk")
        elif distance_to_limit_risk < max_distance_risk:
            triggered_conditions.append("distance_to_limit_risk_below_ceiling")
    if min_fill_probability > 0.0:
        required_conditions.append("limit_fill_probability_above_floor")
        if limit_fill_probability is None:
            missing_fields.append("limit_fill_probability")
        elif limit_fill_probability >= min_fill_probability:
            triggered_conditions.append("limit_fill_probability_above_floor")
    pressure_required_conditions: list[str] = []
    pressure_triggered_conditions: list[str] = []
    pressure_missing_fields: list[str] = []
    pressure_hazard = False
    if config.predecision_stop_hazard_pressure_enabled:
        pressure_required_conditions = [
            "distance_to_limit_risk_below_ceiling",
            "limit_fill_probability_above_floor",
            "target_r_above_floor",
        ]
        if distance_to_limit_risk is None:
            pressure_missing_fields.append("distance_to_limit_risk")
        elif distance_to_limit_risk <= max_distance_risk:
            pressure_triggered_conditions.append("distance_to_limit_risk_below_ceiling")
        if limit_fill_probability is None:
            pressure_missing_fields.append("limit_fill_probability")
        elif limit_fill_probability >= min_fill_probability:
            pressure_triggered_conditions.append("limit_fill_probability_above_floor")
        if target_r is None:
            pressure_missing_fields.append("target_r")
        elif target_r >= min_target_r:
            pressure_triggered_conditions.append("target_r_above_floor")

        pressure_components = {
            "distance": _stop_hazard_pressure_component(
                value=distance_to_limit_risk,
                floor=max_distance_risk,
                higher_is_risky=False,
            ),
            "fill": _stop_hazard_pressure_component(
                value=limit_fill_probability,
                floor=min_fill_probability,
                higher_is_risky=True,
            ),
            "target": _stop_hazard_pressure_component(
                value=target_r,
                floor=min_target_r,
                higher_is_risky=True,
            ),
        }
        weights = {
            "distance": max(
                0.0, config.predecision_stop_hazard_pressure_distance_weight
            ),
            "fill": max(0.0, config.predecision_stop_hazard_pressure_fill_weight),
            "target": max(0.0, config.predecision_stop_hazard_pressure_target_weight),
        }
        usable_weight = sum(
            weight
            for key, weight in weights.items()
            if pressure_components.get(key) is not None
        )
        pressure_score = (
            sum(
                float(pressure_components[key]) * weight
                for key, weight in weights.items()
                if pressure_components.get(key) is not None
            )
            / usable_weight
            if usable_weight > 0.0
            else None
        )
        base["pressure_components"] = {
            key: _round(value) for key, value in pressure_components.items()
        }
        base["pressure_score"] = _round(pressure_score)
        base["pressure_required_conditions"] = pressure_required_conditions
        base["pressure_triggered_conditions"] = list(
            dict.fromkeys(pressure_triggered_conditions)
        )
        base["pressure_missing_fields"] = list(dict.fromkeys(pressure_missing_fields))
        pressure_score_triggered = bool(
            not pressure_missing_fields
            and set(pressure_required_conditions).issubset(
                set(pressure_triggered_conditions)
            )
            and pressure_score is not None
            and pressure_score >= max(
                0.0,
                config.predecision_stop_hazard_pressure_min_score,
            )
        )
        base_fragility_triggered = "unit_risk_atr_below_floor" in triggered_conditions
        pressure_hazard = bool(
            pressure_score_triggered
            and (
                not config.predecision_stop_hazard_pressure_requires_base_fragility
                or base_fragility_triggered
            )
        )
        base["pressure_score_triggered"] = pressure_score_triggered
        if pressure_score_triggered and not pressure_hazard:
            base["pressure_suppressed_reason"] = (
                "stop_hazard_pressure_requires_base_fragility"
            )
        if pressure_hazard:
            triggered_conditions.append("stop_hazard_pressure_score_above_floor")
    base["triggered_conditions"] = list(dict.fromkeys(triggered_conditions))
    base["missing_fields"] = list(dict.fromkeys(missing_fields))
    base["required_conditions"] = required_conditions
    base["pressure_triggered"] = pressure_hazard
    if missing_fields and missing_fields_action == "block":
        base["status"] = "blocked"
        base["reason"] = "predecision_stop_hazard_missing_fields"
        return base
    if config.predecision_stop_hazard_require_all_thresholds:
        hazard = bool(
            required_conditions
            and not missing_fields
            and set(required_conditions).issubset(set(triggered_conditions))
        )
    else:
        hazard = bool(triggered_conditions)
    hazard = bool(hazard or pressure_hazard)
    if not hazard:
        base["status"] = "passed"
        base["reason"] = (
            "predecision_stop_hazard_conditions_not_all_met"
            if config.predecision_stop_hazard_require_all_thresholds
            else "predecision_stop_hazard_conditions_not_met"
        )
        return base
    if action == "block":
        base["status"] = "blocked"
    elif action == "cap":
        base["status"] = "capped"
        base["score_penalty"] = _round(
            max(0.0, config.predecision_stop_hazard_score_penalty)
        )
    else:
        base["status"] = "penalized"
        base["score_penalty"] = _round(
            max(0.0, config.predecision_stop_hazard_score_penalty)
        )
    base["reason"] = "predecision_stop_hazard_guard"
    return base


def _candidate_option(
    candidate: AllocatorCandidate,
    snapshot: ExposureSnapshot,
    config: SchedulerV4Config,
) -> AllocatorOption:
    ev_r, value_source = _candidate_value(candidate)
    probability = candidate.probability
    if probability is None:
        probability = _clamp(0.50 + ev_r / 4.0, 0.05, 0.95)
    confidence = _clamp(candidate.confidence if candidate.confidence is not None else 0.55, 0.0, 1.0)
    uncertainty = _clamp(candidate.uncertainty if candidate.uncertainty is not None else 0.35, 0.0, 1.0)
    fill_probability_missing = candidate.fill_probability is None
    fill_probability = _clamp(
        candidate.fill_probability if candidate.fill_probability is not None else 0.25,
        0.0,
        1.0,
    )
    entry_quality_fill_probability = fill_probability
    execution_fill_probability, execution_fill_probability_source = (
        _candidate_execution_fill_probability(
            candidate,
            fallback=None,
            decision_time_utc=snapshot.asof_utc,
        )
    )
    candidate_execution_fillability_contract = (
        _atomic_predecision_execution_fillability_claim(
            {
                **dict(_mapping(candidate.metadata)),
                "decision_time_utc": _first_present_value(
                    candidate.decision_time_utc,
                    _mapping(candidate.metadata).get("decision_time_utc"),
                    snapshot.asof_utc,
                ),
            }
        )
    )
    execution_fill_probability_source_time_utc = _text(
        candidate_execution_fillability_contract.get("source_time_utc")
    )
    execution_fill_probability_source_boundary = _text(
        candidate_execution_fillability_contract.get("source_boundary")
    )
    execution_fill_probability_for_scoring = (
        execution_fill_probability
        if execution_fill_probability is not None
        else 0.0
    )
    execution_fill_probability_for_gate = (
        execution_fill_probability
        if execution_fill_probability is not None
        else 0.0
    )
    execution_fill_probability_scoring_fallback_applied = False
    execution_fill_probability_scoring_zero_fail_closed_applied = (
        execution_fill_probability is None
    )
    completeness = source_completeness_score(
        candidate.source_completeness,
        candidate.source_completeness_status,
    )
    source_completeness_missing = (
        candidate.source_completeness is None
        and not str(candidate.source_completeness_status or "").strip()
    )
    cost_total = sum(
        value
        for value in (
            candidate.cost_r or 0.0,
            candidate.slippage_r or 0.0,
            candidate.swap_r or 0.0,
        )
    )
    score_cost_total = 0.0 if value_source == "decision_time_expected_net_r" else cost_total
    confluence = _lower(candidate.confluence_action)
    confluence_strength = _clamp(candidate.confluence_strength or 0.0, -1.0, 1.0)
    confluence_confidence = _clamp(
        candidate.confluence_confidence if candidate.confluence_confidence is not None else confidence,
        0.0,
        1.0,
    )
    confluence_reliability = _clamp(
        candidate.confluence_reliability
        if candidate.confluence_reliability is not None
        else 0.50,
        0.0,
        1.0,
    )
    confluence_component = 0.0
    if confluence == "follow":
        confluence_component = 0.12 * max(0.0, confluence_strength) * confluence_confidence
    elif confluence == "avoid":
        confluence_component = -0.45 * max(0.25, abs(confluence_strength))
    elif confluence == "mixed":
        confluence_component = -0.10 * max(0.25, abs(confluence_strength))

    missing_penalty = min(0.40, 0.08 * len(candidate.missing_sources))
    freshness_penalty = 0.0
    if candidate.source_freshness_seconds is not None:
        freshness_penalty = min(0.20, max(0.0, candidate.source_freshness_seconds - 900.0) / 7200.0)
    expected_net_r = (
        candidate.expected_net_r
        if candidate.expected_net_r is not None
        else ev_r - cost_total
    )
    selector_action = _lower(candidate.selector_action)
    selector_reason = _lower(candidate.selector_reason)
    candidate_metadata = _mapping(candidate.metadata)
    candidate_metadata_quality = _mapping(
        candidate_metadata.get("candidate_decision_quality")
    )
    candidate_signed_payload = _mapping(
        candidate_metadata.get("package_new_entry_authority_payload")
    )
    expected_net_r_semantics = _text(
        _first_present_value(
            candidate_signed_payload.get("expected_net_r_semantics"),
            candidate_metadata_quality.get("expected_net_r_semantics"),
            candidate_metadata.get("expected_net_r_semantics"),
            candidate_metadata.get("selected_policy_expected_net_r_semantics"),
            LEGACY_UNTYPED_EXPECTED_VALUE,
        )
    )
    expected_net_r_semantics_source = _text(
        _first_present_value(
            candidate_signed_payload.get("expected_net_r_semantics_source"),
            candidate_metadata_quality.get("expected_net_r_semantics_source"),
            candidate_metadata.get("expected_net_r_semantics_source"),
            LEGACY_UNTYPED_EXPECTED_VALUE_SOURCE,
        )
    )
    matched_member_axis_ids = _canonical_matched_member_axis_ids(candidate_metadata)
    candidate_decision_time_utc = _text(
        candidate.decision_time_utc
        or candidate_metadata.get("decision_time_utc")
        or candidate_metadata.get("window_time_utc")
        or candidate_metadata.get("candle_close_utc")
        or candidate_metadata.get("source_candle_time_utc")
    )
    explicit_candidate_instance_key = _text(
        candidate_metadata.get("canonical_replay_candidate_instance_key")
    )
    candidate_instance_key = explicit_candidate_instance_key
    synthesized_candidate_instance_key = False
    if not candidate_instance_key and candidate.candidate_id and candidate_decision_time_utc:
        candidate_instance_key = f"{candidate.candidate_id}@@{candidate_decision_time_utc}"
        synthesized_candidate_instance_key = True
    explicit_source_bound_candidate_instance_key = _text(
        candidate_metadata.get("source_bound_replay_candidate_instance_key")
    )
    source_bound_candidate_instance_key = explicit_source_bound_candidate_instance_key
    synthesized_source_bound_candidate_instance_key = False
    if not source_bound_candidate_instance_key and candidate_instance_key:
        source_bound_candidate_instance_key = candidate_instance_key
        synthesized_source_bound_candidate_instance_key = True
    explicit_candidate_identity_status = _text(
        candidate_metadata.get("candidate_instance_identity_status")
    )
    candidate_identity_status = explicit_candidate_identity_status
    if not candidate_identity_status:
        candidate_identity_status = (
            "synthetic_not_signable"
            if (
                synthesized_candidate_instance_key
                or synthesized_source_bound_candidate_instance_key
            )
            else "missing_candidate_or_decision_time"
        )
    signable_candidate_identity_status = explicit_candidate_identity_status
    if not signable_candidate_identity_status and (
        synthesized_candidate_instance_key or synthesized_source_bound_candidate_instance_key
    ):
        signable_candidate_identity_status = "synthetic_not_signable"
    candidate_quality_field_sources = _mapping(
        candidate.metadata.get("candidate_decision_quality_field_sources")
    )
    selected_policy_expected_net_calibration = _selected_policy_expected_net_calibration(
        candidate,
        candidate_quality_field_sources,
    )
    selected_policy_expected_net_calibrated = bool(
        selected_policy_expected_net_calibration.get("calibrated")
    )
    selector_reduce_risk_new_entry = (
        selector_action in REDUCED_RISK_NEW_ENTRY_SELECTOR_ACTIONS
        and candidate.action_intent in NEW_RISK_ACTIONS
    )
    open_reduced_selected_policy_calibration_required = bool(
        selector_reduce_risk_new_entry
        and selector_action == "open-reduced-risk"
        and (
            config.selector_reduce_risk_open_reduced_expected_net_policy_calibration_required
            or selector_reason in PACKAGE_REDUCE_RISK_NUMERIC_REASONS
        )
    )
    selected_policy_for_expected_net = _lower(
        selected_policy_expected_net_calibration.get("selected_policy")
    )
    selected_policy_expected_net_calibration_required_for_new_risk = bool(
        config.selected_policy_expected_net_calibration_required_for_new_risk
        and candidate.action_intent in NEW_RISK_ACTIONS
        and selected_policy_for_expected_net
        and selected_policy_for_expected_net != "unspecified_expected_net_r_policy"
    )
    selected_policy_expected_net_calibration_required_for_execution = bool(
        open_reduced_selected_policy_calibration_required
        or selected_policy_expected_net_calibration_required_for_new_risk
    )
    selected_policy_expected_net_calibration_failure = bool(
        selected_policy_expected_net_calibration_required_for_execution
        and not selected_policy_expected_net_calibrated
    )
    numeric_disagreement_reduce_risk_new_entry = bool(
        selector_reduce_risk_new_entry
        and selector_action in {"reduce-risk", "open-reduced-risk"}
        and (
            (
                selector_action == "reduce-risk"
                and (
                    selector_reason in PACKAGE_REDUCE_RISK_NUMERIC_REASONS
                    or "numeric_confluence_structured_disagreement" in selector_reason
                    or "numeric_disagreement" in selector_reason
                )
            )
            or (
                selector_action == "open-reduced-risk"
                and selector_reason
                == "ultimate_candidate_package_numeric_disagreement_open_reduced_risk"
            )
        )
    )
    router_refusal_reduced_risk_new_entry = bool(
        selector_reduce_risk_new_entry
        and selector_reason in ROUTER_REFUSAL_REDUCED_RISK_SELECTOR_REASONS
    )
    selector_reduce_risk_hard_block_reason = ""
    if selector_reduce_risk_new_entry:
        if selector_action == "reduce-risk":
            selector_reduce_risk_hard_block_reason = (
                selector_reason or "plain_reduce_risk_new_entry_requires_explicit_open_authority"
            )
        elif selector_reason in config.selector_reduce_risk_new_entry_hard_block_reasons:
            selector_reduce_risk_hard_block_reason = selector_reason
    selector_reduce_risk_penalty = 0.0
    if (
        config.selector_reduce_risk_new_entry_penalty_enabled
        and selector_reduce_risk_new_entry
    ):
        selector_reduce_risk_penalty = config.selector_reduce_risk_new_entry_base_penalty
        if "router_refusal" in selector_reason:
            selector_reduce_risk_penalty = max(
                selector_reduce_risk_penalty,
                config.selector_reduce_risk_router_refusal_penalty,
            )
        elif (
            selector_reason == "numeric_confluence_structured_disagreement"
            or selector_reason
            == "ultimate_candidate_package_numeric_disagreement_open_reduced_risk"
        ):
            selector_reduce_risk_penalty = max(
                selector_reduce_risk_penalty,
                config.selector_reduce_risk_numeric_disagreement_penalty,
            )
    selector_reduce_risk_quality_failures: list[str] = []
    if (
        config.selector_reduce_risk_new_entry_quality_gate_enabled
        and selector_reduce_risk_new_entry
    ):
        if expected_net_r < config.selector_reduce_risk_new_entry_min_expected_net_r:
            selector_reduce_risk_quality_failures.append("expected_net_r")
        if probability < config.selector_reduce_risk_new_entry_min_probability:
            selector_reduce_risk_quality_failures.append("probability")
        if (
            execution_fill_probability_for_gate
            < config.selector_reduce_risk_new_entry_min_fill_probability
        ):
            selector_reduce_risk_quality_failures.append("fill_probability")
        if completeness < config.selector_reduce_risk_new_entry_min_source_completeness:
            selector_reduce_risk_quality_failures.append("source_completeness")
        if (
            selected_policy_expected_net_calibration_failure
        ):
            selector_reduce_risk_quality_failures.append(
                "selected_policy_expected_net_calibration"
            )
    scheduler_quality_failures: list[str] = []
    if (
        config.dynamic_budget_quality_gate_enabled
        and candidate.action_intent in NEW_RISK_ACTIONS
    ):
        if expected_net_r < config.dynamic_budget_min_expected_net_r:
            scheduler_quality_failures.append(
                "expected_net_r_below_dynamic_allocator_floor"
            )
        if probability < config.dynamic_budget_min_probability:
            scheduler_quality_failures.append(
                "probability_below_dynamic_allocator_floor"
            )
        if (
            execution_fill_probability_for_gate
            < config.dynamic_budget_min_fill_probability
        ):
            scheduler_quality_failures.append(
                "fill_probability_below_dynamic_allocator_floor"
            )
        if completeness < config.dynamic_budget_min_source_completeness:
            scheduler_quality_failures.append(
                "source_completeness_below_dynamic_allocator_floor"
            )
        if selected_policy_expected_net_calibration_failure:
            scheduler_quality_failures.append(
                "selected_policy_expected_net_calibration_missing"
            )
    opening_window_active = _truthy(
        candidate.metadata.get("dynamic_budget_opening_window_active")
        if "dynamic_budget_opening_window_active" in candidate.metadata
        else candidate.metadata.get("opening_window_active")
    )
    if (
        config.dynamic_budget_opening_window_quality_floor_enabled
        and opening_window_active
        and candidate.action_intent in NEW_RISK_ACTIONS
    ):
        if expected_net_r < config.dynamic_budget_opening_window_min_expected_net_r:
            scheduler_quality_failures.append(
                "opening_window_expected_net_r_below_quality_floor"
            )
        if probability < config.dynamic_budget_opening_window_min_probability:
            scheduler_quality_failures.append(
                "opening_window_probability_below_quality_floor"
            )
    if (
        selected_policy_expected_net_calibration_failure
        and "selected_policy_expected_net_calibration_missing"
        not in scheduler_quality_failures
    ):
        scheduler_quality_failures.append(
            "selected_policy_expected_net_calibration_missing"
        )

    broker_cost_rank = _candidate_broker_cost_rank_diagnostic(candidate)
    execution_authority_vetoes = _candidate_execution_authority_vetoes(
        candidate,
        broker_cost_rank,
        source_completeness_floor=(
            config.selector_reduce_risk_package_fill_floor_min_source_completeness
        ),
        expected_net_r=expected_net_r,
        probability=probability,
        fill_probability=execution_fill_probability,
        source_completeness=completeness,
        source_completeness_status=candidate.source_completeness_status,
    )
    metadata_effective_admission_count = _first_num(
        candidate_metadata,
        "ultimate_package_effective_admission_count",
        "ultimate_package_admission_sleeve_match_count",
    )
    metadata_effective_matched_count = _first_num(
        candidate_metadata,
        "ultimate_package_effective_matched_count",
        "ultimate_package_matched_sleeve_count",
    )
    package_admission_count = (
        metadata_effective_admission_count
        if metadata_effective_admission_count is not None
        else
        candidate.ultimate_package_effective_admission_count
        if candidate.ultimate_package_effective_admission_count is not None
        else candidate.ultimate_package_admission_sleeve_match_count
        or 0.0
    )
    package_matched_count = (
        metadata_effective_matched_count
        if metadata_effective_matched_count is not None
        else
        candidate.ultimate_package_effective_matched_count
        if candidate.ultimate_package_effective_matched_count is not None
        else candidate.ultimate_package_matched_sleeve_count
        or 0.0
    )
    package_role = _lower(
        candidate_metadata.get("ultimate_package_role_disposition")
        or candidate.ultimate_package_role_disposition
    )
    package_role_executable = package_role not in PACKAGE_HOLD_ROLE_DISPOSITIONS
    explicit_package_replay_executable_allowed = _truthy(
        _first_present_value(
            candidate_metadata.get("package_replay_executable_candidate_use_allowed"),
            candidate_metadata.get("replay_candidate_use_allowed_now"),
        )
    )
    package_source_bound_diagnostic_present = (
        _candidate_package_source_bound_diagnostic_present(candidate)
    )
    package_source_bound_executable_present = (
        _candidate_package_source_bound_executable_present(candidate)
    )
    explicit_package_replay_executable_reason = _text(
        candidate_metadata.get("package_replay_executable_candidate_use_allowed_reason")
        or candidate_metadata.get("replay_candidate_use_allowed_now_reason")
    )
    source_bound_router_refusal_self_lock_rederived = (
        _candidate_source_bound_router_refusal_signed_self_lock_can_rederive(
            candidate,
            explicit_package_replay_executable_reason,
        )
    )
    package_source_bound_executable_for_authority = bool(
        package_source_bound_executable_present
        or source_bound_router_refusal_self_lock_rederived
    )
    (
        package_executable_authority_allowed,
        package_executable_authority_reason,
        package_executable_authority_source,
    ) = _candidate_package_executable_authority(
        candidate,
        broker_cost_rank,
        source_bound_executable_present=package_source_bound_executable_for_authority,
        source_completeness_floor=(
            config.selector_reduce_risk_package_fill_floor_min_source_completeness
        ),
        expected_net_r=expected_net_r,
        probability=probability,
        fill_probability=execution_fill_probability,
        source_completeness=completeness,
        source_completeness_status=candidate.source_completeness_status,
    )
    package_source_bound_allowed = bool(
        package_source_bound_executable_for_authority
    )
    package_admission_allowed = bool(
        package_source_bound_allowed
        and package_executable_authority_allowed
        and (
            (package_admission_count > 0.0 and package_matched_count > 0.0)
            or explicit_package_replay_executable_allowed
        )
        and package_role_executable
    )
    package_replay_executable_allowed = bool(
        package_source_bound_executable_for_authority
        and package_executable_authority_allowed
        and package_role_executable
    )
    selector_open_reduced_package_authority = _mapping(
        candidate.metadata.get("ultimate_candidate_package_open_reduced_risk_authority")
    )
    selector_open_reduced_package_authority = _normalize_soft_open_reduced_authority(
        selector_open_reduced_package_authority,
        selector_reason,
    )
    (
        selector_open_reduced_package_current_config_allowed,
        selector_open_reduced_package_config_block_reason,
    ) = _package_open_reduced_authority_current_config_status(
        config,
        selector_open_reduced_package_authority,
        selector_reason,
    )
    selector_open_reduced_package_soft_override_allowed = (
        _package_open_reduced_soft_admission_override_allowed(
            selector_open_reduced_package_authority
        )
    )
    if not selector_open_reduced_package_current_config_allowed:
        selector_open_reduced_package_soft_override_allowed = False
    selector_open_reduced_package_authority_allowed = bool(
        selector_open_reduced_package_authority.get("allowed")
        or selector_open_reduced_package_soft_override_allowed
    )
    if not selector_open_reduced_package_current_config_allowed:
        selector_open_reduced_package_authority_allowed = False
    selector_reduce_risk_package_authority = _mapping(
        candidate.metadata.get("ultimate_candidate_package_reduce_risk_authority")
        or candidate.metadata.get("ultimate_candidate_package_reduced_risk_authority")
    )
    selector_reduce_risk_current_authority_row = {
        **dict(candidate_metadata),
        "candidate_id": candidate.candidate_id,
        "candidate_id_source": candidate.candidate_id_source,
        "decision_time_utc": candidate_decision_time_utc,
        "canonical_replay_candidate_instance_key": candidate_instance_key,
        "source_bound_replay_candidate_instance_key": (
            source_bound_candidate_instance_key
        ),
        "candidate_instance_identity_status": candidate_identity_status,
        "execution_fill_probability": _round(execution_fill_probability),
        "execution_fill_probability_source": execution_fill_probability_source,
        "execution_fill_probability_source_time_utc": (
            execution_fill_probability_source_time_utc
        ),
        "execution_fill_probability_source_boundary": (
            execution_fill_probability_source_boundary
        ),
        "ultimate_candidate_package_reduce_risk_authority": dict(
            selector_reduce_risk_package_authority
        ),
    }
    selector_reduce_risk_exact_member_axis_atomic_authority_proven = (
        _exact_member_axis_atomic_authority_proven(
            selector_reduce_risk_current_authority_row,
            selector_reduce_risk_package_authority,
            require_signed_claim=True,
        )
    )
    (
        selector_reduce_risk_package_current_config_allowed,
        selector_reduce_risk_package_config_block_reason,
    ) = _package_reduce_risk_authority_current_config_status(
        config,
        selector_reduce_risk_package_authority,
        selector_reason,
        exact_member_axis_atomic_authority_proven=(
            selector_reduce_risk_exact_member_axis_atomic_authority_proven
        ),
    )
    selector_reduce_risk_package_authority_allowed = bool(
        selector_reduce_risk_package_authority.get("allowed")
    )
