            candidate.metadata.get("same_side_pending_ids"),
            candidate_metadata_decision_inputs.get("same_side_pending_order_ids"),
            candidate_metadata_decision_inputs.get("same_side_pending_ids"),
            same_symbol_replay_exposure_context.get("same_side_pending_order_ids"),
